import React from "react";

/**
 * AnswerKeyEditor — inline editor for a question's correct answers.
 *
 * Rendered inside Preview components when the teacher is in regrade mode
 * (isRegrade && reviewMode) so they can fix a wrong or too-strict answer key.
 *
 * Modes:
 *   "single"      – one text input bound to correctAnswers[0]
 *   "multi-blank" – N inputs, one per slot (preserves " / " alternatives verbatim)
 *   "bag-pool"    – variable-length list with add/remove rows (Correction, Underline flat)
 *   "sub"         – one input per subQuestion (Underline subQuestions, CompleteSentences w/ subs)
 *
 * onChange contract:
 *   single / multi-blank:  onChange({ correctAnswers: string[] })
 *   bag-pool:              onChange({ correctAnswers: string[] })
 *   sub:                   onChange({ subQuestions: updatedSubQuestionsArray })
 *
 * NOTE: Do not split " / " alternatives inside the editor.  normalizeAnswer.js
 * handles that at grade time.  Storing "go / went" verbatim in Firestore is correct.
 */
const inputStyle = {
  border: "2px solid #f59e0b",
  borderRadius: 4,
  padding: "2px 6px",
  fontSize: "0.85em",
  fontFamily: "inherit",
  background: "#fffbeb",
  color: "#78350f",
  minWidth: 80,
  outline: "none",
};

const labelStyle = {
  fontSize: "0.72em",
  fontWeight: 700,
  color: "#b45309",
  textTransform: "uppercase",
  letterSpacing: "0.05em",
  marginBottom: 4,
  display: "block",
};

const wrapStyle = {
  marginTop: 6,
  padding: "6px 8px",
  background: "#fef3c7",
  border: "1px dashed #f59e0b",
  borderRadius: 4,
};

// ─── single mode ──────────────────────────────────────────────────────────────
function SingleEditor({ value, onChange }) {
  const current = Array.isArray(value) ? (value[0] ?? "") : (value ?? "");
  return (
    <div style={wrapStyle}>
      <span style={labelStyle}>Edit answer key</span>
      <input
        style={inputStyle}
        value={current}
        onChange={(e) => onChange({ correctAnswers: [e.target.value] })}
        onClick={(e) => e.stopPropagation()}
      />
    </div>
  );
}

// ─── multi-blank mode ─────────────────────────────────────────────────────────
function MultiBlankEditor({ value, onChange }) {
  const slots = Array.isArray(value) ? value : [];
  return (
    <div style={wrapStyle}>
      <span style={labelStyle}>Edit answer key</span>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 4 }}>
        {slots.map((slot, i) => (
          <input
            key={i}
            style={{ ...inputStyle, minWidth: 70 }}
            value={slot ?? ""}
            onChange={(e) => {
              const next = slots.map((s, j) => (j === i ? e.target.value : s));
              onChange({ correctAnswers: next });
            }}
            onClick={(e) => e.stopPropagation()}
          />
        ))}
      </div>
    </div>
  );
}

// ─── bag-pool mode (Correction, Underline flat) ───────────────────────────────
function BagPoolEditor({ value, onChange }) {
  const pool = Array.isArray(value) ? value : [];
  const update = (i, val) => {
    const next = pool.map((s, j) => (j === i ? val : s));
    onChange({ correctAnswers: next });
  };
  const add = () => onChange({ correctAnswers: [...pool, ""] });
  const remove = (i) => {
    const next = pool.filter((_, j) => j !== i);
    onChange({ correctAnswers: next });
  };

  return (
    <div style={wrapStyle}>
      <span style={labelStyle}>Edit answer key (accepted answers)</span>
      {pool.map((item, i) => (
        <div key={i} style={{ display: "flex", alignItems: "center", gap: 4, marginBottom: 3 }}>
          <input
            style={{ ...inputStyle, flex: 1 }}
            value={item ?? ""}
            onChange={(e) => update(i, e.target.value)}
            onClick={(e) => e.stopPropagation()}
          />
          <button
            style={{ fontSize: "0.75em", padding: "1px 5px", cursor: "pointer", color: "#b91c1c", border: "1px solid #fca5a5", borderRadius: 3, background: "#fff1f2" }}
            onClick={(e) => { e.stopPropagation(); remove(i); }}
            title="Remove"
          >✕</button>
        </div>
      ))}
      <button
        style={{ fontSize: "0.75em", padding: "2px 8px", cursor: "pointer", color: "#065f46", border: "1px solid #6ee7b7", borderRadius: 3, background: "#ecfdf5", marginTop: 2 }}
        onClick={(e) => { e.stopPropagation(); add(); }}
      >+ Add answer</button>
    </div>
  );
}

// ─── sub mode (Underline subQuestions, CompleteSentences w/ subs) ─────────────
function SubEditor({ subQuestions, onChange }) {
  if (!Array.isArray(subQuestions)) return null;
  const update = (i, val) => {
    const next = subQuestions.map((sq, j) =>
      j === i ? { ...sq, correctAnswers: [val] } : sq
    );
    onChange({ subQuestions: next });
  };
  return (
    <div style={wrapStyle}>
      <span style={labelStyle}>Edit answer key (per slot)</span>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 4 }}>
        {subQuestions.map((sq, i) => {
          const current = Array.isArray(sq.correctAnswers) ? (sq.correctAnswers[0] ?? "") : "";
          return (
            <input
              key={i}
              style={{ ...inputStyle, minWidth: 70 }}
              value={current}
              placeholder={sq.prompt ? String(sq.prompt).slice(0, 20) : `Slot ${i + 1}`}
              onChange={(e) => update(i, e.target.value)}
              onClick={(e) => e.stopPropagation()}
            />
          );
        })}
      </div>
    </div>
  );
}

// ─── main export ──────────────────────────────────────────────────────────────
/**
 * @param {object}   props
 * @param {string[]} props.correctAnswers  - current answer key values (flat array)
 * @param {Array}    [props.subQuestions]  - subQuestions array (for sub mode)
 * @param {string}   props.questionType   - question.type string
 * @param {Function} props.onChange       - called with the patch object
 */
const AnswerKeyEditor = ({ correctAnswers, subQuestions, questionType, onChange }) => {
  // Sub mode: has populated subQuestions
  if (Array.isArray(subQuestions) && subQuestions.length > 0) {
    return <SubEditor subQuestions={subQuestions} onChange={onChange} />;
  }

  // Bag-pool mode: correction or underline (flat)
  if (questionType === "correction" || questionType === "underline") {
    return <BagPoolEditor value={correctAnswers} onChange={onChange} />;
  }

  // Multi-blank mode: multiple slots
  const multiBlankTypes = [
    "gap-fill-table", "gap-filling", "fill-in-the-blanks",
    "inline-blank", "notes-completion", "short-answer", "summary-completion",
  ];
  if (multiBlankTypes.includes(questionType) && Array.isArray(correctAnswers) && correctAnswers.length > 1) {
    return <MultiBlankEditor value={correctAnswers} onChange={onChange} />;
  }

  // Single mode: everything else (or single-blank of a multi-blank type)
  return <SingleEditor value={correctAnswers} onChange={onChange} />;
};

export default AnswerKeyEditor;
