import { useState, useEffect } from "react";

/**
 * Manages focus-request state and the retry effect that scrolls/focuses
 * the target question element after navigation or incomplete-question clicks.
 */
export const useFocusRequest = (activeSection) => {
  const [focusRequest, setFocusRequest] = useState(null);

  const escapeSelectorValue = (raw) => {
    if (typeof raw !== "string") return raw;
    if (typeof CSS !== "undefined" && typeof CSS.escape === "function") {
      try {
        return CSS.escape(raw);
      } catch (error) {
        // Fallback to manual escaping below
      }
    }
    return raw.replace(/"/g, '\\"');
  };

  useEffect(() => {
    if (!focusRequest) return;
    if (typeof document === "undefined") return;
    if (focusRequest.sectionKey !== activeSection) return;

    const targetId = `question-${focusRequest.sectionKey}-${focusRequest.questionId}`;
    const focusSelector =
      "input, textarea, select, [contenteditable='true'], .ql-editor, button";

    const container = document.getElementById(targetId);
    const slotNumber = focusRequest.meta?.slotNumber;
    const slotIndex = focusRequest.meta?.slotIndex;
    const slotId = focusRequest.meta?.slotId;

    let targetEl = null;

    // 1. Try precise slot targeting by label number (most accurate for sub-questions)
    if (slotNumber) {
      targetEl = document.querySelector(`[data-question-slot-number="${slotNumber}"]`);
    }

    // 2. Try targeting by internal unique ID or index within a known container
    if (!targetEl && container && slotIndex != null) {
      const selectors = [];
      if (slotId) {
        const escapedSlotId = escapeSelectorValue(slotId);
        selectors.push(`[data-question-slot-id="${escapedSlotId}"]`);
      }
      selectors.push(`[data-question-slot-index="${slotIndex}"]`);
      targetEl = container.querySelector(selectors.join(", "));
    }

    // 3. Fallback to the container itself if no specific element is found
    if (!targetEl) {
      targetEl = container;
    }

    if (targetEl) {
      // Scroll to the most specific element we found
      targetEl.scrollIntoView({ behavior: "smooth", block: "center" });

      // Determine what to actually focus (the element itself or something inside it)
      let focusable = targetEl;
      if (!['INPUT', 'SELECT', 'TEXTAREA', 'BUTTON'].includes(targetEl.tagName)) {
        focusable = targetEl.matches?.(focusSelector)
          ? targetEl
          : targetEl.querySelector?.(focusSelector);
      }

      if (focusable) {
        try {
          const isQuill = focusable.classList && focusable.classList.contains("ql-editor");
          const isTextInput = focusable.tagName === 'TEXTAREA' || focusable.tagName === 'INPUT';
          if (isQuill || isTextInput) {
            focusable.setAttribute("tabindex", "-1");
          }
        } catch (e) { }

        // Use a slight delay for focus if we just scrolled a lot
        setTimeout(() => {
          focusable.focus({ preventScroll: true });
        }, 150);
      }

      setFocusRequest(null);
      return;
    }

    if ((focusRequest.attempts ?? 0) >= 6) {
      setFocusRequest(null);
      return;
    }

    const timer = setTimeout(() => {
      setFocusRequest((prev) => {
        if (
          !prev ||
          prev.sectionKey !== focusRequest.sectionKey ||
          prev.questionId !== focusRequest.questionId
        ) {
          return prev;
        }
        return { ...prev, attempts: (prev.attempts ?? 0) + 1 };
      });
    }, 120);

    return () => clearTimeout(timer);
  }, [focusRequest, activeSection]);

  return { focusRequest, setFocusRequest };
};
