import { DEFAULT_EXAM_TEMPLATE } from "../constants/examTemplate";
import { getQuestionSlotCount } from "./question/questionMetrics";

export function normalizeExamData(remoteExam) {
  if (!remoteExam || Object.keys(remoteExam).length === 0) {
    return JSON.parse(JSON.stringify(DEFAULT_EXAM_TEMPLATE));
  }

  const normalized = {};

  Object.entries(remoteExam).forEach(([key, value]) => {
    if (typeof value === "string") {
      normalized[key] = value;
      return;
    }
    const parsed = parseRemoteSection(value);
    if (parsed !== null && parsed !== undefined) {
      normalized[key] = parsed;
    }
  });

  // Ensure options exist so downstream consumers have a predictable shape
  if (!normalized.options) {
    normalized.options = { ...(DEFAULT_EXAM_TEMPLATE.options || {}) };
  }

  return normalized;
}

export function parseRemoteSection(sectionData) {
  if (!sectionData) return null;

  if (typeof sectionData === "string") {
    try {
      return JSON.parse(sectionData);
    } catch {
      return null;
    }
  }

  if (sectionData?.data) {
    try {
      const parsed = JSON.parse(sectionData.data);
      if (parsed && typeof parsed === "object") {
        return parsed;
      }
    } catch {
      return sectionData;
    }
  }

  return sectionData;
}

const createCollector = (startingNumber = 1) => ({
  items: [],
  nextNumber: Math.max(Number(startingNumber) || 1, 1),
});

const appendQuestionItems = (
  collector,
  questions = [],
  baseMeta = {}
) => {
  if (!collector) return;
  const list = Array.isArray(questions) ? questions : [];
  list.forEach((question) => {
    if (!question) return;
    const slotCount = Math.max(getQuestionSlotCount(question), 1);
    const questionType = question?.type || null;
    const subQuestions = Array.isArray(question?.subQuestions)
      ? question.subQuestions
      : [];

    // Checkbox: each correct answer = 1 question slot
    if (questionType === "checkbox") {
      const correctAnswers = Array.isArray(question?.correctAnswers)
        ? question.correctAnswers
        : [];
      const numSlots = correctAnswers.length || slotCount;

      for (let slotIndex = 0; slotIndex < numSlots; slotIndex += 1) {
        const labelNumber = collector.nextNumber;
        collector.items.push({
          id: question.id,
          key: `${question.id || "unknown"}::checkbox::${slotIndex}`,
          label: `${labelNumber}`,
          order: labelNumber,
          meta: {
            ...baseMeta,
            slotIndex,
            slotNumber: labelNumber,
            slotId: null,
            questionType,
            requiredSelections: numSlots,
            totalSlots: numSlots,
          },
        });
        collector.nextNumber += 1;
      }
      return;
    }

    // For other question types with slots
    const requiredSelections = questionType === "checkbox" ? slotCount : undefined;

    for (let slotIndex = 0; slotIndex < slotCount; slotIndex += 1) {
      const subQuestion = subQuestions[slotIndex];
      const isGrouped = !!subQuestion?.isGrouped;

      // If grouped, use the previous number and don't increment
      const labelNumber = isGrouped ? (collector.nextNumber - 1) : collector.nextNumber;

      const slotId = subQuestion?.id || null;
      collector.items.push({
        id: question.id,
        key: `${question.id || "unknown"}::${slotIndex}`,
        label: `${labelNumber}`,
        order: labelNumber,
        meta: {
          ...baseMeta,
          slotIndex,
          slotNumber: labelNumber,
          slotId,
          questionType,
          requiredSelections,
          totalSlots: slotCount,
          isGrouped,
        },
      });

      if (!isGrouped) {
        collector.nextNumber += 1;
      }
    }
  });
};

export function extractQuestionItems(sectionKey, sectionData, startingNumber = 1) {
  if (!sectionData) return [];

  const collector = createCollector(startingNumber);

  // Handle listening sections with questionGroups
  // Note: No groupId is passed because listening already has its own
  // section tabs (SECTION 1, SECTION 2, etc.) at the top of the content area.
  // Adding groupId would create redundant Part tabs in the footer navigation.
  if (sectionData.questionGroups) {
    sectionData.questionGroups.forEach((group) => {
      if (!group) return;
      appendQuestionItems(collector, group.questions, {});
    });
    return collector.items;
  }

  // Handle custom sections with standalone questions and/or groups
  if (sectionData.groups || sectionData.questions) {
    if (Array.isArray(sectionData.questions) && sectionData.questions.length > 0) {
      appendQuestionItems(collector, sectionData.questions, {
        standalone: true,
      });
    }

    if (Array.isArray(sectionData.groups) && sectionData.groups.length > 0) {
      sectionData.groups.forEach((group) => {
        if (!group) return;
        appendQuestionItems(collector, group.questions, {
          groupId: group.id,
        });
      });
    }

    return collector.items;
  }

  // Handle reading sections with passages
  if (sectionData.passages) {
    sectionData.passages.forEach((passage) => {
      if (!passage) return;
      appendQuestionItems(collector, passage.questions, {
        passageId: passage.id,
      });
    });
    return collector.items;
  }

  // Handle writing sections with tasks
  if (sectionKey === "writing" && sectionData.tasks) {
    return sectionData.tasks.map((task, index) => ({
      id: task.id,
      key: `${task.id || "task"}::${index}`,
      label: `Task ${index + 1}`,
      order: index + 1,
      meta: {
        questionType: "writing-task",
        slotIndex: 0,
        totalSlots: 1,
      },
    }));
  }

  // Handle speaking sections with parts
  if (sectionKey === "speaking" && sectionData.parts) {
    return sectionData.parts.map((part, index) => ({
      id: part.id,
      key: `${part.id || "part"}::${index}`,
      label: `Part ${index + 1}`,
      order: index + 1,
      meta: {
        questionType: "speaking-part",
        slotIndex: 0,
        totalSlots: 1,
      },
    }));
  }

  return [];
}

export function generateId(prefix) {
  return `${prefix}_${Math.random().toString(36).slice(2, 10)}`;
}
