import React, { useCallback, useRef, useContext } from "react";
import { normalizeAnswer, splitAlternatives, isPartialWordMatch } from "../../../utils/normalizeAnswer";
import RegradeContext from "../../../contexts/RegradeContext";
import AnswerKeyEditor from "../_shared/AnswerKeyEditor";

const CorrectionPreview = ({
  question,
  value,
  onChange,
  disabled = false,
  reviewMode = false,
  correctAnswers = [],
  name,
  questionNumber = 1,
  sectionKey = '',
}) => {
  const passageRef = useRef(null);

  const numberOfErrors = question?.numberOfErrors || 0;
  const example = question?.example || null;
  const isInteractive = typeof onChange === "function";
  const { isRegrade, setKeyEdit } = useContext(RegradeContext);

  // value is an array of { error, correction } objects
  const userSlots = Array.isArray(value)
    ? value
    : Array(numberOfErrors).fill(null).map(() => ({ error: "", correction: "" }));

  // Ensure we always have the right number of slots
  while (userSlots.length < numberOfErrors) {
    userSlots.push({ error: "", correction: "" });
  }

  const startingNumber = typeof questionNumber === "string"
    ? parseInt(String(questionNumber).split(" ")[0]) || 1
    : parseInt(String(questionNumber)) || 1;

  const updateSlot = useCallback((index, field, val) => {
    if (!isInteractive || disabled || (reviewMode)) return;
    const next = userSlots.map((s, i) =>
      i === index ? { ...s, [field]: val } : { ...s }
    );
    onChange(next);
  }, [userSlots, isInteractive, disabled, reviewMode, onChange]);

  const handleTextSelect = useCallback(() => {
    if (!isInteractive || disabled || (reviewMode)) return;
    const selection = window.getSelection();
    const text = selection?.toString().trim();
    if (!text) return;

    // Check that the selection is within our passage
    if (passageRef.current && !passageRef.current.contains(selection?.anchorNode)) return;

    // Find next empty error slot
    const emptyIndex = userSlots.findIndex((s) => !s.error);
    if (emptyIndex === -1) return;

    const next = userSlots.map((s, i) =>
      i === emptyIndex ? { ...s, error: text } : { ...s }
    );
    onChange(next);

    // Clear browser selection
    selection?.removeAllRanges();
  }, [userSlots, isInteractive, disabled, reviewMode, onChange]);

  if (!question) return null;

  // Bag-match scoring for review mode
  const reviewResults = (() => {
    if (!reviewMode) return null;

    // Build pool of acceptable answers (normalized)
    const pool = (question.correctAnswers || correctAnswers || []).flatMap(a =>
      splitAlternatives(String(a))
    ).map(normalizeAnswer);
    const remainingPool = [...pool];

    return userSlots.map((slot) => {
      const userCorrection = normalizeAnswer(slot?.correction || "");
      if (!userCorrection) return { isSkipped: true, isCorrect: false };

      // Try exact match first, then partial word match (2/3+ rule)
      let matchIndex = remainingPool.findIndex((a) => a === userCorrection);
      if (matchIndex === -1) {
        matchIndex = remainingPool.findIndex((a) => isPartialWordMatch(userCorrection, a));
      }
      if (matchIndex !== -1) {
        remainingPool.splice(matchIndex, 1);
        return { isSkipped: false, isCorrect: true };
      }
      return { isSkipped: false, isCorrect: false };
    });
  })();

  return (
    <div className="flex flex-col gap-4">
      {/* Passage */}
      <div
        ref={passageRef}
        className="rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-[15px] leading-relaxed text-slate-700 select-text cursor-text rich-text-content [&_u]:underline [&_u]:decoration-orange-400 [&_u]:decoration-2 [&_u]:underline-offset-2"
        dangerouslySetInnerHTML={{ __html: question.content }}
        onMouseUp={handleTextSelect}
        onTouchEnd={handleTextSelect}
      />

      {!reviewMode && !disabled && (
        <p className="text-xs text-slate-400 -mt-2">
          Highlight the incorrect text in the passage above, then type the correction below.
        </p>
      )}

      {/* Correction rows */}
      <div className="flex flex-col gap-2">
        {/* Example row */}
        {example && (
          <div className="flex items-center gap-2 py-2 border-b border-slate-100">
            <span className="inline-flex h-7 min-w-[2.5rem] flex-shrink-0 items-center justify-center rounded bg-blue-100 px-2 text-xs font-semibold text-blue-600">
              Ex.
            </span>
            <div className="flex flex-1 items-center gap-2 flex-wrap sm:flex-nowrap">
              <input
                type="text"
                value={example.errorText}
                disabled
                className="w-full sm:w-[40%] rounded-lg border border-slate-200 bg-slate-100 px-3 py-2 text-sm text-slate-500 line-through"
              />
              <span className="text-slate-400 text-sm font-medium flex-shrink-0">&rarr;</span>
              <span className="inline-flex items-center gap-1 rounded-full bg-green-50 border border-green-200 px-2.5 py-1 text-sm font-semibold text-green-700">
                {example.correction}
              </span>
            </div>
          </div>
        )}

        {/* Answerable rows */}
        {userSlots.map((slot, index) => {
          const rowNumber = startingNumber + index;
          const result = reviewResults?.[index];

          return (
            <div
              key={index}
              className="flex items-center gap-2 py-2 border-b border-slate-100 last:border-0"
            >
              <span className="inline-flex h-7 min-w-[1.75rem] flex-shrink-0 items-center justify-center rounded bg-slate-100 px-2 text-xs font-medium text-slate-600">
                {rowNumber}
              </span>
              <div className="flex flex-1 items-center gap-2 flex-wrap sm:flex-nowrap">
                {/* Error text field */}
                <input
                  type="text"
                  value={slot?.error || ""}
                  onChange={(e) => updateSlot(index, "error", e.target.value)}
                  disabled={disabled || (reviewMode)}
                  placeholder="Select error text above"
                  className={`w-full sm:w-[40%] rounded-lg border px-3 py-2 text-sm shadow-sm transition-all focus:outline-none focus:ring-2 ${
                    slot?.error
                      ? "border-red-200 bg-red-50 text-red-700 line-through"
                      : "border-slate-200 focus:border-blue-500 focus:ring-blue-200"
                  }`}
                />
                <span className="text-slate-400 text-sm font-medium flex-shrink-0">&rarr;</span>
                {/* Correction input */}
                <input
                  type="text"
                  value={slot?.correction || ""}
                  onChange={(e) => updateSlot(index, "correction", e.target.value)}
                  disabled={disabled || (reviewMode)}
                  placeholder="Type correction"
                  data-question-slot-number={rowNumber}
                  data-question-slot-index={index}
                  className={`w-full sm:w-[40%] rounded-lg border px-3 py-2 text-sm shadow-sm transition-all focus:outline-none focus:ring-2 ${
                    reviewMode
                      ? result?.isCorrect
                        ? "border-green-400 bg-green-50"
                        : result?.isSkipped
                          ? "border-slate-200 bg-slate-50"
                          : "border-red-300 bg-red-50"
                      : "border-slate-200 focus:border-blue-500 focus:ring-blue-200"
                  }`}
                />
              </div>
              {/* Review feedback */}
              {reviewMode && (
                <div className="flex-shrink-0 text-xs font-semibold">
                  {result?.isCorrect && <span className="text-green-600">&#10003;</span>}
                  {!result?.isCorrect && !result?.isSkipped && <span className="text-red-600">&#10007;</span>}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* Review: show expected answers */}
      {reviewMode && (
        <div className="mt-2 rounded-lg border border-slate-200 bg-slate-50 px-4 py-3">
          <p className="text-xs font-semibold text-slate-500 mb-1">Expected corrections:</p>
          <div className="flex flex-wrap gap-2">
            {(question.correctAnswers || correctAnswers || []).map((ans, i) => (
              <span key={i} className="inline-block rounded-full bg-green-50 border border-green-200 px-2.5 py-0.5 text-xs font-medium text-green-700">
                {ans}
              </span>
            ))}
          </div>
        </div>
      )}
      {isRegrade && reviewMode && (
        <AnswerKeyEditor
          correctAnswers={question.correctAnswers}
          questionType={question.type}
          onChange={(patch) => setKeyEdit(sectionKey, question.id, patch)}
        />
      )}
    </div>
  );
};

export default CorrectionPreview;
