import React, { useMemo } from "react";
import AudioPlayer from "react-h5-audio-player";
import "react-h5-audio-player/lib/styles.css";
import QuestionCard from "../Question/QuestionCard";
import { cloneDefaultOptions } from "../../../../utils/question/questionUtils";
import { getQuestionSlotCount } from "../../../../utils/question/questionMetrics";
import { DEFAULT_MATCHING_HEADING_TITLE } from "../../../../utils/question/questionDefaults";
import { generateId } from "../../../../utils/question/idUtils";
import { useNumbering } from "../../../../contexts/NumberingContext";
import { generateQuestionRangeTitle, generateInstructionGroupTitle } from "../../../../utils/question/questionTitleGenerator";

const createBaseQuestion = () => ({
  id: generateId("LQ"),
  type: "fill-in-the-blanks",
  inputMode: "text",
  description: "",
  prompt: "",
  placeholder: "",
  options: cloneDefaultOptions(),
  correctAnswers: [],
  inlineTemplate: "",
  subQuestions: [],
  matchingHeadingListTitle: DEFAULT_MATCHING_HEADING_TITLE,
  matchingHeadingItems: ["", "", ""],
  matchingHeadingAnswers: ["", "", ""],
});

const ensureArray = (value) => (Array.isArray(value) ? value : []);

function ListeningBuilder({
  data,
  onChange,
  onAudioUpload,
  uploadingAudio,
  sectionKey = "listening",
}) {
  const listening = useMemo(
    () => ({
      title: "",
      intro: "",
      timeAllotted: "",
      questionGroups: [],
      ...data,
    }),
    [data]
  );

  const applyUpdate = (updates) => {
    onChange({
      ...listening,
      ...updates,
    });
  };

  const updateGroups = (updater) => {
    const current = ensureArray(listening.questionGroups);
    const next = typeof updater === "function" ? updater(current) : updater;
    applyUpdate({ questionGroups: next });
  };

  const handleSectionFieldChange = (field, value) => {
    applyUpdate({ [field]: value });
  };

  const handleGroupChange = (groupIndex, field, value) => {
    updateGroups((groups) =>
      groups.map((group, idx) =>
        idx === groupIndex ? { ...group, [field]: value } : group
      )
    );
  };

  const handleAddGroup = () => {
    updateGroups((groups) => [
      ...groups,
      {
        id: generateId("recording"),
        title: `Recording ${groups.length + 1}`,
        description: "",
        audioUrl: "",
        audioFileName: "",
        audioPreviewUrl: "",
        questions: [],
      },
    ]);
  };

  const handleRemoveGroup = (groupIndex) => {
    updateGroups((groups) => groups.filter((_, idx) => idx !== groupIndex));
  };

  const handleAddQuestion = (groupIndex) => {
    updateGroups((groups) =>
      groups.map((group, idx) =>
        idx === groupIndex
          ? {
            ...group,
            questions: [...ensureArray(group.questions), createBaseQuestion()],
          }
          : group
      )
    );
  };

  const handleRemoveQuestion = (groupIndex, questionIndex) => {
    updateGroups((groups) =>
      groups.map((group, idx) => {
        if (idx !== groupIndex) return group;
        return {
          ...group,
          questions: ensureArray(group.questions).filter((_, qIdx) => qIdx !== questionIndex),
        };
      })
    );
  };

  const handleDuplicateQuestion = (groupIndex, questionIndex) => {
    updateGroups((groups) =>
      groups.map((group, idx) => {
        if (idx !== groupIndex) return group;
        const questions = ensureArray(group.questions);
        const target = questions[questionIndex];
        if (!target) return group;
        const clone = {
          ...target,
          id: generateId("LQ"),
          prompt: target.prompt || "",
        };
        return {
          ...group,
          questions: [
            ...questions.slice(0, questionIndex + 1),
            clone,
            ...questions.slice(questionIndex + 1),
          ],
        };
      })
    );
  };

  const handleQuestionChange = (groupIndex, questionIndex, patchOrUpdater, value) => {
    updateGroups((groups) =>
      groups.map((group, idx) => {
        if (idx !== groupIndex) return group;
        const questions = ensureArray(group.questions).map((question, qIdx) => {
          if (qIdx !== questionIndex) return question;
          if (typeof patchOrUpdater === "function") {
            const next = patchOrUpdater(question);
            return next || question;
          }
          if (patchOrUpdater && typeof patchOrUpdater === "object") {
            return { ...question, ...patchOrUpdater };
          }
          if (typeof patchOrUpdater === "string") {
            return { ...question, [patchOrUpdater]: value };
          }
          return question;
        });
        return { ...group, questions };
      })
    );
  };

  const { getQuestionNumber } = useNumbering();

  return (
    <div className="space-y-8">
      <section className="space-y-4 rounded-2xl border border-slate-200 bg-white p-5">
        <div className="grid gap-6 md:grid-cols-3">
          <div>
            <label className="text-xs font-semibold uppercase tracking-wide text-slate-500">
              Listening title
            </label>
            <input
              type="text"
              value={listening.title}
              onChange={(event) => handleSectionFieldChange("title", event.target.value)}
              className="mt-1 w-full rounded-xl border border-slate-200 px-4 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
              placeholder="IELTS Listening Test 1"
            />
          </div>
          <div>
            <label className="text-xs font-semibold uppercase tracking-wide text-slate-500">
              Introductory text
            </label>
            <textarea
              value={listening.intro}
              onChange={(event) => handleSectionFieldChange("intro", event.target.value)}
              rows={4}
              className="mt-1 w-full rounded-xl border border-slate-200 px-4 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
              placeholder="Describe the focus of the listening section..."
            />
          </div>
          <div>
            <label className="text-xs font-semibold uppercase tracking-wide text-slate-500">
              Time allotted
            </label>
            <input
              type="text"
              value={listening.timeAllotted || ""}
              onChange={(event) => handleSectionFieldChange("timeAllotted", event.target.value)}
              className="mt-1 w-full rounded-xl border border-slate-200 px-4 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
              placeholder="e.g., 15 minutes"
            />
          </div>
        </div>

        <div className="flex items-center justify-between">
          <h3 className="text-lg font-semibold text-slate-900">Recording blocks</h3>
          <button
            type="button"
            onClick={handleAddGroup}
            className="rounded-lg border border-blue-200 px-3 py-1.5 text-sm font-medium text-blue-700 transition hover:bg-blue-50"
          >
            + Add recording block
          </button>
        </div>
      </section>

      <div className="space-y-6">
        {ensureArray(listening.questionGroups).map((group, groupIndex) => {
          const questions = ensureArray(group.questions);

          // Calculate group numbering range
          const firstQuestion = questions.length > 0 ? questions[0] : null;
          const lastQuestion = questions.length > 0 ? questions[questions.length - 1] : null;
          const groupStartNum = firstQuestion ? getQuestionNumber("listening", group.id, firstQuestion.id) : null;
          const groupEndNum = lastQuestion ? getQuestionNumber("listening", group.id, lastQuestion.id) : null;

          // Parse range if it's a string like "1-5"
          let groupStart = groupStartNum;
          let groupEnd = groupEndNum;
          if (typeof groupStartNum === "string" && groupStartNum.includes("-")) {
            const parts = groupStartNum.split("-");
            groupStart = parseInt(parts[0]) || 1;
            groupEnd = parseInt(parts[parts.length - 1]) || groupStart;
          } else if (typeof groupEndNum === "string" && groupEndNum.includes("-")) {
            const parts = groupEndNum.split("-");
            groupEnd = parseInt(parts[parts.length - 1]) || parseInt(groupEndNum) || 1;
          } else {
            groupStart = parseInt(groupStartNum) || 1;
            groupEnd = parseInt(groupEndNum) || groupStart;
          }

          const groupTitle = generateQuestionRangeTitle(groupStart, groupEnd);

          return (
            <article
              key={group.id || `group-${groupIndex}`}
              data-question-id={group.id}
              className="space-y-4 rounded-2xl border border-slate-200 bg-slate-50 p-5"
            >
              <div className="flex justify-between items-center">
                <div className="text-sm font-semibold text-slate-600">{groupTitle}</div>
                <button
                  type="button"
                  onClick={() => handleRemoveGroup(groupIndex)}
                  className="text-xs font-semibold text-rose-500 hover:text-rose-600"
                >
                  Remove
                </button>
              </div>
              <div className="rounded-xl border border-amber-200 bg-amber-50 p-4">
                <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
                  <div>
                    <p className="text-sm font-semibold text-amber-800">
                      🎵 Recording audio
                    </p>
                    <p className="text-xs text-amber-700">
                      Upload audio file for this recording block (MP3, WAV, AAC)
                    </p>
                  </div>
                  <label className="inline-flex cursor-pointer items-center gap-2 rounded-lg bg-amber-600 px-3 py-2 text-sm font-medium text-white shadow hover:bg-amber-700">
                    <input
                      type="file"
                      accept="audio/*"
                      className="hidden"
                      onChange={(event) => {
                        const file = event.target.files?.[0];
                        if (file) {
                          onAudioUpload?.(file, groupIndex, sectionKey);
                        }
                      }}
                      disabled={uploadingAudio}
                    />
                    {uploadingAudio ? "⏳ Uploading..." : "📤 Choose audio"}
                  </label>
                </div>

                {(group.audioUrl ||
                  group.audioPreviewUrl ||
                  group.audioFileName) && (
                    <div className="mt-3 space-y-3">
                      {(group.audioUrl || group.audioPreviewUrl) && (
                        <div className="rounded-lg border border-amber-200 bg-white p-3">
                          <AudioPlayer
                            autoPlay={false}
                            src={group.audioUrl || group.audioPreviewUrl}
                            layout="horizontal"
                            showSkipControls={false}
                          />
                        </div>
                      )}
                      <div className="rounded-lg border border-amber-100 bg-white p-3 text-xs">
                        <p className="font-semibold text-amber-700">
                          {group.audioFileName || "Audio attached"}
                        </p>
                        <p className="mt-1 text-amber-600">
                          The audio will be available to candidates once uploaded.
                        </p>
                      </div>
                    </div>
                  )}
                {!group.audioUrl &&
                  !group.audioPreviewUrl &&
                  !group.audioFileName && (
                    <p className="mt-3 text-xs text-slate-400 italic">
                      No audio uploaded yet
                    </p>
                  )}
              </div>
              <div className="flex items-start justify-between gap-3">
                <div className="flex-1 space-y-2">
                  <input
                    type="text"
                    value={group.title || ""}
                    onChange={(event) =>
                      handleGroupChange(groupIndex, "title", event.target.value)
                    }
                    placeholder="e.g. Recording 1, Conversation, Interview..."
                    className="w-full rounded-xl border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-800 focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
                  />
                  <textarea
                    value={group.description || ""}
                    onChange={(event) =>
                      handleGroupChange(
                        groupIndex,
                        "description",
                        event.target.value
                      )
                    }
                    rows={2}
                    className="w-full rounded-xl border border-slate-200 px-4 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
                    placeholder="Optional description or instructions"
                  />
                </div>
              </div>

              <div className="space-y-3">
                {questions.map((question, questionIndex) => {
                  const questionNumber = getQuestionNumber("listening", group.id, question.id);
                  return (
                    <QuestionCard
                      key={question.id || `question-${questionIndex}`}
                      question={question}
                      questionNumber={questionNumber}
                      numberingPrefix={questionNumber}
                      onChange={(updates) =>
                        handleQuestionChange(groupIndex, questionIndex, updates)
                      }
                      sectionMeta={{
                        sectionKey: "listening",
                        type: "group",
                        groupId: group.id,
                        groupIndex,
                        questionIndex,
                      }}
                      renderActions={() => (
                        <div className="flex items-center gap-2">
                          <button
                            type="button"
                            onClick={() =>
                              handleDuplicateQuestion(groupIndex, questionIndex)
                            }
                            className="rounded border border-blue-200 px-3 py-1 text-xs font-semibold text-blue-600 hover:bg-blue-50"
                          >
                            Duplicate
                          </button>
                          <button
                            type="button"
                            onClick={() =>
                              handleRemoveQuestion(groupIndex, questionIndex)
                            }
                            className="rounded border border-red-200 px-3 py-1 text-xs font-semibold text-red-600 hover:bg-red-50"
                          >
                            Delete
                          </button>
                        </div>
                      )}
                    />
                  );
                })}
              </div>

              <button
                type="button"
                onClick={() => handleAddQuestion(groupIndex)}
                className="rounded border border-blue-200 px-3 py-1 text-xs font-semibold text-blue-600 hover:bg-blue-50"
              >
                + Add question
              </button>
            </article>
          );
        })}

        {ensureArray(listening.questionGroups).length === 0 && (
          <div className="rounded-lg border border-dashed border-slate-300 bg-white p-6 text-center text-sm text-slate-500">
            Add a recording block to start building questions.
          </div>
        )}
      </div>
    </div>
  );
}

export default ListeningBuilder;
