// recaptcha.js — reCAPTCHA Enterprise token minting for the public booking callables.
//
// DIY assessment (NOT Firebase App Check — App Check's token exchange kept 403-ing): the
// client mints a short-lived Enterprise SCORE token here; the booking Cloud Function verifies
// it via createAssessment and (Phase 2) score-gates the write. See booking_consultation_flow.md.
//
// Tokens are single-use and expire in ~2 min, so we mint one per server call (savePendingLead
// / createConsultationLead) at action time — never cached. Any failure (no key, script blocked,
// execute throws) resolves to `null`: the CF is log-only in Phase 1, so a missing token never
// blocks a legit booking. The site key is PUBLIC (Enterprise has no client secret) — it's the
// same key the backend passes to createAssessment, sourced from REACT_APP_RECAPTCHA_SITE_KEY.

const SITE_KEY = process.env.REACT_APP_RECAPTCHA_SITE_KEY;
const SCRIPT_ID = 'recaptcha-enterprise-sdk';

let _ready = null; // memoized script-load promise (load once per page)

function loadScript() {
  if (_ready) return _ready;
  _ready = new Promise((resolve, reject) => {
    if (!SITE_KEY) { reject(new Error('no reCAPTCHA site key')); return; }
    if (typeof window === 'undefined' || typeof document === 'undefined') { reject(new Error('no DOM')); return; }
    if (window.grecaptcha && window.grecaptcha.enterprise) { resolve(); return; }
    // A tag may already exist (from a prior preload) but not be ready — poll grecaptcha.
    if (document.getElementById(SCRIPT_ID)) { waitForGrecaptcha(resolve, reject); return; }
    const s = document.createElement('script');
    s.id = SCRIPT_ID;
    s.src = `https://www.google.com/recaptcha/enterprise.js?render=${encodeURIComponent(SITE_KEY)}`;
    s.async = true;
    s.defer = true;
    s.onload = () => waitForGrecaptcha(resolve, reject);
    s.onerror = () => reject(new Error('reCAPTCHA script failed to load'));
    document.head.appendChild(s);
  });
  return _ready;
}

// onload fires before grecaptcha.enterprise is necessarily initialized — poll briefly.
function waitForGrecaptcha(resolve, reject) {
  const t0 = Date.now();
  const iv = setInterval(() => {
    if (window.grecaptcha && window.grecaptcha.enterprise) { clearInterval(iv); resolve(); }
    else if (Date.now() - t0 > 10000) { clearInterval(iv); reject(new Error('grecaptcha.enterprise load timeout')); }
  }, 80);
}

// Kick off the script load early (call on booking mount) so execute() is instant at submit.
export function preloadRecaptcha() {
  loadScript().catch(() => { /* surfaced at execute() time */ });
}

// Mint a single-use token for `action`. Resolves to `null` on ANY failure — Phase 1 is
// log-only server-side, so the booking proceeds and the CF logs 'missing-token'.
export async function executeBookingRecaptcha(action) {
  if (!SITE_KEY) return null;
  try {
    await loadScript();
    const g = window.grecaptcha && window.grecaptcha.enterprise;
    if (!g) return null;
    return await new Promise((resolve, reject) => {
      g.ready(() => { g.execute(SITE_KEY, { action }).then(resolve, reject); });
    });
  } catch (e) {
    try { console.warn('[booking] reCAPTCHA execute failed:', e && e.message); } catch (_) { /* noop */ }
    return null;
  }
}
