export const BLANK_TOKEN = " _____ ";
export const INLINE_BLANK_TOKEN = "{{blank}}";

export const countTokenOccurrences = (value = "", token = BLANK_TOKEN) => {
  if (!value) return 0;
  return value.split(token).length - 1;
};

export const insertTokenAtCursor = (fieldId, currentValue = "", token = BLANK_TOKEN) => {
  const textarea = typeof document !== "undefined" ? document.getElementById(fieldId) : null;
  if (!textarea) {
    return {
      nextValue: `${currentValue}${token}`,
      cursorPosition: null,
    };
  }

  const { selectionStart, selectionEnd } = textarea;
  const start = typeof selectionStart === "number" ? selectionStart : currentValue.length;
  const end = typeof selectionEnd === "number" ? selectionEnd : start;
  const nextValue = currentValue.slice(0, start) + token + currentValue.slice(end);

  return {
    nextValue,
    cursorPosition: start + token.length,
  };
};

export const computePromptWithBlank = (fieldId, currentValue = "") =>
  insertTokenAtCursor(fieldId, currentValue, BLANK_TOKEN);

export const computeInlineTemplateWithBlank = (fieldId, currentValue = "") =>
  insertTokenAtCursor(fieldId, currentValue, INLINE_BLANK_TOKEN);
