import React from "react";
import { useQuestionContext } from "../../../../contexts/QuestionContext";
import FillInBlankBuilder from "../../../../components/QuestionTypes/FillInBlank/Builder";
import InlineBlankBuilder from "../../../../components/QuestionTypes/InlineBlank/Builder";
import MultipleChoiceBuilder from "../../../../components/QuestionTypes/MultipleChoice/Builder";
import CheckboxBuilder from "../../../../components/QuestionTypes/Checkbox/Builder";
import MatchingHeadingsBuilder from "../../../../components/QuestionTypes/MatchingHeadings/Builder";
import WhichTrueBuilder from "../../../../components/QuestionTypes/WhichTrue/Builder";
import TrueFalseNotGivenBuilder from "../../../../components/QuestionTypes/TrueFalseNotGiven/Builder";
import CompleteSentencesBuilder from "../../../../components/QuestionTypes/CompleteSentences/Builder";
import GapFillingBuilder from "../../../../components/QuestionTypes/GapFilling/Builder";
import GapFillTableBuilder from "../../../../components/QuestionTypes/GapFillTable/Builder";
import FillInBlankActions from "../../../../components/QuestionTypes/FillInBlank/Actions";
import InlineBlankActions from "../../../../components/QuestionTypes/InlineBlank/Actions";
import GapFillingActions from "../../../../components/QuestionTypes/GapFilling/Actions";

const builderMap = {
  "fill-in-the-blanks": FillInBlankBuilder,
  "inline-blank": InlineBlankBuilder,
  "multiple-choice": MultipleChoiceBuilder,
  checkbox: CheckboxBuilder,
  "matching-headings": MatchingHeadingsBuilder,
  "which-true": WhichTrueBuilder,
  "true-false-not-given": TrueFalseNotGivenBuilder,
  "complete-sentences": CompleteSentencesBuilder,
  "gap-filling": GapFillingBuilder,
  "gap-fill-table": GapFillTableBuilder,
  // Aliases for question types used in exam data
  "yes-no-not-given": TrueFalseNotGivenBuilder,
  "notes-completion": GapFillingBuilder,
  "short-answer": GapFillingBuilder,
  "summary-completion": GapFillingBuilder,
};

const actionsMap = {
  "fill-in-the-blanks": FillInBlankActions,
  "inline-blank": InlineBlankActions,
  "gap-filling": GapFillingActions,
};

const QuestionTypeRouter = ({ mode = "builder", questionNumber }) => {
  const { question } = useQuestionContext();
  const type = question?.type || "fill-in-the-blanks";

  if (mode === "actions") {
    const ActionComponent = actionsMap[type];
    return ActionComponent ? <ActionComponent /> : null;
  }

  const BuilderComponent = builderMap[type] || builderMap["fill-in-the-blanks"];
  return <BuilderComponent questionNumber={questionNumber} />;
};

export default QuestionTypeRouter;
