import React from "react";

import { normalizeAnswer, normalizeTFNG, formatTFNG } from "../../../utils/normalizeAnswer";


const TrueFalseNotGivenPreview = ({
  question,
  value,
  onChange,
  disabled = false,
  reviewMode = false,
  correctAnswers = [],
  name,
  questionNumber = 1,
}) => {
  // Use table view from question settings if available, otherwise default to false
  const tableView = question?.useTableView || false;

  if (!question) {
    return null;
  }

  const subQuestions = Array.isArray(question.subQuestions)
    ? question.subQuestions
    : [];

  if (subQuestions.length === 0) {
    return (
      <div className="rounded border border-dashed border-slate-300 bg-slate-50 px-3 py-2 text-sm text-slate-500">
        Add sub-questions to preview this question.
      </div>
    );
  }

  const isInteractive = typeof onChange === "function";

  // Handle value as an array of answers (one per sub-question)
  const userAnswers = Array.isArray(value) ? value : [];

  const handleAnswerSelect = (subQuestionIndex, answer) => {
    if (!isInteractive || disabled || (reviewMode)) return;

    const nextAnswers = [...userAnswers];
    nextAnswers[subQuestionIndex] = answer;
    onChange(nextAnswers);
  };

  const isYesNo = question?.type === "yes-no-not-given" ||
    (question?.prompt && /\bYES\b/.test(question.prompt) && /\bNO\b/.test(question.prompt));

  // Parse question number - could be "11" or "11 - 15"
  const startingNumber = typeof questionNumber === "string"
    ? parseInt(String(questionNumber).split(" ")[0]) || 1
    : parseInt(String(questionNumber)) || 1;

  // Use custom answer texts if provided - dynamically collect all answer options
  const answerOptions = (() => {
    const opts = [];
    let i = 1;
    const defaultValues = isYesNo
      ? ["YES", "NO", "NOT GIVEN"]
      : ["TRUE", "FALSE", "NOT GIVEN"];
    while (question?.[`answerText${i}`] !== undefined || i <= 3) {
      const value = question?.[`answerText${i}`];
      opts.push(
        value !== undefined && value !== null ? value : (defaultValues[i - 1] || "")
      );
      i++;
      if (i > 10 || (value === undefined && i > 3)) break; // Safety limit and stop if undefined after default 3
    }
    return opts.filter((opt) => opt.length > 0); // Filter out empty options
  })();

  // Table view rendering
  if (tableView) {
    return (
      <div className="space-y-3">
        {/* Questions Table */}
        <div className="border border-orange-300 rounded-lg overflow-hidden">
          <table className="w-full">
            <tbody>
              {subQuestions.map((subQuestion, subQuestionIndex) => {
                const answerNumber = startingNumber + subQuestionIndex;
                const userAnswer = answerOptions.find(opt => normalizeAnswer(opt) === normalizeAnswer(userAnswers[subQuestionIndex])) || "";

                return (
                  <tr key={`sub-question-${subQuestionIndex}`} className="border-b border-orange-300 bg-white hover:bg-slate-50">
                    <td className="px-4 py-3 text-sm text-slate-700 border-r border-orange-300">
                      <span className="font-semibold text-orange-600">{answerNumber}. </span>
                      <span className="rich-text-content">{subQuestion.prompt || subQuestion}</span>
                    </td>
                    <td className="px-4 py-2 w-20 text-center">
                      {userAnswer && (
                        <span className="inline-flex items-center justify-center font-semibold text-xs text-orange-600">
                          {userAnswer}
                        </span>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>

        {/* Answer Dropdowns Below */}
        <div className="space-y-2">
          {subQuestions.map((subQuestion, subQuestionIndex) => {
            const answerNumber = startingNumber + subQuestionIndex;
            const userAnswer = answerOptions.find(opt => normalizeAnswer(opt) === normalizeAnswer(userAnswers[subQuestionIndex])) || "";
            const correctAnswer = normalizeAnswer(correctAnswers[subQuestionIndex]);
            const isCorrect = reviewMode && correctAnswer ? normalizeTFNG(userAnswer) === normalizeTFNG(correctAnswer) : false;
            const isIncorrect = reviewMode && correctAnswer && userAnswer && normalizeTFNG(userAnswer) !== normalizeTFNG(correctAnswer);

            return (
              <div key={`answer-${subQuestionIndex}`} className="flex items-center gap-3">
                <span className="inline-flex h-6 min-w-[1.75rem] flex-shrink-0 items-center justify-center text-xs font-semibold text-orange-600">
                  {answerNumber}.
                </span>
                <select
                  value={userAnswer}
                  onChange={(event) =>
                    handleAnswerSelect(subQuestionIndex, event.target.value)
                  }
                  disabled={disabled || (reviewMode) || !isInteractive}
                  data-testid={`tfng-select-${answerNumber}`}
                  data-question-slot-index={subQuestionIndex}
                  data-question-slot-id={subQuestion?.id || undefined}
                  data-question-slot-number={answerNumber}
                  className={`px-3 py-1 text-xs rounded border ${reviewMode
                    ? isCorrect
                      ? "border-green-400 bg-green-50"
                      : isIncorrect
                        ? "border-red-300"
                        : "border-slate-200"
                    : "border-slate-200 hover:border-blue-400"
                    }`}
                >
                  <option value="">Select answer</option>
                  {answerOptions.map((option) => (
                    <option key={option} value={option}>
                      {option}
                    </option>
                  ))}
                </select>
                {reviewMode && (
                  <div className="text-xs">
                    {isCorrect && (
                      <span className="font-semibold text-green-600">
                        ✓ Correct
                      </span>
                    )}
                    {isIncorrect && (
                      <span className="font-semibold text-red-600">
                        ✗ ({formatTFNG(correctAnswer)})
                      </span>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  // List view rendering (when tableView is false)
  return (
    <div className="space-y-3">
      <div className="rounded-lg border border-orange-300 bg-orange-50/30 px-4 py-3">
        <div className="space-y-2">
          {subQuestions.map((subQuestion, subQuestionIndex) => {
            const answerNumber = startingNumber + subQuestionIndex;
            return (
              <div key={`sub-question-${subQuestionIndex}`} className="flex gap-3 text-sm text-slate-700">
                <span className="flex-shrink-0 font-semibold text-orange-600">{answerNumber}.</span>
                <span className="rich-text-content">{subQuestion.prompt || subQuestion}</span>
              </div>
            );
          })}
        </div>
      </div>

      {/* Answer Dropdowns */}
      <div className="space-y-2">
        {subQuestions.map((subQuestion, subQuestionIndex) => {
          const answerNumber = startingNumber + subQuestionIndex;
          const userAnswer = answerOptions.find(opt => normalizeAnswer(opt) === normalizeAnswer(userAnswers[subQuestionIndex])) || "";
          const correctAnswer = normalizeAnswer(correctAnswers[subQuestionIndex]);
          const isCorrect = reviewMode && correctAnswer ? normalizeTFNG(userAnswer) === normalizeTFNG(correctAnswer) : false;
          const isIncorrect = reviewMode && correctAnswer && userAnswer && normalizeTFNG(userAnswer) !== normalizeTFNG(correctAnswer);

          return (
            <div key={`answer-${subQuestionIndex}`} className="flex items-center gap-3">
              <span className="inline-flex h-6 min-w-[1.75rem] flex-shrink-0 items-center justify-center text-xs font-semibold text-orange-600">
                {answerNumber}.
              </span>
              <select
                value={userAnswer}
                onChange={(event) =>
                  handleAnswerSelect(subQuestionIndex, event.target.value)
                }
                disabled={disabled || (reviewMode) || !isInteractive}
                data-testid={`tfng-select-${answerNumber}`}
                data-question-slot-index={subQuestionIndex}
                data-question-slot-id={subQuestion?.id || undefined}
                data-question-slot-number={answerNumber}
                className={`px-3 py-1 text-xs rounded border ${reviewMode
                  ? isCorrect
                    ? "border-green-400 bg-green-50"
                    : isIncorrect
                      ? "border-red-300"
                      : "border-slate-200"
                  : "border-slate-200 hover:border-blue-400"
                  }`}
              >
                <option value="">Select answer</option>
                {answerOptions.map((option) => (
                  <option key={option} value={option}>
                    {option}
                  </option>
                ))}
              </select>
              {reviewMode && (
                <div className="text-xs">
                  {isCorrect && (
                    <span className="font-semibold text-green-600">
                      ✓ Correct
                    </span>
                  )}
                  {isIncorrect && (
                    <span className="font-semibold text-red-600">
                      ✗ ({formatTFNG(correctAnswer)})
                    </span>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default TrueFalseNotGivenPreview;
