import { useState, useMemo, useCallback } from "react";

/**
 * Generates a unique ID for notes/highlights.
 */
const createNoteId = () => {
  try {
    if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
      return crypto.randomUUID();
    }
  } catch (error) {
    // ignore crypto errors and fallback to timestamp id
  }
  return `note-${Date.now()}-${Math.abs(Math.floor(Math.random() * 1_000_000))}`;
};

/**
 * Clamps a note position to stay within the visible viewport.
 */
const clampNotePosition = (desiredX, desiredY) => {
  if (typeof window === "undefined") {
    return [desiredX, desiredY];
  }
  const maxX = Math.max(window.innerWidth - 210, 48);
  const maxY = Math.max(window.innerHeight - 140, 48);
  const clampedX = Math.min(Math.max(desiredX, 16), maxX);
  const clampedY = Math.min(Math.max(desiredY, 16), maxY);
  return [clampedX, clampedY];
};

/**
 * Manages notes and highlights state, context key derivation, and all CRUD operations.
 */
export const useNotesAndHighlights = (activeSection, activeReadingPassageId, activeListeningPart) => {
  const [notesByContext, setNotesByContext] = useState({});
  const [highlightsByContext, setHighlightsByContext] = useState({});

  const activeNoteContextKey = useMemo(() => {
    const normalizedSection = activeSection || "unknown";
    let passageKey = "default";
    if (activeSection === "reading") {
      passageKey = activeReadingPassageId || "default";
    } else if (normalizedSection.includes("listening")) {
      passageKey = `part-${activeListeningPart}`;
    }
    return `${normalizedSection}::${passageKey}`;
  }, [activeSection, activeReadingPassageId, activeListeningPart]);

  const notesForActiveContext = notesByContext[activeNoteContextKey] || [];
  const highlightsForActiveContext = highlightsByContext[activeNoteContextKey] || [];

  const addNoteForContext = useCallback((contextKey, options = {}) => {
    if (!contextKey) return;
    const {
      x: desiredX,
      y: desiredY,
      anchor = null,
      surfaceId: overrideSurfaceId = null,
      highlightId = null,
    } = options || {};
    const [x, y] = clampNotePosition(
      desiredX ?? 140,
      desiredY ?? 180
    );
    const newNote = {
      id: createNoteId(),
      x,
      y,
      content: "",
      isCollapsed: false,
      anchor: anchor || null,
      surfaceId: overrideSurfaceId || anchor?.surfaceId || null,
      highlightId: highlightId || null,
    };
    setNotesByContext((prev) => {
      const existing = prev[contextKey] || [];
      return {
        ...prev,
        [contextKey]: [...existing, newNote],
      };
    });
  }, []);

  const updateNotePositionForContext = useCallback((contextKey, noteId, nextX, nextY) => {
    if (!contextKey || !noteId) return;
    const [x, y] = clampNotePosition(nextX, nextY);
    setNotesByContext((prev) => {
      const existing = prev[contextKey] || [];
      let didChange = false;
      const nextNotes = existing.map((note) => {
        if (note.id !== noteId) return note;
        if (note.isCollapsed) return note;
        didChange = true;
        return { ...note, x, y };
      });
      if (!didChange) return prev;
      return { ...prev, [contextKey]: nextNotes };
    });
  }, []);

  const updateNoteContentForContext = useCallback((contextKey, noteId, nextContent) => {
    if (!contextKey || !noteId) return;
    setNotesByContext((prev) => {
      const existing = prev[contextKey] || [];
      let didChange = false;
      const nextNotes = existing.map((note) => {
        if (note.id !== noteId) return note;
        didChange = true;
        return { ...note, content: nextContent };
      });
      if (!didChange) return prev;
      return { ...prev, [contextKey]: nextNotes };
    });
  }, []);

  const deleteNoteForContext = useCallback((contextKey, noteId) => {
    if (!contextKey || !noteId) return;
    let highlightIdToRemove = null;
    setNotesByContext((prev) => {
      const existing = prev[contextKey] || [];
      const targetNote = existing.find((note) => note.id === noteId);
      highlightIdToRemove = targetNote?.highlightId || null;
      const nextNotes = existing.filter((note) => note.id !== noteId);
      if (nextNotes.length === existing.length) return prev;
      if (nextNotes.length === 0) {
        const { [contextKey]: _removed, ...rest } = prev;
        return rest;
      }
      return { ...prev, [contextKey]: nextNotes };
    });

    if (highlightIdToRemove) {
      setHighlightsByContext((prev) => {
        const existing = prev[contextKey] || [];
        const nextHighlights = existing.filter((highlight) => highlight.id !== highlightIdToRemove);
        if (nextHighlights.length === existing.length) return prev;
        if (nextHighlights.length === 0) {
          const { [contextKey]: _removed, ...rest } = prev;
          return rest;
        }
        return { ...prev, [contextKey]: nextHighlights };
      });
    }
  }, []);

  const setNoteCollapsedForContext = useCallback((contextKey, noteId, nextCollapsed) => {
    if (!contextKey || !noteId) return;
    setNotesByContext((prev) => {
      const existing = prev[contextKey] || [];
      let didChange = false;
      const nextNotes = existing.map((note) => {
        if (note.id !== noteId) return note;
        if (note.isCollapsed === nextCollapsed) return note;
        didChange = true;
        return { ...note, isCollapsed: nextCollapsed };
      });
      if (!didChange) return prev;
      return { ...prev, [contextKey]: nextNotes };
    });
  }, []);

  const addHighlightForContext = useCallback((contextKey, highlight) => {
    if (!contextKey || !highlight) return;
    setHighlightsByContext((prev) => {
      const existing = prev[contextKey] || [];
      if (highlight.id && existing.some((entry) => entry.id === highlight.id)) {
        return prev;
      }
      return { ...prev, [contextKey]: [...existing, highlight] };
    });
  }, []);

  const createNoteForHighlightInContext = useCallback(
    (contextKey, highlight) => {
      if (!contextKey || !highlight) return;

      setNotesByContext((prev) => {
        const existingNotes = prev[contextKey] || [];
        if (highlight.id && existingNotes.some((note) => note.highlightId === highlight.id)) {
          return prev;
        }

        const rects = Array.isArray(highlight.rects) ? highlight.rects : [];
        const lastRect = rects.length > 0 ? rects[rects.length - 1] : null;
        const surfaceId = highlight.surfaceId || "exam-main-surface";

        let anchor = null;
        let noteX = 160;
        let noteY = 180;

        if (lastRect) {
          const approxHalfChar = Math.max(Math.min(lastRect.width || 0, 14) / 2, 3);
          anchor = {
            surfaceId,
            x: Math.max(lastRect.x + lastRect.width - approxHalfChar, 0),
            y: Math.max(lastRect.y, 0),
            baseline: Math.max(lastRect.y + lastRect.height, 0),
            width: lastRect.width || 0,
          };

          if (typeof document !== "undefined") {
            const surfaceSelector = `[data-highlight-surface-id="${surfaceId}"]`;
            const surfaceElement =
              document.querySelector(surfaceSelector) ||
              document.querySelector("[data-highlight-surface-id='exam-main-surface']");
            const surfaceRect = surfaceElement?.getBoundingClientRect();
            const scrollLeft = surfaceElement?.scrollLeft || 0;
            const scrollTop = surfaceElement?.scrollTop || 0;
            const viewportX = surfaceRect
              ? surfaceRect.left + (lastRect.x - scrollLeft) + lastRect.width + 20
              : lastRect.x + lastRect.width + 20;
            const viewportY = surfaceRect
              ? surfaceRect.top + (lastRect.y - scrollTop) - 10
              : lastRect.y - 10;
            const [clampedX, clampedY] = clampNotePosition(viewportX, viewportY);
            noteX = clampedX;
            noteY = clampedY;
          }
        }

        const [finalX, finalY] = clampNotePosition(noteX, noteY);

        const newNote = {
          id: createNoteId(),
          x: finalX,
          y: finalY,
          content: "",
          isCollapsed: false,
          anchor,
          surfaceId,
          highlightId: highlight.id || null,
        };

        return {
          ...prev,
          [contextKey]: [...existingNotes, newNote],
        };
      });
    },
    []
  );

  const updateNoteColorForContext = useCallback((contextKey, noteId, nextColor) => {
    if (!contextKey || !noteId) return;
    setNotesByContext((prev) => {
      const existing = prev[contextKey] || [];
      let didChange = false;
      const nextNotes = existing.map((note) => {
        if (note.id !== noteId) return note;
        if (note.color === nextColor) return note;
        didChange = true;
        return { ...note, color: nextColor };
      });
      if (!didChange) return prev;
      return { ...prev, [contextKey]: nextNotes };
    });
  }, []);

  const updateNoteFontSizeForContext = useCallback((contextKey, noteId, nextFontSize) => {
    if (!contextKey || !noteId) return;
    setNotesByContext((prev) => {
      const existing = prev[contextKey] || [];
      let didChange = false;
      const nextNotes = existing.map((note) => {
        if (note.id !== noteId) return note;
        if (note.fontSize === nextFontSize) return note;
        didChange = true;
        return { ...note, fontSize: nextFontSize };
      });
      if (!didChange) return prev;
      return { ...prev, [contextKey]: nextNotes };
    });
  }, []);

  const updateNotePreviewAngleForContext = useCallback((contextKey, noteId, nextAngle) => {
    if (!contextKey || !noteId) return;
    setNotesByContext((prev) => {
      const existing = prev[contextKey] || [];
      let didChange = false;
      const nextNotes = existing.map((note) => {
        if (note.id !== noteId) return note;
        if (note.previewAngle === nextAngle) return note;
        didChange = true;
        return { ...note, previewAngle: nextAngle };
      });
      if (!didChange) return prev;
      return { ...prev, [contextKey]: nextNotes };
    });
  }, []);

  const removeHighlightForContext = useCallback((contextKey, highlightId) => {
    if (!contextKey || !highlightId) return;
    setHighlightsByContext((prev) => {
      const existing = prev[contextKey] || [];
      const nextHighlights = existing.filter((entry) => entry.id !== highlightId);
      if (nextHighlights.length === existing.length) return prev;
      if (nextHighlights.length === 0) {
        const { [contextKey]: _removed, ...rest } = prev;
        return rest;
      }
      return { ...prev, [contextKey]: nextHighlights };
    });

    setNotesByContext((prev) => {
      const existingNotes = prev[contextKey] || [];
      if (existingNotes.length === 0) return prev;
      const nextNotes = existingNotes.filter(
        (note) => note?.highlightId !== highlightId
      );
      if (nextNotes.length === existingNotes.length) return prev;
      if (nextNotes.length === 0) {
        const { [contextKey]: _removedNotes, ...rest } = prev;
        return rest;
      }
      return { ...prev, [contextKey]: nextNotes };
    });
  }, []);

  return {
    notesByContext,
    setNotesByContext,
    highlightsByContext,
    setHighlightsByContext,
    activeNoteContextKey,
    notesForActiveContext,
    highlightsForActiveContext,
    addNoteForContext,
    updateNotePositionForContext,
    updateNotePreviewAngleForContext,
    updateNoteFontSizeForContext,
    updateNoteColorForContext,
    updateNoteContentForContext,
    deleteNoteForContext,
    setNoteCollapsedForContext,
    addHighlightForContext,
    createNoteForHighlightInContext,
    removeHighlightForContext,
  };
};
