import React from "react";
import { generateId } from "../../../../utils/question/idUtils";

function SpeakingBuilder({ data, onChange, options = {}, onOptionsChange = () => { } }) {
  const speaking = {
    parts: [],
    ...data,
  };

  const updateParts = (parts) =>
    onChange({
      ...speaking,
      parts,
    });

  const handlePartChange = (index, updates) => {
    updateParts(
      speaking.parts.map((part, idx) =>
        idx === index ? { ...part, ...updates } : part
      )
    );
  };

  const handleAddPart = () => {
    updateParts([
      ...(speaking.parts || []),
      {
        id: generateId("S"),
        title: `Part ${speaking.parts.length + 1}`,
        prompt: "",
        preparationTime: "",
        speakingTime: "",
      },
    ]);
  };

  const handleRemovePart = (index) => {
    updateParts(speaking.parts.filter((_, idx) => idx !== index));
  };

  return (
    <div className="space-y-8">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <h3 className="text-lg font-semibold text-slate-900">Speaking parts</h3>
          <div className="flex items-center gap-3">
            <label className="block text-xs font-medium text-slate-600">Speaking option</label>
            <select
              value={(options?.speakingMode) || '1v1'}
              onChange={(e) => onOptionsChange({ speakingMode: e.target.value })}
              className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm text-slate-700"
            >
              <option value="in-app">In-app speaking</option>
              <option value="1v1">1 vs 1 (teacher via Google Meet)</option>
            </select>
            {/* If 1v1 speaking, allow optional meet link */}
            {options?.speakingMode === '1v1' && (
              <div className="flex items-center gap-2">
                <input
                  type="text"
                  placeholder="Google Meet URL (optional)"
                  value={options.speakingMeetUrl || ""}
                  onChange={(e) => onOptionsChange({ speakingMeetUrl: e.target.value })}
                  className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm text-slate-700 w-64"
                />
              </div>
            )}
          </div>
        </div>
        {options.speakingMode !== '1v1' && (
          <button
            type="button"
            onClick={handleAddPart}
            className="rounded-lg border border-blue-200 px-3 py-1.5 text-sm font-medium text-blue-700 transition hover:bg-blue-50"
          >
            + Add part
          </button>
        )}
      </div>

      <div className="space-y-6">
        {speaking.parts?.map((part, index) => (
          <div
            key={part.id}
            data-question-id={part.id}
            className="space-y-4 rounded-2xl border border-slate-200 bg-slate-50 p-5"
          >
            <div className="flex items-start justify-between gap-3">
              <input
                type="text"
                value={part.title}
                onChange={(event) =>
                  handlePartChange(index, { title: event.target.value })
                }
                className="flex-1 rounded-xl border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-800 focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
              />
              <button
                type="button"
                onClick={() => handleRemovePart(index)}
                className="text-xs font-semibold text-rose-500 hover:text-rose-600"
              >
                Remove
              </button>
            </div>

            <textarea
              value={part.prompt}
              onChange={(event) =>
                handlePartChange(index, { prompt: event.target.value })
              }
              rows={4}
              className="w-full rounded-xl border border-slate-200 px-4 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
              placeholder="Describe the focus of this speaking part."
            />

            <div className="grid gap-4 md:grid-cols-2">
              <div>
                <label className="text-xs font-semibold uppercase tracking-wide text-slate-500">
                  Preparation time
                </label>
                <input
                  type="text"
                  value={part.preparationTime || ""}
                  onChange={(event) =>
                    handlePartChange(index, {
                      preparationTime: event.target.value,
                    })
                  }
                  className="mt-1 w-full rounded-xl border border-slate-200 px-4 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
                  placeholder="e.g. 1 minute"
                />
              </div>
              <div>
                <label className="text-xs font-semibold uppercase tracking-wide text-slate-500">
                  Speaking time
                </label>
                <input
                  type="text"
                  value={part.speakingTime || ""}
                  onChange={(event) =>
                    handlePartChange(index, {
                      speakingTime: event.target.value,
                    })
                  }
                  className="mt-1 w-full rounded-xl border border-slate-200 px-4 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
                  placeholder="e.g. 2 minutes"
                />
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default SpeakingBuilder;
