import React from "react";
import { useQuestionContext } from "../../../contexts/QuestionContext";
import MultipleChoicePreview from "./Preview";

/**
 * MultipleChoiceBuilder - Uses Preview component with editMode for WYSIWYG editing
 */
const MultipleChoiceBuilder = ({ question: questionProp, onUpdate: onUpdateProp }) => {
  // Try to get from props first, fallback to context
  const context = useQuestionContext();
  const question = questionProp || context?.question;
  const onUpdate = onUpdateProp || context?.updateQuestion;

  // Check if this is a subQuestions-based format
  const hasSubQuestions = Array.isArray(question?.subQuestions) && question.subQuestions.length > 0;

  if (hasSubQuestions) { 
    // For subQuestions format, show content and allow editing sub-questions
    return (
      <div className="space-y-4">
        {/* Content editor */}
        <div>
          <label className="block text-sm font-medium text-slate-700 mb-2">
            Passage/Content
          </label>
          <textarea
            value={question.content || ""}
            onChange={(e) => onUpdate({ ...question, content: e.target.value })}
            rows={6}
            className="w-full rounded border border-slate-300 px-3 py-2 text-sm font-mono"
            placeholder="Enter the passage with numbered blanks like __1__, __2__, etc."
          />
        </div>

        {/* Sub-questions editor */}
        <div className="border-t pt-4">
          <h4 className="text-sm font-medium text-slate-700 mb-3">Questions</h4>
          {question.subQuestions.map((subQ, idx) => (
            <div key={`subq-${idx}`} className="mb-4 p-3 border border-slate-200 rounded bg-slate-50">
              <div className="mb-3">
                <label className="block text-xs font-medium text-slate-600 mb-1">
                  Question {idx + 1} Prompt
                </label>
                <input
                  type="text"
                  value={subQ.prompt || ""}
                  onChange={(e) => {
                    const newSubQuestions = [...question.subQuestions];
                    newSubQuestions[idx] = { ...subQ, prompt: e.target.value };
                    onUpdate({ ...question, subQuestions: newSubQuestions });
                  }}
                  className="w-full rounded border border-slate-300 px-2 py-1 text-sm"
                  placeholder="Question prompt"
                />
              </div>

              <div className="mb-3">
                <label className="block text-xs font-medium text-slate-600 mb-1">
                  Correct Answer(s) (comma-separated for multiple)
                </label>
                <input
                  type="text"
                  value={Array.isArray(subQ.correctAnswers) ? subQ.correctAnswers.join(", ") : subQ.correctAnswers || ""}
                  onChange={(e) => {
                    const newSubQuestions = [...question.subQuestions];
                    newSubQuestions[idx] = {
                      ...subQ,
                      correctAnswers: e.target.value.split(",").map(a => a.trim()).filter(a => a),
                    };
                    onUpdate({ ...question, subQuestions: newSubQuestions });
                  }}
                  className="w-full rounded border border-slate-300 px-2 py-1 text-sm"
                  placeholder="Correct answer letter(s)"
                />
              </div>

              <div>
                <label className="block text-xs font-medium text-slate-600 mb-2">Options</label>
                {subQ.options?.map((opt, oIdx) => (
                  <div key={`opt-${oIdx}`} className="mb-2 flex gap-2 items-center">
                    <span className="text-xs font-semibold text-slate-600 w-6">{String.fromCharCode(65 + oIdx)}.</span>
                    <input
                      type="text"
                      value={opt.label || ""}
                      onChange={(e) => {
                        const newSubQuestions = [...question.subQuestions];
                        newSubQuestions[idx].options[oIdx] = {
                          ...opt,
                          label: e.target.value,
                          value: e.target.value,
                        };
                        onUpdate({ ...question, subQuestions: newSubQuestions });
                      }}
                      className="flex-1 rounded border border-slate-300 px-2 py-1 text-sm"
                      placeholder="Option text"
                    />
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  // Use Preview component with editMode for single-question format
  return (
    <MultipleChoicePreview
      question={question}
      editMode={true}
      onQuestionChange={onUpdate}
    />
  );
};

export default MultipleChoiceBuilder;
