import { generateId } from "./idUtils";
import { parseGapContent } from "./gapFilling";

const createCell = () => ({
  id: generateId("cell"),
  content: "",
  colSpan: 1,
  rowSpan: 1,
  isSpanned: false,
});

const createRow = ({ type = "body", columnCount = 3 } = {}) => ({
  id: generateId("row"),
  type,
  cells: Array.from({ length: columnCount }).map(() => createCell()),
});

export const createDefaultGapFillTable = () => ({
  caption: "",
  rows: [
    createRow({ type: "header", columnCount: 3 }),
    createRow({ type: "body", columnCount: 3 }),
  ],
});

export const ensureGapFillTable = (table) => {
  if (!table || typeof table !== "object") {
    return createDefaultGapFillTable();
  }

  const columnCount = (() => {
    const rows = Array.isArray(table.rows) ? table.rows : [];
    let max = 0;
    for (const row of rows) {
      const len = Array.isArray(row?.cells) ? row.cells.length : 0;
      if (len > max) max = len;
    }
    return max > 0 ? max : 3;
  })();

  return {
    caption: typeof table.caption === "string" ? table.caption : "",
    rows: Array.isArray(table.rows) && table.rows.length > 0
      ? table.rows.map((row, rowIndex) => {
        const cells = Array.isArray(row?.cells) ? row.cells : [];
        // Build normalized cells respecting colSpan — don't pad beyond what spans cover
        const normalizedCells = [];
        let spannedCols = 0;
        for (let cellIndex = 0; cellIndex < cells.length && spannedCols < columnCount; cellIndex++) {
          const source = cells[cellIndex];
          const content = typeof source?.content === "string" ? source.content : "";
          const colSpan = Number.isInteger(source?.colSpan) && source.colSpan > 1 ? source.colSpan : 1;
          const rowSpan = Number.isInteger(source?.rowSpan) && source.rowSpan > 1 ? source.rowSpan : 1;
          normalizedCells.push({
            id: source?.id || generateId(`cell-${rowIndex}-${cellIndex}`),
            content,
            colSpan,
            rowSpan,
            isSpanned: Boolean(source?.isSpanned),
          });
          spannedCols += colSpan;
        }
        // Pad with empty cells if total span doesn't reach columnCount
        while (spannedCols < columnCount) {
          normalizedCells.push({
            id: generateId(`cell-${rowIndex}-${normalizedCells.length}`),
            content: "",
            colSpan: 1,
            rowSpan: 1,
            isSpanned: false,
          });
          spannedCols += 1;
        }

        return {
          id: row?.id || generateId(`row-${rowIndex}`),
          type: row?.type === "header" ? "header" : "body",
          cells: normalizedCells,
        };
      })
      : createDefaultGapFillTable().rows,
  };
};

export const parseGapFillTablePlaceholders = (table) => {
  const normalized = ensureGapFillTable(table);
  const placeholders = [];

  normalized.rows.forEach((row) => {
    row.cells.forEach((cell) => {
      if (cell.isSpanned) {
        return;
      }
      const { placeholders: cellPlaceholders } = parseGapContent(cell.content || "");
      cellPlaceholders.forEach((placeholder) => {
        placeholders.push({
          ...placeholder,
          rowId: row.id,
          cellId: cell.id,
        });
      });
    });
  });

  return { table: normalized, placeholders };
};

export const synchronizeGapFillTableQuestion = (currentQuestion = {}, options = {}) => {
  const nextTable = options.table ? ensureGapFillTable(options.table) : ensureGapFillTable(currentQuestion.table);
  const { placeholders } = parseGapFillTablePlaceholders(nextTable);

  const existingSubQuestions = Array.isArray(currentQuestion.subQuestions)
    ? currentQuestion.subQuestions
    : [];
  const existingAnswers = Array.isArray(currentQuestion.correctAnswers)
    ? currentQuestion.correctAnswers
    : [];

  const nextSubQuestions = placeholders.map((placeholder, index) => {
    const candidate = existingSubQuestions[index];
    const baseAnswer = candidate?.correctAnswers?.[0] ?? existingAnswers[index] ?? "";
    const displayNumber = placeholder.hasExplicitNumber
      ? placeholder.number
      : index + 1;

    return {
      id: candidate?.id || generateId("SQ"),
      number: candidate?.number || String(displayNumber),
      prompt:
        candidate?.prompt && candidate.prompt.trim().length > 0
          ? candidate.prompt
          : `Answer for blank ${displayNumber}`,
      type: "text",
      gapIndex: displayNumber,
      rowId: placeholder.rowId,
      cellId: placeholder.cellId,
      correctAnswers: [baseAnswer || ""],
    };
  });

  const nextCorrectAnswers = nextSubQuestions.map((sub) => sub.correctAnswers?.[0] || "");

  return {
    ...currentQuestion,
    table: nextTable,
    subQuestions: nextSubQuestions,
    correctAnswers: nextCorrectAnswers,
  };
};

export const countGapFillTableSlots = (question = {}) => {
  const { placeholders } = parseGapFillTablePlaceholders(question.table);
  const answersLength = Array.isArray(question.correctAnswers)
    ? question.correctAnswers.length
    : 0;
  const subQuestions = Array.isArray(question.subQuestions) ? question.subQuestions : [];
  const subQuestionLength = subQuestions.length;
  const placeholderCount = placeholders.length;

  const baseCount = Math.max(placeholderCount, answersLength, subQuestionLength, 1);
  const groupedCount = subQuestions.filter(sq => sq.isGrouped).length;

  return Math.max(baseCount - groupedCount, 1);
};
