import { useCallback, useEffect, useRef, useState } from 'react';
import { submitExamResult } from '../../../controller/useFirebase';

// ── SaveIndicator ─────────────────────────────────────────────────────────────
// Floating toast driven by the saveIndicator value from useAutosave.
// Lives in this file because it has no reason to exist without the hook.

export function SaveIndicator({ state }) {
  if (!state) return null;
  return (
    <div
      className={`fixed bottom-12 right-4 z-modal flex items-center gap-2.5 rounded-xl border border-white/20 px-4 py-2.5 text-[11px] font-semibold tracking-wide shadow-2xl backdrop-blur-md transition-all duration-500 animate-in fade-in slide-in-from-bottom-2
        ${state === 'saving'
          ? 'bg-amber-500/90 text-white shadow-amber-500/20'
          : state === 'error'
            ? 'bg-rose-600/90 text-white shadow-rose-600/20'
            : 'bg-emerald-500/90 text-white shadow-emerald-500/20'
        }`}
    >
      {state === 'saving' ? (
        <>
          <svg className="h-3.5 w-3.5 animate-spin" viewBox="0 0 24 24" fill="none">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
          </svg>
          SAVING...
        </>
      ) : state === 'error' ? (
        <>
          <svg className="h-3.5 w-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
            <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v4m0 4h.01M10.29 3.86l-7.4 12.8A1 1 0 003.75 18h16.5a1 1 0 00.86-1.34l-7.4-12.8a1 1 0 00-1.72 0z" />
          </svg>
          SAVE FAILED
        </>
      ) : (
        <>
          <svg className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3">
            <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
          </svg>
          SAVED
        </>
      )}
    </div>
  );
}

// ── useAutosave ───────────────────────────────────────────────────────────────
// Layer 1 of the submission safety net.
//
// Saves all current answers to localStorage every 15 seconds and on Ctrl+S.
// Also owns answersRef — kept in sync every render so that handleConfirmSubmit
// can read the latest answers without stale-closure risk.
//
// Guards: does NOT fire in preview/history mode or after final submission.
//
// Key:     weaver_${examCode}_autosave
// Cleared: on successful submission via clearPersistedExamStorage()
// Restored: Layer 2 (AutosaveRestoreModal) on next visit
//
// See: scripts/cross-project_communication/exam_resilience.md → Layer 1 & Layer 7

export function useAutosave({ examCode, isPreviewMode, isHistoryMode, hasSubmitted, answers, activeSection, skillTimeLeftSeconds, submittedSections, startedAt, listeningPartState }) {
  // Layer 7: answersRef keeps the submit flow free of stale closures.
  // Read answersRef.current in handleConfirmSubmit instead of captured `answers`.
  const answersRef = useRef(answers);
  answersRef.current = answers;
  const activeSectionRef = useRef(activeSection);
  activeSectionRef.current = activeSection;
  const skillTimeLeftRef = useRef(skillTimeLeftSeconds);
  skillTimeLeftRef.current = skillTimeLeftSeconds;
  const submittedSectionsRef = useRef(submittedSections);
  submittedSectionsRef.current = submittedSections;
  const startedAtRef = useRef(startedAt);
  startedAtRef.current = startedAt;
  const listeningPartStateRef = useRef(listeningPartState);   // NEW
  listeningPartStateRef.current = listeningPartState;          // NEW

  const [saveIndicator, setSaveIndicator] = useState(null); // null | 'saving' | 'saved' | 'error'
  const saveIndicatorTimerRef = useRef(null);

  const doSave = useCallback((source) => {
    if (!examCode || isPreviewMode || isHistoryMode || hasSubmitted) return;
    const current = answersRef.current;
    if (!current || Object.keys(current).length === 0) return;
    try {
      const autosaveKey = `weaver_${examCode}_autosave`;
      const payload = {
        answers: current,
        savedAt: new Date().toISOString(),
        examCode,
        activeSection: activeSectionRef.current || null,
        skillTimeLeftSeconds: (typeof skillTimeLeftRef.current === 'number')
          ? skillTimeLeftRef.current
          : null,
        submittedSections: submittedSectionsRef.current || [],
        startedAt: startedAtRef.current || null,
        listeningPartState: listeningPartStateRef.current || null,   // NEW
      };
      localStorage.setItem(autosaveKey, JSON.stringify(payload));
    } catch (e) {
      /* localStorage full or blocked — always show error */
      setSaveIndicator('error');
      if (saveIndicatorTimerRef.current) clearTimeout(saveIndicatorTimerRef.current);
      saveIndicatorTimerRef.current = setTimeout(() => setSaveIndicator(null), 2000);
      return;
    }
    if (source === 'manual') {
      setSaveIndicator('saving');
      if (saveIndicatorTimerRef.current) clearTimeout(saveIndicatorTimerRef.current);
      saveIndicatorTimerRef.current = setTimeout(() => {
        setSaveIndicator('saved');
        saveIndicatorTimerRef.current = setTimeout(() => setSaveIndicator(null), 1200);
      }, 400);
    }
  }, [examCode, isPreviewMode, isHistoryMode, hasSubmitted]);

  const triggerSave = useCallback(() => {
    doSave('manual');
  }, [doSave]);

  // Periodic autosave every 15s — silent, no toast
  useEffect(() => {
    if (!examCode || isPreviewMode || isHistoryMode || hasSubmitted) return;
    const interval = setInterval(() => doSave('periodic'), 15_000);
    return () => clearInterval(interval);
  }, [examCode, isPreviewMode, isHistoryMode, hasSubmitted, doSave]);

  // Ctrl+S manual save
  useEffect(() => {
    const handleKeyDown = (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 's') {
        e.preventDefault();
        e.stopPropagation();
        triggerSave();
      }
    };
    window.addEventListener('keydown', handleKeyDown, { capture: true });
    return () => window.removeEventListener('keydown', handleKeyDown, { capture: true });
  }, [triggerSave]);

  return { answersRef, triggerSave, saveIndicator };
}

export function useSubmissionRecovery({ urlExamCode, isHistoryMode }) {
  const [hasPendingSubmission, setHasPendingSubmission] = useState(false);
  const [recoveredInThisSession, setRecoveredInThisSession] = useState(false);
  const [isRecovering, setIsRecovering] = useState(false);
  const [recoveredResult, setRecoveredResult] = useState(null);
  const isRetryingRef = useRef(false);

  useEffect(() => {
    if (!urlExamCode || isHistoryMode) {
      console.log('🔄 [Recovery] Hook skipped — urlExamCode:', urlExamCode, 'isHistoryMode:', isHistoryMode);
      return;
    }

    console.log('🔄 [Recovery] Hook initialized for', urlExamCode);
    const pendingKey = `weaver_${urlExamCode}_pending_submission`;
    let retryInterval = null;

    const checkPending = () => {
      try {
        const raw = localStorage.getItem(pendingKey);
        if (!raw) {
          //console.log('🔄 [Recovery] checkPending: no pending_submission found');
          setHasPendingSubmission(false);
          return null;
        }
        const payload = JSON.parse(raw);
        if (!payload || typeof payload !== 'object') return null;

        // Pre-existing synced payload from a previous attempt.
        // Do NOT treat as a recovery — it was already written to Firestore.
        // Do NOT delete it — it's needed for /history route and audit trail.
        if (payload.synced) {
          console.log('🔄 [Recovery] checkPending: found old synced payload (syncedAt:', payload.syncedAt, ') — ignoring, not recovering');
          setHasPendingSubmission(false);
          return null;
        }

        console.log('🔄 [Recovery] checkPending: found unsynced pending_submission — will attempt recovery');
        setHasPendingSubmission(true);
        return payload;
      } catch (_) {
        return null;
      }
    };

    const attemptRecovery = async () => {
      if (isRetryingRef.current) {
        console.log('🔄 [Recovery] attemptRecovery: skipped — already retrying');
        return;
      }
      const pendingPayload = checkPending();
      if (!pendingPayload) return;

      isRetryingRef.current = true;
      setIsRecovering(true);
      try {
        console.warn('🔁 [Recovery] Found pending submission — retrying Firestore write...');
        await submitExamResult(urlExamCode, pendingPayload);

        const syncedPayload = { ...pendingPayload, synced: true, syncedAt: Date.now() };
        localStorage.setItem(pendingKey, JSON.stringify(syncedPayload));

        console.log('✅ [Recovery] Pending submission recovered and written to Firestore successfully');
        setRecoveredInThisSession(true);
        setIsRecovering(false);
        setRecoveredResult(syncedPayload);
      } catch (err) {
        console.error('❌ [Recovery] Failed to recover pending submission:', err.message);
        setIsRecovering(false);
      } finally {
        isRetryingRef.current = false;
      }
    };

    attemptRecovery();
    retryInterval = setInterval(() => {
      //console.log('🔄 [Recovery] 7s interval tick');
      attemptRecovery();
    }, 7_000);

    return () => {
      console.log('🔄 [Recovery] Hook cleanup — clearing interval');
      if (retryInterval) clearInterval(retryInterval);
    };
  }, [urlExamCode, isHistoryMode]);

  return { hasPendingSubmission, recoveredInThisSession, isRecovering, recoveredResult };
}
