import React from "react";
import { useQuestionContext } from "../../../contexts/QuestionContext";
import { cloneDefaultOptions } from "../../../utils/question/questionUtils";

const ensureOptions = (options) => {
  if (Array.isArray(options) && options.length > 0) {
    return options.map((option) => ({ ...option }));
  }
  return cloneDefaultOptions();
};

const ChoiceOptionsEditor = ({ allowMultiple = false }) => {
  const { question, updateQuestion } = useQuestionContext();
  const options = ensureOptions(question?.options);

  const handleOptionChange = (index, field, value) => {
    updateQuestion((current = question) => {
      const nextOptions = ensureOptions(current.options);
      nextOptions[index] = {
        ...nextOptions[index],
        [field]: value,
      };
      return {
        ...current,
        options: nextOptions,
      };
    });
  };

  const handleAddOption = () => {
    updateQuestion((current = question) => {
      const nextOptions = ensureOptions(current.options);
      const optionIndex = nextOptions.length;
      const letter = String.fromCharCode(65 + optionIndex);
      nextOptions.push({
        label: `Option ${letter}`,
        value: letter,
      });
      return {
        ...current,
        options: nextOptions,
      };
    });
  };

  const handleRemoveOption = (index) => {
    updateQuestion((current = question) => {
      const nextOptions = ensureOptions(current.options).filter((_, idx) => idx !== index);
      return {
        ...current,
        options: nextOptions.length ? nextOptions : cloneDefaultOptions(),
      };
    });
  };

  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between">
        <p className="text-xs font-medium uppercase tracking-wide text-slate-500">
          Choice options
        </p>
        <button
          type="button"
          onClick={handleAddOption}
          className="rounded border border-blue-200 px-3 py-1 text-xs font-semibold text-blue-600 hover:bg-blue-50"
        >
          + Add option
        </button>
      </div>
      <div className="space-y-2">
        {options.map((option, index) => (
          <div key={`choice-option-${option.value}-${index}`} className="flex items-center gap-2">
            <span className="inline-flex h-7 w-7 flex-shrink-0 items-center justify-center rounded border border-slate-200 bg-slate-50 text-xs font-semibold text-slate-700">
              {String.fromCharCode(65 + index)}
            </span>
            <input
              type="text"
              value={option.label || ""}
              onChange={(event) => handleOptionChange(index, "label", event.target.value)}
              className="flex-1 rounded-lg border border-slate-200 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
              placeholder={`Option ${String.fromCharCode(65 + index)} label`}
            />
            <input
              type="text"
              value={option.value || ""}
              onChange={(event) => handleOptionChange(index, "value", event.target.value)}
              className="w-24 rounded-lg border border-slate-200 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
              placeholder="Value"
            />
            {options.length > 2 ? (
              <button
                type="button"
                onClick={() => handleRemoveOption(index)}
                className="rounded border border-red-200 px-2 py-1 text-xs font-semibold text-red-500 hover:bg-red-50"
              >
                Remove
              </button>
            ) : null}
          </div>
        ))}
      </div>
      <p className="text-[11px] text-slate-500">
        {allowMultiple
          ? "Learners can select multiple answers. Ensure the answer key lists every correct value."
          : "Learners can select one answer. Set the correct option using the answer input below."}
      </p>
    </div>
  );
};

export default ChoiceOptionsEditor;
