import React, { useState, useEffect } from "react";

const SpeakingFollowupModal = ({ isOpen, submitStatus, audioUploadSkipped, onClose, speakingMeetUrl, nonSpeakingCount = 0, onRetry }) => {
  const [visible, setVisible] = useState(false);
  const handleClose = () => {
    try { onClose?.(); } catch (e) { }
  };
  useEffect(() => {
    if (isOpen) setVisible(true);
    else {
      // Keep mounted for the exit animation duration (match CSS duration-300)
      const t = setTimeout(() => setVisible(false), 300);
      return () => clearTimeout(t);
    }
  }, [isOpen]);

  if (!isOpen && !visible) return null;
  return (
    <div
      aria-hidden={!isOpen}
      role="dialog"
      className={`fixed inset-0 z-modal flex items-center justify-center p-4 backdrop-blur-sm ${isOpen ? 'bg-black/40' : 'bg-black/20'} transition-colors duration-300`}
      // Prevent closing when clicking outside so students can't review answers
    >
      <div
        className={`w-full max-w-lg rounded-2xl bg-white p-6 shadow-xl transform transition-all duration-300 ${isOpen ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-95 translate-y-3'}`}
        onClick={(e) => e.stopPropagation()}
      >
        {/* ── SUBMITTING state ── */}
        {submitStatus === 'submitting' && (
          <>
            <div className="flex items-center gap-4">
              <div className="flex h-[60px] w-[60px] items-center justify-center">
                <svg className="animate-spin h-10 w-10 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
                </svg>
              </div>
              <div className="flex-1">
                <h2 className="text-lg md:text-xl font-semibold text-slate-900">Đang gửi bài thi...</h2>
                <p className="mt-1 text-sm text-slate-500">Vui lòng không đóng tab này.</p>
              </div>
            </div>
          </>
        )}

        {/* ── SUCCESS state ── */}
        {submitStatus === 'success' && (
          <>
            <div className="flex items-center gap-4">
              <div className="flex h-[60px] w-[60px] items-center justify-center bg-transparent shadow-none">
                <img src="/assets/images/celebration_icon.png" alt="Chúc mừng" className="h-full w-full object-contain" loading="lazy" />
              </div>
              <div className="flex-1">
                <h2 className="text-lg md:text-xl font-semibold text-slate-900">Chúc mừng bạn!</h2>
                <p className="mt-1 text-sm text-slate-600">Chúc mừng bạn đã nỗ lực hoàn thành xong phần thi!</p>
              </div>
            </div>
            
            {audioUploadSkipped && (
              <div className="mt-3 flex items-start gap-2 rounded-md bg-amber-50 border border-amber-200 px-3 py-2">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 shrink-0 text-amber-500 mt-0.5" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                </svg>
                <p className="text-xs text-amber-700">Phần ghi âm Speaking chưa được tải lên do kết nối mạng. Giáo viên sẽ liên hệ lại nếu cần.<br /><span className="text-amber-500">Speaking recordings could not be uploaded. Your teacher will follow up if needed.</span></p>
              </div>
            )}

            {speakingMeetUrl ? (
              <>
                <div className="mt-2 text-sm text-gray-600 space-y-3">
                  <div className="mt-3 flex items-start gap-3">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 shrink-0 text-orange-400 mt-1" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
                      <path d="M15 10l4.553-2.276a1 1 0 0 1 1.447.894v6.764a1 1 0 0 1-1.447.894L15 14" />
                      <rect x="3" y="5" width="12" height="14" rx="2" />
                    </svg>
                    <div>
                      <p className="text-sm text-slate-600">Tiếp theo, bạn sẽ tham gia bài thi SPEAKING qua Google Meet theo lịch hẹn trung tâm đã thông báo.</p>
                      <p className="mt-2 text-sm text-slate-600">Vui lòng truy cập vào link Google Meet do trung tâm cung cấp để hoàn thành phần thi Speaking (nếu có).</p>
                    </div>
                  </div>
                  <p>
                    Chúc bạn tự tin và làm bài tốt!
                  </p>
                </div>
                <div className="mt-6 flex gap-3">
                  <div className="flex-1">
                    <a
                      href={speakingMeetUrl}
                      target="_blank"
                      rel="noreferrer"
                      className="block w-full rounded-lg bg-orange-500 px-4 py-2 text-sm font-semibold text-white text-center transition hover:bg-orange-600"
                    >
                      Mở Google Meet
                    </a>
                  </div>
                  <button
                    onClick={onClose}
                    autoFocus
                    className="w-36 rounded-lg border border-orange-200 bg-orange-50 px-4 py-2 text-sm font-semibold text-orange-600 transition hover:bg-orange-100 focus:outline-none focus:ring-2 focus:ring-orange-200"
                  >
                    Về trang chủ
                  </button>
                </div>
              </>
            ) : (
              <>
                <div className="mt-4 text-sm text-gray-600 space-y-3">
                  <div className="flex items-start gap-3">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 shrink-0 text-orange-400 mt-1" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
                      <path d="M15 10l4.553-2.276a1 1 0 0 1 1.447.894v6.764a1 1 0 0 1-1.447.894L15 14" />
                      <rect x="3" y="5" width="12" height="14" rx="2" />
                    </svg>
                    <div>
                      <p className="text-sm text-slate-600">Bạn vẫn còn phần thi SPEAKING. Vui lòng liên hệ với trung tâm để được hướng dẫn hoàn thành phần thi này.</p>
                    </div>
                  </div>
                </div>
                <div className="mt-6 flex justify-end">
                  <button
                    onClick={onClose}
                    autoFocus
                    className="rounded-lg bg-emerald-500 px-6 py-2 text-sm font-semibold text-white transition hover:bg-emerald-600 focus:outline-none focus:ring-2 focus:ring-emerald-200"
                  >
                    Về trang chủ
                  </button>
                </div>
              </>
            )}
          </>
        )}

        {/* ── ERROR state ── */}
        {submitStatus === 'error' && (
          <>
            <div className="flex items-center gap-4">
              <div className="flex h-[60px] w-[60px] items-center justify-center text-4xl">
                &#9888;
              </div>
              <div className="flex-1">
                <h2 className="text-lg md:text-xl font-semibold text-red-700">Gửi bài thất bại!</h2>
                <p className="mt-1 text-sm text-slate-600">Bài thi chưa được gửi thành công. Câu trả lời đã được lưu tạm trên máy.</p>
              </div>
            </div>

            <div className="mt-4 rounded-lg bg-red-50 border border-red-200 p-4">
              <p className="text-sm font-semibold text-red-800">Đừng đóng tab này!</p>
              <p className="mt-1 text-sm text-red-700">Hệ thống sẽ tự động thử gửi lại. Bạn cũng có thể nhấn nút bên dưới để thử ngay.</p>
              <p className="mt-2 text-xs text-red-500">Your answers are saved locally. The system will auto-retry, or you can retry now.</p>
            </div>

            <div className="mt-6 flex justify-end gap-3">
              <button
                onClick={onRetry}
                className="rounded-lg bg-red-600 px-6 py-2 text-sm font-semibold text-white transition hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-red-200"
              >
                Thử gửi lại
              </button>
            </div>
          </>
        )}

      </div>
    </div>
  );
};

export default SpeakingFollowupModal;
