import { useEffect, useMemo, useRef, useCallback } from "react";
import { mergeRects, collectSurfaceRects } from "./useHighlightInteraction";

/**
 * Finds the Nth occurrence (occurrenceIndex) of searchText within a surface
 * element using TreeWalker, returning a DOM Range or null.
 */
function findRangeForText(surfaceElement, searchText, occurrenceIndex) {
  const walker = document.createTreeWalker(surfaceElement, NodeFilter.SHOW_TEXT, null);

  const textNodes = [];
  let node;
  while ((node = walker.nextNode())) {
    textNodes.push(node);
  }

  let fullText = "";
  const nodeOffsets = [];
  for (const textNode of textNodes) {
    const start = fullText.length;
    fullText += textNode.textContent;
    nodeOffsets.push({ node: textNode, start, end: start + textNode.textContent.length });
  }

  let searchFrom = 0;
  let matchStart = -1;
  for (let i = 0; i <= occurrenceIndex; i++) {
    const idx = fullText.indexOf(searchText, searchFrom);
    if (idx === -1) return null;
    matchStart = idx;
    searchFrom = idx + 1;
  }
  if (matchStart === -1) return null;

  const matchEnd = matchStart + searchText.length;
  const range = document.createRange();
  let rangeStartSet = false;

  for (const { node: textNode, start, end } of nodeOffsets) {
    if (end <= matchStart) continue;
    if (start >= matchEnd) break;
    if (!rangeStartSet) {
      range.setStart(textNode, matchStart - start);
      rangeStartSet = true;
    }
    range.setEnd(textNode, Math.min(matchEnd - start, textNode.textContent.length));
  }

  return rangeStartSet ? range : null;
}

function rectsChanged(oldRects, newRects) {
  if (!oldRects || !newRects || oldRects.length !== newRects.length) return true;
  for (let i = 0; i < oldRects.length; i++) {
    const o = oldRects[i];
    const n = newRects[i];
    if (Math.abs(o.x - n.x) > 1 || Math.abs(o.y - n.y) > 1 ||
        Math.abs(o.width - n.width) > 1 || Math.abs(o.height - n.height) > 1) {
      return true;
    }
  }
  return false;
}

const RESIZE_DEBOUNCE_MS = 100;

/**
 * Recalculates highlight rects by re-finding each highlight's text in the DOM
 * after reflow. Triggers on:
 *   - fontLevel change (React-driven)
 *   - window resize (covers browser zoom — Ctrl+/Ctrl- — which changes pixel
 *     coordinates without changing any React state)
 * Only calls updateHighlights if at least one rect actually moved.
 */
export function useHighlightRecalculation({ highlights, fontLevel, updateHighlights }) {
  // Refs let the recalc callback stay stable while still seeing latest values.
  const highlightsRef = useRef(highlights);
  highlightsRef.current = highlights;
  const updateHighlightsRef = useRef(updateHighlights);
  updateHighlightsRef.current = updateHighlights;

  const recalculate = useCallback(() => {
    const currentHighlights = highlightsRef.current;
    if (!currentHighlights || currentHighlights.length === 0) return;

    const occurrenceCounts = new Map();
    let anyChanged = false;

    const updated = currentHighlights.map((highlight) => {
      const { text, surfaceId, rects: oldRects } = highlight;
      if (!text || !surfaceId) return highlight;

      const key = `${surfaceId}:${text}`;
      const occurrenceIndex = occurrenceCounts.get(key) || 0;
      occurrenceCounts.set(key, occurrenceIndex + 1);

      const surfaceElement = document.querySelector(
        `[data-highlight-surface-id="${surfaceId}"]`
      );
      if (!surfaceElement) return highlight;

      const range = findRangeForText(surfaceElement, text, occurrenceIndex);
      if (!range) return highlight;

      // collectSurfaceRects splits the range around answer blanks, so the
      // carved-out blank survives reflow exactly as it was at creation time.
      const newRects = mergeRects(collectSurfaceRects(range, surfaceElement));
      if (!rectsChanged(oldRects, newRects)) return highlight;

      anyChanged = true;
      return { ...highlight, rects: newRects };
    });

    if (anyChanged) updateHighlightsRef.current(updated);
  }, []);

  // Trigger on fontLevel change (waits for reflow via rAF + setTimeout 0).
  useEffect(() => {
    if (!highlights || highlights.length === 0) return;
    const rafId = requestAnimationFrame(() => {
      setTimeout(recalculate, 0);
    });
    return () => cancelAnimationFrame(rafId);
  }, [fontLevel, recalculate]); // eslint-disable-line react-hooks/exhaustive-deps

  // Observe each surface element that owns highlights. ResizeObserver fires
  // whenever the surface's box changes size, which covers:
  //   - window resize (the surface flexes with the viewport)
  //   - browser zoom (rendered pixel sizes change)
  //   - split-pane drag in ReadingSection / GrammarSection (the surface's
  //     width changes mid-drag, reflowing the text)
  // Triggering recalc here keeps highlight rects glued to their text through
  // any of those reflows. Debounced because the observer fires rapidly during
  // a drag and recalc walks the whole surface DOM.
  const surfaceIdsKey = useMemo(() => {
    if (!Array.isArray(highlights)) return "";
    const ids = new Set();
    for (const h of highlights) {
      if (h?.surfaceId) ids.add(h.surfaceId);
    }
    return [...ids].sort().join("|");
  }, [highlights]);

  useEffect(() => {
    if (!surfaceIdsKey || typeof ResizeObserver === "undefined") return undefined;

    let debounceId = null;
    let rafId = null;
    const handleResize = () => {
      if (debounceId) clearTimeout(debounceId);
      debounceId = setTimeout(() => {
        if (rafId) cancelAnimationFrame(rafId);
        rafId = requestAnimationFrame(recalculate);
      }, RESIZE_DEBOUNCE_MS);
    };

    const observers = [];
    for (const surfaceId of surfaceIdsKey.split("|")) {
      if (!surfaceId) continue;
      const el = document.querySelector(
        `[data-highlight-surface-id="${surfaceId}"]`
      );
      if (!el) continue;
      const obs = new ResizeObserver(handleResize);
      obs.observe(el);
      observers.push(obs);
    }

    return () => {
      observers.forEach((o) => o.disconnect());
      if (debounceId) clearTimeout(debounceId);
      if (rafId) cancelAnimationFrame(rafId);
    };
  }, [surfaceIdsKey, recalculate]);
}
