import React, { useMemo, useCallback } from "react";
import { useQuestionContext } from "../../../contexts/QuestionContext";
import { useNumbering } from "../../../contexts/NumberingContext";
import { generateId } from "../../../utils/question/idUtils";
import { parseGapContent } from "../../../utils/question/gapFilling";
import { calculateGapNumber } from "../../../utils/question/questionTitleGenerator";

const synchronizeGapQuestion = (
  currentQuestion = {},
  { nextContent } = {}
) => {
  const content = nextContent !== undefined ? nextContent : currentQuestion.content || "";
  const { placeholders } = parseGapContent(content);

  const existingSubQuestions = Array.isArray(currentQuestion.subQuestions)
    ? currentQuestion.subQuestions
    : [];
  const existingAnswers = Array.isArray(currentQuestion.correctAnswers)
    ? currentQuestion.correctAnswers
    : [];

  const nextSubQuestions = placeholders.map((placeholder, index) => {
    const candidate = existingSubQuestions[index];
    const baseAnswer = candidate?.correctAnswers?.[0] ?? existingAnswers[index] ?? "";
    const displayNumber = placeholder.hasExplicitNumber
      ? placeholder.number
      : index + 1;

    return {
      id: candidate?.id || generateId("SQ"),
      number: candidate?.number || String(displayNumber),
      prompt:
        candidate?.prompt && candidate.prompt.trim().length > 0
          ? candidate.prompt
          : `Answer for gap ${displayNumber}`,
      type: "text",
      gapIndex: displayNumber,
      correctAnswers: [baseAnswer || ""],
      // Preserve options if they exist (from AI generation)
      ...(candidate?.options && candidate.options.length > 0 ? { options: candidate.options } : {})
    };
  });

  const nextCorrectAnswers = nextSubQuestions.map((sub) => sub.correctAnswers?.[0] || "");

  return {
    ...currentQuestion,
    content,
    subQuestions: nextSubQuestions,
    correctAnswers: nextCorrectAnswers,
  };
};

const GapFillingBuilder = () => {
  const { question, updateQuestion, sectionMeta } = useQuestionContext();
  
  // Get numbering context for global question numbering
  let numbering;
  try {
    // eslint-disable-next-line react-hooks/rules-of-hooks
    numbering = useNumbering();
  } catch {
    numbering = undefined;
  }

  const { placeholders } = useMemo(
    () => parseGapContent(question?.content || ""),
    [question?.content]
  );
  const blankCount = placeholders.length;
  
  // Calculate the starting gap number from global numbering context
  const gapStartNumber = useMemo(() => {
    if (!numbering || !sectionMeta?.sectionKey || !question?.id) {
      return 1;
    }
    const passageOrGroupId =
      sectionMeta.passageId != null
        ? sectionMeta.passageId
        : sectionMeta.groupId != null
        ? sectionMeta.groupId
        : null;
    
    const questionNumber = numbering.getQuestionStart(
      sectionMeta.sectionKey,
      passageOrGroupId,
      question.id
    );
    return questionNumber;
  }, [numbering, sectionMeta, question?.id]);

  const handleContentChange = useCallback(
    (event) => {
      const nextContent = event.target.value;
      updateQuestion((current = question) => synchronizeGapQuestion(current, { nextContent }));
    },
    [question, updateQuestion]
  );

  const handleHintChange = useCallback(
    (event) => {
      const nextHint = event.target.value;
      updateQuestion((current = question) => ({
        ...current,
        hint: nextHint,
      }));
    },
    [question, updateQuestion]
  );

  const handleAddBlank = useCallback(() => {
    const highestExplicitNumber = placeholders.reduce((highest, placeholder) => {
      if (placeholder.hasExplicitNumber && Number.isFinite(placeholder.number)) {
        return Math.max(highest, placeholder.number);
      }
      return highest;
    }, 0);
    const nextBlankNumber = highestExplicitNumber > 0
      ? highestExplicitNumber + 1
      : placeholders.length + 1;
    const currentContent = question?.content || "";
    const separator = currentContent.trim().length === 0 ? "" : " ";
    const shouldUseNumberedFormat = highestExplicitNumber > 0;
    const newPlaceholder = shouldUseNumberedFormat
      ? `(${nextBlankNumber}) `
      : `__${nextBlankNumber}__`;
    const trailingUnderscores = shouldUseNumberedFormat ? "______" : "";
    const updatedContent = `${currentContent}${separator}${newPlaceholder}${trailingUnderscores}`;

    updateQuestion((current = question) => synchronizeGapQuestion(current, { nextContent: updatedContent }));
  }, [placeholders, question, updateQuestion]);

  const handleAnswerChange = useCallback(
    (index, value) => {
      updateQuestion((current = question) => {
        const synchronized = synchronizeGapQuestion(current);
        const nextAnswers = [...synchronized.correctAnswers];
        nextAnswers[index] = value;
        const nextSubQuestions = synchronized.subQuestions.map((sub, subIndex) => ({
          ...sub,
          correctAnswers: [nextAnswers[subIndex] || ""],
        }));

        return {
          ...synchronized,
          subQuestions: nextSubQuestions,
          correctAnswers: nextAnswers,
        };
      });
    },
    [question, updateQuestion]
  );

  const answers = Array.isArray(question?.correctAnswers) ? question.correctAnswers : [];
  const subQuestions = Array.isArray(question?.subQuestions) ? question.subQuestions : [];
  
  const normalizedAnswers = useMemo(() => {
    const base = [];
    
    // Priority 1: Get from subQuestions.correctAnswers (from AI)
    // Priority 2: Get from question.correctAnswers (legacy format)
    for (let i = 0; i < blankCount; i++) {
      const subQAnswer = subQuestions[i]?.correctAnswers?.[0];
      const directAnswer = answers[i];
      base.push(subQAnswer || directAnswer || "");
    }
    
    return base;
  }, [answers, subQuestions, blankCount]);

  return (
    <div className="space-y-4">
      <div>
        <div className="flex items-center justify-between mb-2">
          <label className="text-xs font-medium uppercase tracking-wide text-slate-500">
            Passage Content
          </label>
          <button
            type="button"
            onClick={handleAddBlank}
            className="rounded border border-blue-200 px-3 py-1 text-xs font-semibold text-blue-600 hover:bg-blue-50"
          >
            + Add blank
          </button>
        </div>
        <p className="mb-2 text-xs text-slate-500">
          Use __1__, __2__, __3__, etc. to mark gap positions, or click "Add blank" to insert automatically
        </p>
        <textarea
          value={question?.content || ""}
          onChange={handleContentChange}
          className="h-40 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm text-slate-700 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
          placeholder="Enter passage content with gaps marked as __1__, __2__, etc."
        />
        {blankCount > 0 && (
          <p className="mt-2 text-xs text-slate-500">
            Found <strong>{blankCount}</strong> blank(s) in content
          </p>
        )}
      </div>

      <div>
        <label className="text-xs font-medium uppercase tracking-wide text-slate-500">
          Hint (Optional)
        </label>
        <input
          type="text"
          value={question?.hint || ""}
          onChange={handleHintChange}
          className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm text-slate-700 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
          placeholder="e.g., Choose NO MORE THAN THREE WORDS..."
        />
      </div>

      <div>
        <label className="text-xs font-medium uppercase tracking-wide text-slate-500">
          Answers for {blankCount} gap{blankCount !== 1 ? 's' : ''}
        </label>
        {blankCount === 0 ? (
          <div className="rounded border border-dashed border-slate-300 bg-slate-50 px-3 py-2 text-sm text-slate-500">
            Add blanks to the passage content to configure answers.
          </div>
        ) : (
          <div className="space-y-3 mt-2">
            {Array.from({ length: blankCount }).map((_, index) => {
              const answerNumber = index + 1;
              // Use global numbering if available, otherwise fallback to local calculation
              // Check both numbering and gapStartNumber are defined and gapStartNumber > 0
              const useGlobalNumbering = numbering && gapStartNumber && gapStartNumber > 0;
              const displayNumber = useGlobalNumbering
                ? calculateGapNumber(index, gapStartNumber)
                : (placeholders[index]?.number ?? answerNumber);
              
              // Get options for this gap (from AI generation)
              const gapOptions = subQuestions[index]?.options || [];
              
              return (
                <div key={`gap-answer-${index}`} className="space-y-2">
                  <div className="flex items-center gap-2">
                    <span className="inline-flex h-6 min-w-[2rem] flex-shrink-0 items-center justify-center rounded border border-slate-300 bg-slate-100 px-2 text-xs font-semibold text-slate-600">
                      {displayNumber}
                    </span>
                    <input
                      type="text"
                      value={normalizedAnswers[index] || ""}
                      onChange={(e) => handleAnswerChange(index, e.target.value)}
                      className="flex-1 rounded-lg border border-slate-300 px-3 py-2 text-sm text-slate-700 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
                      placeholder={`Answer for gap ${answerNumber}`}
                    />
                  </div>
                  
                  {/* Show options if they exist (from AI) */}
                  {gapOptions.length > 0 && (
                    <div className="ml-12 text-xs text-slate-600">
                      <span className="font-medium">Options: </span>
                      <span className="text-slate-500">
                        {gapOptions.map((opt, optIdx) => (
                          <span key={optIdx}>
                            {String.fromCharCode(65 + optIdx)}. {opt.label || opt.value || opt}
                            {optIdx < gapOptions.length - 1 ? ' | ' : ''}
                          </span>
                        ))}
                      </span>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

export default GapFillingBuilder;
