import React, { useRef, useEffect } from "react";
import { useQuestionContext } from "../../../contexts/QuestionContext";

const ensureLength = (source, minLength) => {
  const base = Array.isArray(source) ? [...source] : [];
  while (base.length < minLength) {
    base.push("");
  }
  return base;
};

const intToRoman = (num) => {
  const romanNumerals = [
    { value: 1000, numeral: "M" },
    { value: 900, numeral: "CM" },
    { value: 500, numeral: "D" },
    { value: 400, numeral: "CD" },
    { value: 100, numeral: "C" },
    { value: 90, numeral: "XC" },
    { value: 50, numeral: "L" },
    { value: 40, numeral: "XL" },
    { value: 10, numeral: "X" },
    { value: 9, numeral: "IX" },
    { value: 5, numeral: "V" },
    { value: 4, numeral: "IV" },
    { value: 1, numeral: "I" },
  ];

  let result = "";
  for (const { value, numeral } of romanNumerals) {
    while (num >= value) {
      result += numeral;
      num -= value;
    }
  }
  return result.toLowerCase();
};

const MatchingHeadingsBuilder = () => {
  const { question, updateQuestion } = useQuestionContext();
  const lastHeadingRef = useRef(null);
  const lastAnswerRef = useRef(null);
  const isInitialMount = useRef(true);

  const headingItems = ensureLength(question?.matchingHeadingItems, 3);
  const headingAnswers = Array.isArray(question?.matchingHeadingAnswers) 
    ? question.matchingHeadingAnswers 
    : [];

  // Auto-focus newly added heading - skip on initial mount
  useEffect(() => {
    if (isInitialMount.current) {
      isInitialMount.current = false;
      return;
    }

    if (lastHeadingRef.current) {
      setTimeout(() => {
        lastHeadingRef.current?.focus();
      }, 100);
    }
  }, [headingItems.length]);

  // Auto-focus newly added answer select
  useEffect(() => {
    if (isInitialMount.current) {
      return;
    }

    if (lastAnswerRef.current) {
      setTimeout(() => {
        lastAnswerRef.current?.focus();
      }, 100);
    }
  }, [headingAnswers.length]);

  const handleTitleChange = (value) => {
    updateQuestion((current = question) => ({
      ...current,
      matchingHeadingListTitle: value,
    }));
  };

  const handleItemChange = (index, value) => {
    updateQuestion((current = question) => {
      const nextItems = ensureLength(current.matchingHeadingItems, Math.max(index + 1, 3));
      nextItems[index] = value;
      return {
        ...current,
        matchingHeadingItems: nextItems,
      };
    });
  };

  const handleRemoveItem = (index) => {
    updateQuestion((current = question) => {
      const nextItems = ensureLength(current.matchingHeadingItems, 0).filter(
        (_, itemIndex) => itemIndex !== index
      );
      return {
        ...current,
        matchingHeadingItems: nextItems.length ? nextItems : [""],
      };
    });
  };

  const handleAddHeading = () => {
    updateQuestion((current = question) => ({
      ...current,
      matchingHeadingItems: [...ensureLength(current.matchingHeadingItems, 0), ""],
    }));
  };

  const handleAnswerChange = (index, value) => {
    const normalizedValue = (value || "").trim();
    updateQuestion((current = question) => {
      const currentAnswers = Array.isArray(current.matchingHeadingAnswers) 
        ? [...current.matchingHeadingAnswers] 
        : [];
      currentAnswers[index] = normalizedValue;
      return {
        ...current,
        matchingHeadingAnswers: currentAnswers,
        correctAnswers: currentAnswers.slice(),
      };
    });
  };

  const handleAddAnswer = () => {
    updateQuestion((current = question) => {
      const currentAnswers = ensureLength(current.matchingHeadingAnswers, 0);
      const nextAnswers = [...currentAnswers, ""];
      return {
        ...current,
        matchingHeadingAnswers: nextAnswers,
        correctAnswers: nextAnswers.slice(),
      };
    });
  };

  const handleRemoveAnswer = (index) => {
    updateQuestion((current = question) => {
      const nextAnswers = ensureLength(current.matchingHeadingAnswers, 0).filter(
        (_, answerIndex) => answerIndex !== index
      );
      return {
        ...current,
        matchingHeadingAnswers: nextAnswers.length ? nextAnswers : [""],
        correctAnswers: nextAnswers.slice(),
      };
    });
  };

  return (
    <div className="space-y-4 rounded-lg border border-blue-100 bg-blue-50/40 p-4">
      <div>
        <div className="flex items-center justify-between">
          <label className="text-xs font-medium uppercase tracking-wide text-slate-500">
            Heading items
          </label>
          <button
            type="button"
            onClick={handleAddHeading}
            className="rounded border border-blue-200 px-3 py-1 text-xs font-semibold text-blue-600 hover:bg-blue-50"
          >
            + Add heading
          </button>
        </div>
        <div className="mt-2 space-y-2">
          {headingItems.map((item, index) => {
            const headingLabel = intToRoman(index + 1);
            const isLastItem = index === headingItems.length - 1;
            return (
              <div
                key={`matching-heading-${index}`}
                className="flex items-start gap-2"
              >
                <span className="mt-2 inline-flex h-6 min-w-[1.5rem] items-center justify-center rounded border border-blue-200 bg-white px-2 text-xs font-semibold text-blue-600">
                  {headingLabel}.
                </span>
                <textarea
                  ref={isLastItem ? lastHeadingRef : null}
                  value={item}
                  onChange={(event) =>
                    handleItemChange(index, event.target.value)
                  }
                  rows={2}
                  className="flex-1 rounded-lg border border-slate-200 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
                  placeholder={`Heading description ${headingLabel}`}
                />
                <button
                  type="button"
                  onClick={() => handleRemoveItem(index)}
                  className="mt-2 rounded border border-red-200 px-2 py-1 text-xs font-semibold text-red-500 hover:bg-red-50"
                >
                  Remove
                </button>
              </div>
            );
          })}
        </div>
      </div>

      <div>
        <div className="flex items-center justify-between">
          <label className="text-xs font-medium uppercase tracking-wide text-slate-500">
            Correct answers
          </label>
          <button
            type="button"
            onClick={handleAddAnswer}
            className="rounded border border-blue-200 px-3 py-1 text-xs font-semibold text-blue-600 hover:bg-blue-50"
          >
            + Add answer
          </button>
        </div>
        <div className="mt-2 space-y-2">
          {headingAnswers.map((answer, answerIndex) => {
            const isLastAnswer = answerIndex === headingAnswers.length - 1;
            return (
              <div
                key={`matching-answer-${answerIndex}`}
                className="flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-2 py-1.5"
              >
                <span className="inline-flex h-6 w-6 flex-shrink-0 items-center justify-center rounded border border-orange-200 bg-orange-50 text-xs font-semibold text-orange-600">
                  {answerIndex + 1}
                </span>
                <select
                  ref={isLastAnswer ? lastAnswerRef : null}
                  value={answer || ""}
                  onChange={(event) =>
                    handleAnswerChange(answerIndex, event.target.value)
                  }
                  className="flex-1 rounded-lg border border-slate-200 bg-white px-2 py-1 text-sm text-slate-700 focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
                >
                  <option value="">Select a heading</option>
                  {headingItems.map((_, index) => {
                    const label = intToRoman(index + 1);
                    return (
                      <option key={label} value={label}>
                        {label}
                      </option>
                    );
                  })}
                </select>
                <button
                  type="button"
                  onClick={() => handleRemoveAnswer(answerIndex)}
                  className="rounded border border-red-200 px-2 py-1 text-xs font-semibold text-red-500 hover:bg-red-50"
                >
                  Remove
                </button>
              </div>
            );
          })}
        </div>
        <p className="mt-1 text-[11px] text-slate-500">
          These entries feed the answer key; they are hidden from candidates.
        </p>
      </div>
    </div>
  );
};

export default MatchingHeadingsBuilder;
