import React, { useState } from "react";
import {
  DndContext,
  closestCenter,
  PointerSensor,
  MouseSensor,
  TouchSensor,
  useSensor,
  useSensors,
} from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
  useSortable,
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

// Sortable Question Component
function SortableQuestion({ id, questionNum, isGrouped, questionData, sectionKey, onQuestionClick, pIdx }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  };

  // Extract preview text from prompt
  const getPreviewText = () => {
    const prompt = questionData?.prompt || "";
    // Remove HTML tags and get first 40 chars
    const cleanText = prompt.replace(/<[^>]*>/g, "").trim();
    return cleanText.length > 40 ? cleanText.substring(0, 40) + "..." : cleanText;
  };

  const previewText = getPreviewText();

  const handleClick = (e) => {
    // Only trigger click if not dragging
    console.log("[DEBUG-SIDEBAR] SortableQuestion Clicked", {
      id: questionData?.id,
      section: sectionKey,
      isDragging,
      hasHandler: !!onQuestionClick
    });

    if (!isDragging && onQuestionClick && questionData?.id) {
      e.stopPropagation();
      onQuestionClick(sectionKey, questionData.id, { passageIndex: pIdx });
    }
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      {...attributes}
      {...listeners}
      onClick={handleClick}
      data-question-id={questionData?.id}
      data-section-key={sectionKey}
      className={`text-[9px] px-2 py-1 rounded cursor-pointer select-none transition-all ${isDragging
        ? "bg-blue-300 text-white shadow-lg scale-105 ring-2 ring-blue-400"
        : "bg-white border border-slate-200 hover:bg-blue-50 hover:border-blue-300 hover:shadow-md"
        }`}
      title={questionData?.prompt || ""}
    >
      <div className="font-semibold text-slate-700">
        {isGrouped ? "🔰" : "📌"} Q{questionNum}
      </div>
      {previewText && (
        <div className="text-[8px] text-slate-600 line-clamp-2 mt-0.5">
          {previewText}
        </div>
      )}
    </div>
  );
}

// Sortable Ungrouped Questions Block Component
function SortableUngroupedBlock({ id, questions, groupedQuestionIndices, pIdx, onReorderQuestions, sectionKey, onQuestionClick }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  };

  // Get ungrouped questions with their original indices
  const ungroupedQuestionsData = questions
    ?.map((q, originalIdx) => ({ question: q, originalIdx }))
    .filter(({ originalIdx }) => !groupedQuestionIndices.has(originalIdx)) || [];

  const ungroupedIds = ungroupedQuestionsData.map((_, idx) => `ungrouped-question-${pIdx}-${idx}`);



  const sensors = useSensors(
    useSensor(MouseSensor, {
      activationConstraint: {
        distance: 10,
      },
    }),
    useSensor(TouchSensor, {
      activationConstraint: {
        delay: 250,
        tolerance: 5,
      },
    })
  );

  const handleUngroupedDragEnd = (event) => {
    const { active, over } = event;

    if (!over || active.id === over.id) return;

    const oldIndex = ungroupedIds.indexOf(active.id);
    const newIndex = ungroupedIds.indexOf(over.id);

    if (oldIndex !== -1 && newIndex !== -1 && typeof onReorderQuestions === 'function') {
      // Convert ungrouped indices to actual question indices
      const actualFromIndex = ungroupedQuestionsData[oldIndex].originalIdx;
      const actualToIndex = ungroupedQuestionsData[newIndex].originalIdx;
      onReorderQuestions(pIdx, actualFromIndex, actualToIndex);
    }
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={`space-y-1 rounded border-2 p-2 transition-all ${isDragging
        ? "bg-blue-200 border-blue-400 shadow-lg scale-105 ring-2 ring-blue-400"
        : "border-slate-200 bg-slate-50 hover:bg-slate-100"
        }`}
    >
      <p
        {...attributes}
        {...listeners}
        className={`text-[10px] font-semibold cursor-move ${isDragging ? "text-blue-700" : "text-slate-600"
          }`}
      >
        ✓ Questions
      </p>
      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragEnd={handleUngroupedDragEnd}
      >
        <div className="ml-2 space-y-1 pointer-events-auto">
          <SortableContext items={ungroupedIds} strategy={verticalListSortingStrategy}>
            {ungroupedQuestionsData.map(({ question, originalIdx }, idx) => (
              <SortableQuestion
                key={ungroupedIds[idx]}
                id={ungroupedIds[idx]}
                questionNum={originalIdx + 1}
                isGrouped={false}
                questionData={question}
                sectionKey={sectionKey}
                onQuestionClick={onQuestionClick}
                pIdx={pIdx}
              />
            ))}
          </SortableContext>
        </div>
      </DndContext>
    </div>
  );
}

// Sortable Group Component
function SortableGroup({ id, group, gIdx, questions, groupedQuestionIndices, sectionKey, onQuestionClick, pIdx }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={`space-y-1 rounded border-2 bg-orange-50 p-2 transition-all ${isDragging
        ? "bg-blue-200 border-blue-400 shadow-lg scale-105 ring-2 ring-blue-400"
        : "bg-orange-50 border-orange-300 hover:bg-orange-100"
        }`}
    >
      <p
        {...attributes}
        {...listeners}
        className={`text-[10px] font-semibold cursor-move ${isDragging ? "text-blue-700" : "text-orange-700"
          }`}
      >
        📋 Group Q{group.startIndex}-{group.endIndex}: {group.title || `Group ${gIdx + 1}`}
      </p>
      <div className="ml-2 space-y-1">
        {questions?.map((question, qIdx) => {
          const questionNum = qIdx + 1;
          if (questionNum < group.startIndex || questionNum > group.endIndex) return null;

          // Get preview text
          const prompt = question?.prompt || "";
          const cleanText = prompt.replace(/<[^>]*>/g, "").trim();
          const previewText = cleanText.length > 35 ? cleanText.substring(0, 35) + "..." : cleanText;

          return (
            <div
              key={question.id || qIdx}
              data-question-id={question.id}
              data-section-key={sectionKey}
              onClick={(e) => {
                e.stopPropagation();
                console.log("[DEBUG-SIDEBAR] Ungrouped/SortableGroup Item Clicked", {
                  id: question.id,
                  section: sectionKey,
                  dragState: isDragging ? "dragging" : "static",
                  hasHandler: !!onQuestionClick
                });
                onQuestionClick?.(sectionKey, question.id, { passageIndex: pIdx });
              }}
              className="text-[9px] px-2 py-1 rounded bg-white border border-orange-200 cursor-pointer hover:bg-orange-50 hover:border-orange-400 transition-colors"
              title={question?.prompt || ""}
            >
              <div className="font-semibold text-slate-700">🔰 Q{questionNum}</div>
              {previewText && (
                <div className="text-[8px] text-slate-600 line-clamp-2 mt-0.5">
                  {previewText}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// Sortable Passage Component  
function SortablePassage({ id, passage, pIdx, onReorderGroups, onReorderReadingQuestions, onQuestionClick }) {
  const [itemOrder, setItemOrder] = useState(null);

  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  };

  // Get grouped question indices
  const groupedQuestionIndices = new Set();
  passage.instructionGroups?.forEach((group) => {
    for (let i = group.startIndex; i <= group.endIndex; i++) {
      groupedQuestionIndices.add(i - 1);
    }
  });

  // Check if there are ungrouped questions
  const hasUngroupedQuestions = passage.questions?.some((_, qIdx) => !groupedQuestionIndices.has(qIdx));

  // Create a single array of all sortable items (groups + ungrouped block)
  // Use saved displayOrder if available, otherwise create default order
  const defaultItems = passage.displayOrder || [
    ...(passage.instructionGroups?.map((g, idx) => ({ type: 'group', id: `group-${pIdx}-${idx}`, index: idx })) || []),
    ...(hasUngroupedQuestions ? [{ type: 'ungrouped', id: `ungrouped-${pIdx}` }] : [])
  ];

  // Use itemOrder state if available, otherwise use default
  const orderedItems = itemOrder || defaultItems;
  const itemIds = orderedItems.map(item => item.id);



  const sensors = useSensors(
    useSensor(MouseSensor, {
      activationConstraint: {
        distance: 10,
      },
    }),
    useSensor(TouchSensor, {
      activationConstraint: {
        delay: 250,
        tolerance: 5,
      },
    })
  );

  const handleLocalDragEnd = (event) => {
    const { active, over } = event;

    if (!over || active.id === over.id) return;

    const oldIndex = itemIds.indexOf(active.id);
    const newIndex = itemIds.indexOf(over.id);

    if (oldIndex !== -1 && newIndex !== -1) {
      const newOrder = [...orderedItems];
      const [movedItem] = newOrder.splice(oldIndex, 1);
      newOrder.splice(newIndex, 0, movedItem);
      setItemOrder(newOrder);

      // Notify parent component about the new order
      if (typeof onReorderGroups === 'function') {
        onReorderGroups(pIdx, newOrder);
      }
    }
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={`text-xs rounded border-2 p-2 transition-all ${isDragging
        ? "bg-blue-300 text-white border-blue-400 shadow-lg scale-105 ring-2 ring-blue-400"
        : "bg-white border-slate-300 hover:bg-slate-50"
        }`}
    >
      <p
        {...attributes}
        {...listeners}
        className={`font-semibold cursor-move ${isDragging ? "text-white" : "text-slate-700"}`}
      >
        📖 Passage {pIdx + 1}: {passage.title || `Passage ${pIdx + 1}`}
      </p>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragEnd={handleLocalDragEnd}
      >
        <div className="space-y-1 text-slate-600 mt-1 pointer-events-auto">
          {/* Single SortableContext for all items */}
          <SortableContext items={itemIds} strategy={verticalListSortingStrategy}>
            {/* Render items in order */}
            {orderedItems.map((item) => {
              if (item.type === 'group') {
                const group = passage.instructionGroups[item.index];
                return (
                  <SortableGroup
                    key={item.id}
                    id={item.id}
                    group={group}
                    gIdx={item.index}
                    questions={passage.questions}
                    groupedQuestionIndices={groupedQuestionIndices}
                    sectionKey="reading"
                    onQuestionClick={onQuestionClick}
                    pIdx={pIdx}
                  />
                );
              } else if (item.type === 'ungrouped') {
                return (
                  <SortableUngroupedBlock
                    key={item.id}
                    id={item.id}
                    questions={passage.questions}
                    groupedQuestionIndices={groupedQuestionIndices}
                    pIdx={pIdx}
                    onReorderQuestions={onReorderReadingQuestions}
                    sectionKey="reading"
                    onQuestionClick={onQuestionClick}
                  />
                );
              }
              return null;
            })}
          </SortableContext>
        </div>
      </DndContext>
    </div>
  );
}

// Sortable Custom Section Component (similar to Reading)
function SortableCustomSection({ sectionKey, sectionData, onReorderGroups, onReorderCustomQuestions, onQuestionClick }) {
  const [itemOrder, setItemOrder] = useState(null);

  // Get grouped question indices from groups
  const groupedQuestionIndices = new Set();
  sectionData.groups?.forEach((group) => {
    (group.questions || []).forEach((q, idx) => {
      // Mark these as grouped - we'll track by group membership
      groupedQuestionIndices.add(q.id);
    });
  });

  // Standalone questions are those NOT in any group
  const standaloneQuestions = (sectionData.questions || []).filter(
    (q) => !groupedQuestionIndices.has(q.id)
  );
  const hasStandaloneQuestions = standaloneQuestions.length > 0;

  // Create sortable items array (standalone block + groups)
  const defaultItems = [
    ...(hasStandaloneQuestions ? [{ type: 'standalone', id: `standalone-${sectionKey}` }] : []),
    ...(sectionData.groups?.map((g, idx) => ({ type: 'group', id: `group-${sectionKey}-${idx}`, index: idx })) || [])
  ];

  const orderedItems = itemOrder || defaultItems;
  const itemIds = orderedItems.map(item => item.id);

  const sensors = useSensors(
    useSensor(MouseSensor, {
      activationConstraint: {
        distance: 10,
      },
    }),
    useSensor(TouchSensor, {
      activationConstraint: {
        delay: 250,
        tolerance: 5,
      },
    })
  );

  const handleLocalDragEnd = (event) => {
    const { active, over } = event;

    if (!over || active.id === over.id) return;

    const oldIndex = itemIds.indexOf(active.id);
    const newIndex = itemIds.indexOf(over.id);

    if (oldIndex !== -1 && newIndex !== -1) {
      const newOrder = [...orderedItems];
      const [movedItem] = newOrder.splice(oldIndex, 1);
      newOrder.splice(newIndex, 0, movedItem);
      setItemOrder(newOrder);

      // Notify parent component about the new order
      if (typeof onReorderGroups === 'function') {
        onReorderGroups(sectionKey, newOrder);
      }
    }
  };

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCenter}
      onDragEnd={handleLocalDragEnd}
    >
      <div className="p-2 space-y-2">
        <SortableContext items={itemIds} strategy={verticalListSortingStrategy}>
          {orderedItems.map((item) => {
            if (item.type === 'standalone') {
              return (
                <SortableStandaloneBlock
                  key={item.id}
                  id={item.id}
                  questions={standaloneQuestions}
                  sectionKey={sectionKey}
                  onReorderQuestions={onReorderCustomQuestions}
                  onQuestionClick={onQuestionClick}
                />
              );
            } else if (item.type === 'group') {
              const group = sectionData.groups[item.index];
              return (
                <SortableCustomGroup
                  key={item.id}
                  id={item.id}
                  group={group}
                  gIdx={item.index}
                  sectionKey={sectionKey}
                  onQuestionClick={onQuestionClick}
                />
              );
            }
            return null;
          })}
        </SortableContext>
      </div>
    </DndContext>
  );
}

