// Sortable Custom Question Component
function SortableCustomQuestion({ id, question, questionNum, isGrouped, sectionKey, onQuestionClick }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  };

  const handleClick = (e) => {
    // Only trigger click if not dragging
    console.log("[DEBUG-SIDEBAR] SortableCustomQuestion Clicked", {
      id: question?.id,
      section: sectionKey,
      isDragging,
      hasHandler: !!onQuestionClick
    });

    if (!isDragging && onQuestionClick && question?.id) {
      e.stopPropagation();
      onQuestionClick(sectionKey, question.id);
    }
  };

  const hasSubQuestions = question.subQuestions && question.subQuestions.length > 0;
  const previewText = question.prompt
    ? question.prompt.replace(/<[^>]*>/g, "").trim().substring(0, 40) + "..."
    : "";

  return (
    <div ref={setNodeRef} style={style}>
      <div
        {...attributes}
        {...listeners}
        onClick={handleClick}
        data-question-id={question.id}
        data-section-key={sectionKey}
        className={`text-[9px] px-2 py-1 rounded cursor-pointer select-none transition-all ${isDragging
          ? "bg-blue-300 text-white shadow-lg scale-105 ring-2 ring-blue-400"
          : "bg-white border border-slate-200 hover:bg-blue-50 hover:border-blue-300 hover:shadow-md"
          }`}
        title={question.prompt || ""}
      >
        <div className="font-semibold text-slate-700">
          {isGrouped ? "🔰" : "📌"} Q{questionNum}
        </div>
        {previewText && (
          <div className="text-[8px] text-slate-600 line-clamp-2 mt-0.5">
            {previewText}
          </div>
        )}
      </div>

      {/* Show subQuestions if exist */}
      {hasSubQuestions && (
        <div className="ml-3 mt-1 space-y-0.5">
          {question.subQuestions.map((sub, subIdx) => (
            <div
              key={sub.id || `sub-${subIdx}`}
              className={`text-[8px] px-1.5 py-0.5 rounded ${isGrouped
                ? "bg-orange-100 border border-orange-300 text-orange-700"
                : "bg-slate-100 border border-slate-300 text-slate-700"
                }`}
            >
              {sub.number || `${questionNum}.${subIdx + 1}`}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export function ExamStructureSidebar({
  exam,
  customSections = [],
  onReorderReadingQuestions,
  onReorderPassages,
  onReorderGroups,
  onReorderListeningGroups,
  onReorderWritingTasks,
  onReorderSpeakingParts,
  onReorderCustomQuestions,
  onReorderCustomGroups,
  isOpen: propIsOpen,
  onToggle,
  onQuestionClick, // NEW: Click to navigate to question in builder
}) {
  // Build expanded sections state from customSections
  const initialExpandedSections = {};
  customSections.forEach((section) => {
    if (section.enabled) {
      initialExpandedSections[section.key] = true;
    }
  });

  const [expandedSections, setExpandedSections] = useState(initialExpandedSections);
  const [internalIsOpen, setInternalIsOpen] = useState(true);

  const isControlled = typeof propIsOpen !== 'undefined';
  const isOpen = isControlled ? propIsOpen : internalIsOpen;
  const setIsOpen = isControlled ? onToggle : setInternalIsOpen;

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8,
      },
    })
  );

  const toggleSection = (section) => {
    setExpandedSections((prev) => ({
      ...prev,
      [section]: !prev[section],
    }));
  };

  const handleDragEnd = (event) => {
    const { active, over } = event;

    if (!over || active.id === over.id) {
      return;
    }

    const activeId = active.id;
    const overId = over.id;

    // Parse IDs to determine type and indices
    if (activeId.startsWith("passage-") && overId.startsWith("passage-")) {
      const fromIdx = parseInt(activeId.split("-")[1]);
      const toIdx = parseInt(overId.split("-")[1]);
      onReorderPassages?.(fromIdx, toIdx);
    } else if (activeId.startsWith("question-") && overId.startsWith("question-")) {
      const [, passageIdx, fromQIdx] = activeId.split("-").map(Number);
      const [, , toQIdx] = overId.split("-").map(Number);
      onReorderReadingQuestions?.(passageIdx, fromQIdx, toQIdx);
    } else if (activeId.startsWith("listening-group-") && overId.startsWith("listening-group-")) {
      const fromIdx = parseInt(activeId.split("-")[2]);
      const toIdx = parseInt(overId.split("-")[2]);
      onReorderListeningGroups?.(fromIdx, toIdx);
    } else if (activeId.startsWith("writing-task-") && overId.startsWith("writing-task-")) {
      const fromIdx = parseInt(activeId.split("-")[2]);
      const toIdx = parseInt(overId.split("-")[2]);
      onReorderWritingTasks?.(fromIdx, toIdx);
    } else if (activeId.startsWith("speaking-part-") && overId.startsWith("speaking-part-")) {
      const fromIdx = parseInt(activeId.split("-")[2]);
      const toIdx = parseInt(overId.split("-")[2]);
      onReorderSpeakingParts?.(fromIdx, toIdx);
    }
  };

  const renderReadingContent = () => {
    const { reading } = exam;
    if (!reading?.passages?.length) {
      return <p className="text-xs text-slate-400 p-2">No passages</p>;
    }

    const passageIds = reading.passages.map((_, idx) => `passage-${idx}`);

    return (
      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragEnd={handleDragEnd}
      >
        <div className="space-y-2 p-2">
          <SortableContext items={passageIds} strategy={verticalListSortingStrategy}>
            {reading.passages.map((passage, pIdx) => (
              <SortablePassage
                key={`passage-${pIdx}`}
                id={`passage-${pIdx}`}
                passage={passage}
                pIdx={pIdx}
                onReorderGroups={onReorderGroups}
                onReorderReadingQuestions={onReorderReadingQuestions}
                onQuestionClick={onQuestionClick}
              />
            ))}
          </SortableContext>
        </div>
      </DndContext>
    );
  };

  const renderListeningContent = () => {
    const { listening } = exam;
    if (!listening?.questionGroups?.length) {
      return <p className="text-xs text-slate-400 p-2">No questions</p>;
    }

    const groupIds = listening.questionGroups.map((_, idx) => `listening-group-${idx}`);

    const SortableListeningGroup = ({ id, group, gIdx }) => {
      const { attributes, listeners, setNodeRef, transform, transition, isDragging } =
        useSortable({ id });

      const style = {
        transform: CSS.Transform.toString(transform),
        transition,
        opacity: isDragging ? 0.5 : 1,
      };

      return (
        <div
          ref={setNodeRef}
          style={style}
          {...attributes}
          {...listeners}
          onClick={(e) => {
            if (!isDragging) {
              onQuestionClick?.('listening', group.id);
            }
          }}
          className={`text-xs rounded border-2 p-2 cursor-move transition-all ${isDragging
            ? "bg-blue-300 text-white border-blue-400 shadow-lg scale-105"
            : "bg-white border-slate-300 hover:bg-slate-50 cursor-pointer"
            }`}
        >
          <p className="font-semibold">
            🎧 Group {gIdx + 1}: {group.title || `Group ${gIdx + 1}`}
          </p>
        </div>
      );
    };

    return (
      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragEnd={handleDragEnd}
      >
        <div className="space-y-2 p-2">
          <SortableContext items={groupIds} strategy={verticalListSortingStrategy}>
            {listening.questionGroups.map((group, gIdx) => (
              <SortableListeningGroup
                key={`listening-group-${gIdx}`}
                id={`listening-group-${gIdx}`}
                group={group}
                gIdx={gIdx}
              />
            ))}
          </SortableContext>
        </div>
      </DndContext>
    );
  };

  const renderWritingContent = () => {
    const { writing } = exam;
    if (!writing?.tasks?.length) {
      return <p className="text-xs text-slate-400 p-2">No tasks</p>;
    }

    const taskIds = writing.tasks.map((_, idx) => `writing-task-${idx}`);

    const SortableWritingTask = ({ id, task, tIdx }) => {
      const { attributes, listeners, setNodeRef, transform, transition, isDragging } =
        useSortable({ id });

      const style = {
        transform: CSS.Transform.toString(transform),
        transition,
        opacity: isDragging ? 0.5 : 1,
      };

      return (
        <div
          ref={setNodeRef}
          style={style}
          {...attributes}
          {...listeners}
          onClick={(e) => {
            if (!isDragging) {
              onQuestionClick?.('writing', task.id);
            }
          }}
          className={`text-xs rounded border-2 p-2 cursor-move transition-all ${isDragging
            ? "bg-blue-300 text-white border-blue-400 shadow-lg scale-105"
            : "bg-white border-slate-300 hover:bg-slate-50 cursor-pointer"
            }`}
        >
          <p className="font-semibold">
            ✍️ Task {tIdx + 1}: {task.title || `Task ${tIdx + 1}`}
          </p>
        </div>
      );
    };

    return (
      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragEnd={handleDragEnd}
      >
        <div className="space-y-2 p-2">
          <SortableContext items={taskIds} strategy={verticalListSortingStrategy}>
            {writing.tasks.map((task, tIdx) => (
              <SortableWritingTask
                key={`writing-task-${tIdx}`}
                id={`writing-task-${tIdx}`}
                task={task}
                tIdx={tIdx}
              />
            ))}
          </SortableContext>
        </div>
      </DndContext>
    );
  };

  const renderSpeakingContent = () => {
    const { speaking } = exam;
    if (!speaking?.parts?.length) {
      return <p className="text-xs text-slate-400 p-2">No parts</p>;
    }

    const partIds = speaking.parts.map((_, idx) => `speaking-part-${idx}`);

    const SortableSpeakingPart = ({ id, part, pIdx }) => {
      const { attributes, listeners, setNodeRef, transform, transition, isDragging } =
        useSortable({ id });

      const style = {
        transform: CSS.Transform.toString(transform),
        transition,
        opacity: isDragging ? 0.5 : 1,
      };

      return (
        <div
          ref={setNodeRef}
          style={style}
          {...attributes}
          {...listeners}
          onClick={(e) => {
            if (!isDragging) {
              onQuestionClick?.('speaking', part.id);
            }
          }}
          className={`text-xs rounded border-2 p-2 cursor-move transition-all ${isDragging
            ? "bg-blue-300 text-white border-blue-400 shadow-lg scale-105"
            : "bg-white border-slate-300 hover:bg-slate-50 cursor-pointer"
            }`}
        >
          <p className="font-semibold">
            🎤 Part {pIdx + 1}: {part.title || `Part ${pIdx + 1}`}
          </p>
        </div>
      );
    };

    return (
      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragEnd={handleDragEnd}
      >
        <div className="space-y-2 p-2">
          <SortableContext items={partIds} strategy={verticalListSortingStrategy}>
            {speaking.parts.map((part, pIdx) => (
              <SortableSpeakingPart
                key={`speaking-part-${pIdx}`}
                id={`speaking-part-${pIdx}`}
                part={part}
                pIdx={pIdx}
              />
            ))}
          </SortableContext>
        </div>
      </DndContext>
    );
  };

  const renderCustomSectionContent = (sectionKey) => {
    const sectionData = exam[sectionKey];

    if (!sectionData) {
      return <p className="text-xs text-slate-400 p-2">Custom section (no content)</p>;
    }

    // Check if section has content
    const hasStandaloneQuestions = sectionData.questions && sectionData.questions.length > 0;
    const hasGroups = sectionData.groups && sectionData.groups.length > 0;

    if (!hasStandaloneQuestions && !hasGroups) {
      return <p className="text-xs text-slate-400 p-2">Custom section (no content)</p>;
    }

    // Use the sortable component with drag-and-drop
    return (
      <SortableCustomSection
        sectionKey={sectionKey}
        sectionData={sectionData}
        onReorderGroups={onReorderCustomGroups}
        onReorderCustomQuestions={onReorderCustomQuestions}
        onQuestionClick={onQuestionClick}
      />
    );
  };

  return (
    <>
      {/* Backdrop for mobile */}
      {isOpen && (
        <div
          className="fixed inset-0 bg-black bg-opacity-50 z-30 lg:hidden"
          onClick={() => setIsOpen(false)}
          aria-hidden="true"
        />
      )}

      {/* Toggle Badge - Visible when collapsed */}
      {!isOpen && (
        <button
          onClick={() => setIsOpen(true)}
          className="fixed right-0 top-24 z-50 bg-white border-l border-t border-b border-slate-300 p-1 rounded-l-md shadow-md hover:bg-slate-50 transition-colors group"
          title="Open Exam Structure"
        >
          <svg className="w-5 h-5 text-slate-500 group-hover:text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
          </svg>
        </button>
      )}

      {/* Sidebar */}
      <div className={`fixed right-0 top-0 h-screen w-80 bg-white border-l border-slate-200 overflow-y-auto z-[60] transition-transform duration-300 ease-in-out ${isOpen ? 'translate-x-0' : 'translate-x-full'
        }`}>
        <div className="p-4 border-b border-slate-200 flex items-start justify-between">
          <div className="flex-1">
            <h2 className="text-lg font-bold text-slate-800">📋 Exam Structure</h2>
            <p className="text-xs text-slate-500 mt-1">
              Drag and drop to reorder sections, passages, groups, and questions
            </p>
          </div>
          <button
            onClick={() => setIsOpen(false)}
            className="ml-2 p-1 hover:bg-slate-100 rounded transition-colors"
            aria-label="Close sidebar"
          >
            <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        {/* Dynamic Sections from customSections */}
        {customSections.map((section) => {
          if (!section.enabled) return null;

          // Map section key to icon, label, and renderer
          const sectionConfig = {
            listening: { icon: "🎧", label: "Listening", renderer: renderListeningContent },
            reading: { icon: "📖", label: "Reading", renderer: renderReadingContent },
            writing: { icon: "✍️", label: "Writing", renderer: renderWritingContent },
            speaking: { icon: "🎤", label: "Speaking", renderer: renderSpeakingContent },
          };

          // Check if it's a known section or custom
          const config = sectionConfig[section.key] || {
            icon: "📝",
            label: section.label,
            renderer: () => renderCustomSectionContent(section.key)
          };

          return (
            <div key={section.key} className="border-b border-slate-200">
              <button
                onClick={() => toggleSection(section.key)}
                className="w-full px-4 py-3 flex items-center justify-between hover:bg-slate-50 transition-colors"
              >
                <span className="font-semibold text-slate-700">{config.icon} {config.label}</span>
                <span className="text-slate-400">{expandedSections[section.key] ? "▼" : "▶"}</span>
              </button>
              {expandedSections[section.key] && config.renderer()}
            </div>
          );
        })}
      </div>
    </>
  );
}
