import React, { useState, useMemo } from "react";

const DEFAULT_SECTIONS = [
  { key: "listening", label: "Listening", enabled: true, isDefault: true },
  { key: "reading", label: "Reading", enabled: true, isDefault: true },
  { key: "writing", label: "Writing", enabled: true, isDefault: true },
  { key: "grammar", label: "Grammar & Vocabulary", enabled: true, isDefault: true },
  { key: "speaking", label: "Speaking", enabled: true, isDefault: true },
];

const ConfirmDialog = ({ isOpen, title, message, onConfirm, onCancel }) => {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-modal flex items-center justify-center bg-black/50">
      <div className="rounded-lg bg-white p-6 shadow-lg">
        <h3 className="text-lg font-bold text-gray-900">{title}</h3>
        <p className="mt-2 text-sm text-gray-600">{message}</p>
        <div className="mt-4 flex gap-2">
          <button
            onClick={onCancel}
            className="flex-1 rounded border border-gray-300 px-4 py-2 text-sm font-semibold text-gray-700 hover:bg-gray-100"
          >
            Cancel
          </button>
          <button
            onClick={onConfirm}
            className="flex-1 rounded bg-red-500 px-4 py-2 text-sm font-semibold text-white hover:bg-red-600"
          >
            Delete
          </button>
        </div>
      </div>
    </div>
  );
};

const SectionCustomizer = ({ isOpen, onClose, sections = DEFAULT_SECTIONS, onSave }) => {
  const [customSections, setCustomSections] = useState(sections);
  const [newSectionLabel, setNewSectionLabel] = useState("");
  const [deleteConfirm, setDeleteConfirm] = useState({ isOpen: false, key: null });
  const [lastSavedSections, setLastSavedSections] = useState(sections);

  // Sync customSections when sections prop changes (but not during user edits)
  React.useEffect(() => {
    if (isOpen) {
      // If props changed AND we haven't made edits, sync from props
      // This handles case where parent saved changes and modal still open
      const hasLocalChanges = JSON.stringify(customSections) !== JSON.stringify(lastSavedSections);
      if (!hasLocalChanges) {
        setCustomSections(sections);
        setLastSavedSections(sections);
      }
    }
  }, [sections, isOpen]);

  const handleToggleSection = (key) => {
    setCustomSections((prev) =>
      prev.map((section) =>
        section.key === key ? { ...section, enabled: !section.enabled } : section
      )
    );
  };

  const handleRenameSection = (key, newLabel) => {
    setCustomSections((prev) =>
      prev.map((section) =>
        section.key === key ? { ...section, label: newLabel } : section
      )
    );
  };

  const handleAddSection = () => {
    if (!newSectionLabel.trim()) {
      alert("Please enter a skill name");
      return;
    }

    // Check if name already exists
    if (customSections.some(s => s.label.toLowerCase() === newSectionLabel.toLowerCase())) {
      alert("This skill name already exists");
      return;
    }

    // Generate unique key from label
    const key = `custom_${Date.now()}`;
    const newSection = {
      key,
      label: newSectionLabel,
      enabled: true,
      isDefault: false,
    };

    console.log("➕ Adding new section:", newSection);
    setCustomSections((prev) => [...prev, newSection]);
    setNewSectionLabel("");
  };

  const handleMoveSection = (key, direction) => {
    setCustomSections((prev) => {
      const index = prev.findIndex(s => s.key === key);
      if (index === -1) return prev;
      
      if (direction === "up" && index > 0) {
        const updated = [...prev];
        [updated[index], updated[index - 1]] = [updated[index - 1], updated[index]];
        return updated;
      }
      
      if (direction === "down" && index < prev.length - 1) {
        const updated = [...prev];
        [updated[index], updated[index + 1]] = [updated[index + 1], updated[index]];
        return updated;
      }
      
      return prev;
    });
  };

  const handleDeleteSection = (key) => {
    // Check if removing this section would leave no enabled sections
    const section = customSections.find(s => s.key === key);
    const willHaveEnabledAfterDelete = customSections.some(
      s => s.key !== key && s.enabled
    );
    
    console.log("🗑️ handleDeleteSection - Attempting to delete:", {
      key,
      label: section?.label,
      willHaveEnabledAfterDelete
    });
    
    if (!willHaveEnabledAfterDelete) {
      alert("You must have at least one skill enabled");
      return;
    }

    setDeleteConfirm({ isOpen: true, key });
  };

  const confirmDelete = () => {
    const sectionToDelete = customSections.find(s => s.key === deleteConfirm.key);
    console.log("🗑️ confirmDelete - Deleting section:", sectionToDelete?.key, sectionToDelete?.label);
    setCustomSections((prev) => {
      const updated = prev.filter(s => s.key !== deleteConfirm.key);
      console.log("📊 customSections after delete:", {
        before: prev.length,
        after: updated.length,
        updated
      });
      return updated;
    });
    setDeleteConfirm({ isOpen: false, key: null });
  };

  const handleSave = () => {
    // Ensure at least one section is enabled
    if (!customSections.some(s => s.enabled)) {
      alert("Please enable at least one skill");
      return;
    }

    console.log("💾 handleSave - Calling onSave with customSections:", customSections);
    setLastSavedSections(customSections);
    onSave?.(customSections);
    onClose?.();
  };

  if (!isOpen) return null;

  const sectionToDelete = customSections.find(s => s.key === deleteConfirm.key);

  return (
    <>
      <div className="fixed inset-0 z-modal flex items-center justify-center bg-black/50">
        <div className="flex max-h-[90vh] w-full max-w-md flex-col rounded-2xl bg-white shadow-xl overflow-hidden">
          {/* Header */}
          <div className="border-b border-gray-200 px-6 py-4">
            <h2 className="text-xl font-bold text-gray-900">Customize Sections</h2>
            <p className="mt-1 text-sm text-gray-600">
              Enable/disable skills and customize their names
            </p>
          </div>

          {/* Content */}
          <div className="flex-1 overflow-y-auto px-6 py-4">
            <div className="space-y-3">
              {customSections.map((section, idx) => (
                <div
                  key={section.key}
                  className="flex items-center gap-3 rounded-lg border border-gray-200 p-3 hover:bg-gray-50"
                >
                  {/* Toggle Checkbox */}
                  <input
                    type="checkbox"
                    checked={section.enabled}
                    onChange={() => handleToggleSection(section.key)}
                    className="h-5 w-5 rounded border-gray-300 text-orange-400 focus:ring-orange-300"
                  />

                  {/* Section Name Input */}
                  <input
                    type="text"
                    value={section.label}
                    onChange={(e) => handleRenameSection(section.key, e.target.value)}
                    disabled={!section.enabled}
                    placeholder={`Enter ${section.key} name`}
                    className={`flex-1 rounded border border-gray-300 px-3 py-2 text-sm focus:border-orange-400 focus:outline-none focus:ring-2 focus:ring-orange-200 ${
                      !section.enabled
                        ? "cursor-not-allowed bg-gray-100 text-gray-400"
                        : "bg-white"
                    }`}
                  />

                  {/* Status Badge & Actions */}
                  <div className="flex items-center gap-2">
                    {/* Status */}
                    <div className="text-xs font-semibold">
                      {section.enabled ? (
                        <span className="inline-flex items-center gap-1 rounded-full bg-green-100 px-2 py-1 text-green-700">
                          ✓ On
                        </span>
                      ) : (
                        <span className="inline-flex items-center gap-1 rounded-full bg-gray-100 px-2 py-1 text-gray-500">
                          ✕ Off
                        </span>
                      )}
                    </div>

                    {/* Move Up Button */}
                    <button
                      type="button"
                      onClick={() => handleMoveSection(section.key, "up")}
                      disabled={idx === 0}
                      className="text-blue-500 hover:text-blue-700 disabled:text-gray-300 text-sm font-semibold disabled:cursor-not-allowed"
                      title="Move up"
                    >
                      ▲
                    </button>

                    {/* Move Down Button */}
                    <button
                      type="button"
                      onClick={() => handleMoveSection(section.key, "down")}
                      disabled={idx === customSections.length - 1}
                      className="text-blue-500 hover:text-blue-700 disabled:text-gray-300 text-sm font-semibold disabled:cursor-not-allowed"
                      title="Move down"
                    >
                      ▼
                    </button>

                    {/* Delete Button */}
                    <button
                      type="button"
                      onClick={() => handleDeleteSection(section.key)}
                      className="text-red-500 hover:text-red-700 text-sm font-semibold"
                      title="Delete this skill"
                    >
                      ✕
                    </button>
                  </div>
                </div>
              ))}
            </div>

            {/* Add New Section */}
            <div className="mt-6 space-y-3 border-t border-gray-200 pt-4">
              <label className="block text-xs font-semibold uppercase tracking-wide text-gray-700">
                Add new skill
              </label>
              
              {/* Quick Add Buttons for Basic Skills */}
              <div className="grid grid-cols-2 gap-2">
                {["Listening", "Reading", "Writing", "Speaking"].map((skill) => (
                  <button
                    key={skill}
                    type="button"
                    onClick={() => {
                      setNewSectionLabel(skill);
                      // Add immediately
                      const key = `custom_${Date.now()}`;
                      const newSection = {
                        key,
                        label: skill,
                        enabled: true,
                        isDefault: false,
                      };
                      if (!customSections.some(s => s.label.toLowerCase() === skill.toLowerCase())) {
                        setCustomSections((prev) => [...prev, newSection]);
                        setNewSectionLabel("");
                      }
                    }}
                    className="rounded border-2 border-dashed border-orange-300 px-3 py-2 text-xs font-semibold text-orange-600 transition hover:bg-orange-50 active:bg-orange-100"
                  >
                    + {skill}
                  </button>
                ))}
              </div>

              {/* Custom Input */}
              <div className="flex gap-2 items-center">
                <input
                  type="text"
                  value={newSectionLabel}
                  onChange={(e) => setNewSectionLabel(e.target.value)}
                  onKeyPress={(e) => e.key === "Enter" && handleAddSection()}
                  placeholder="Enter skill name (e.g. Vocabulary)"
                  autoFocus
                  className="flex-1 min-w-0 rounded border border-gray-300 px-3 py-2 text-sm focus:border-orange-400 focus:outline-none focus:ring-2 focus:ring-orange-200"
                />
                <button
                  type="button"
                  onClick={handleAddSection}
                  title="Add new skill (or press Enter)"
                  className="flex-shrink-0 rounded bg-orange-400 px-4 py-2 text-sm font-bold text-white transition hover:bg-orange-500 active:bg-orange-600 whitespace-nowrap"
                >
                  Add
                </button>
              </div>
              <p className="text-xs text-gray-600">
                💡 Click quick buttons or enter custom skill name and press <strong>Enter</strong>
              </p>
            </div>
          </div>

          {/* Footer */}
          <div className="border-t border-gray-200 flex gap-2 bg-gray-50 px-6 py-4">
            <button
              onClick={onClose}
              className="flex-1 rounded-lg border border-gray-300 px-4 py-2 text-sm font-semibold text-gray-700 transition hover:bg-gray-100"
            >
              Cancel
            </button>
            <button
              onClick={handleSave}
              className="flex-1 rounded-lg bg-orange-400 px-4 py-2 text-sm font-semibold text-white transition hover:bg-orange-500"
            >
              Save Changes
            </button>
          </div>
        </div>
      </div>

      {/* Confirm Delete Dialog */}
      <ConfirmDialog
        isOpen={deleteConfirm.isOpen}
        title="Delete Skill"
        message={`Are you sure you want to delete "${sectionToDelete?.label}"?`}
        onConfirm={confirmDelete}
        onCancel={() => setDeleteConfirm({ isOpen: false, key: null })}
      />
    </>
  );
};

export default SectionCustomizer;
