import React from "react";
import { useQuestionContext } from "../../../contexts/QuestionContext";
import BlankAnswerList from "../shared/BlankAnswerList";
import ChoiceOptionsEditor from "../shared/ChoiceOptionsEditor";

const FillInBlankBuilder = () => {
  const { question } = useQuestionContext();

  return (
    <div className="space-y-4">
      <div>
        <label className="text-xs font-medium uppercase tracking-wide text-slate-500">
          Correct answer(s)
        </label>
        <BlankAnswerList />
      </div>

      {question?.inputMode === "choices" ? (
        <ChoiceOptionsEditor allowMultiple={false} />
      ) : null}
    </div>
  );
};

export default FillInBlankBuilder;
