import React from "react";
import { createPortal } from "react-dom";

const SubmitConfirmModal = ({ isOpen, isSubmitting, onConfirm, onCancel, title = "Submit Exam?", message = "Are you sure you want to submit your exam? Once submitted, you cannot make any changes.", confirmLabel = "Submit", violationCount = 0 }) => {
  if (!isOpen) return null;

  // Portal + translateZ + isolation: same recipe as the Ready Popup. The
  // Listening sticky audio bar auto-composites and would otherwise punch
  // through any z-index we set here.
  return createPortal(
    <div
      className="fixed inset-0 z-modal flex items-center justify-center bg-black/40 p-4 backdrop-blur-sm"
      style={{ transform: "translateZ(0)", isolation: "isolate" }}
    >
      <div className="w-full max-w-sm rounded-2xl bg-white p-6 shadow-xl">
        <h2 className="text-lg font-semibold text-blue-950">
          {title}
        </h2>
        <p className="mt-2 text-sm text-gray-600">
          {message}
        </p>

        {violationCount > 0 && (
          <div className="mt-3 rounded-lg bg-amber-50 border border-amber-200 px-3 py-2">
            <p className="text-sm font-semibold text-amber-800">
              Phát hiện {violationCount} vi phạm tab-out trong buổi thi
            </p>
            <p className="text-xs text-amber-600 mt-0.5">
              Hệ thống đã ghi nhận {violationCount > 1 ? `các lần` : 'lần'} bạn rời khỏi tab thi quá 10 giây.
            </p>
          </div>
        )}

        <div className="mt-6 flex gap-3">
          <button
            type="button"
            onClick={onCancel}
            disabled={isSubmitting}
            className="flex-1 rounded-lg border border-gray-300 px-4 py-2 text-sm font-semibold text-gray-700 transition hover:bg-gray-50 disabled:opacity-50"
          >
            Cancel
          </button>
          <button
            type="button"
            onClick={onConfirm}
            disabled={isSubmitting}
            className="flex-1 rounded-lg bg-orange-400 px-4 py-2 text-sm font-semibold text-white transition hover:bg-orange-500 disabled:opacity-50"
          >
            {isSubmitting ? "Submitting..." : confirmLabel}
          </button>
        </div>
      </div>
    </div>,
    document.body
  );
};

export default SubmitConfirmModal;
