import { useEffect, useRef, useCallback } from "react";

/**
 * Computes the anchor point for a note from its linked highlight's last rect.
 * Mirrors the logic in useHighlightInteraction.js → handleSelectionMenuAddNote
 * so a freshly-created anchor and a recalculated anchor agree.
 */
function anchorFromRect(rect) {
  const approxHalfChar = Math.max(Math.min(rect.width || 0, 14) / 2, 3);
  return {
    x: Math.max(rect.x + rect.width - approxHalfChar, 0),
    y: Math.max(rect.y, 0),
    baseline: Math.max(rect.y + rect.height, 0),
    width: rect.width,
  };
}

/**
 * Recalculates note anchors when their linked highlight moves (font size or
 * window resize / zoom). For notes with a highlightId:
 *   - Updates anchor.x/y/baseline/width to track the highlight's last rect
 *   - Shifts note.x/y by the same delta so the floating card follows the text
 *
 * Notes without a highlightId (free-floating notes the user dragged) are left
 * alone — moving them would fight the user's explicit positioning.
 *
 * Triggers off `highlights` changing — which already happens on fontLevel
 * change and window resize via useHighlightRecalculation. So note recalc is
 * naturally ordered after highlight recalc.
 */
export function useNoteRecalculation({ notes, highlights, updateNotes }) {
  const notesRef = useRef(notes);
  notesRef.current = notes;
  const updateNotesRef = useRef(updateNotes);
  updateNotesRef.current = updateNotes;

  const recalculate = useCallback(() => {
    const currentNotes = notesRef.current;
    if (!currentNotes || currentNotes.length === 0) return;

    const highlightById = new Map((highlights || []).map((h) => [h.id, h]));
    let anyChanged = false;

    const updated = currentNotes.map((note) => {
      if (!note?.highlightId) return note;
      const linked = highlightById.get(note.highlightId);
      if (!linked?.rects?.length) return note;

      const lastRect = linked.rects[linked.rects.length - 1];
      const newAnchor = anchorFromRect(lastRect);

      const oldAnchorX = note.anchor?.x ?? newAnchor.x;
      const oldAnchorY = note.anchor?.y ?? newAnchor.y;
      const dx = newAnchor.x - oldAnchorX;
      const dy = newAnchor.y - oldAnchorY;

      if (Math.abs(dx) < 1 && Math.abs(dy) < 1) return note;

      anyChanged = true;
      return {
        ...note,
        x: (note.x ?? 0) + dx,
        y: (note.y ?? 0) + dy,
        anchor: {
          ...note.anchor,
          ...newAnchor,
          surfaceId: note.anchor?.surfaceId || linked.surfaceId,
        },
      };
    });

    if (anyChanged) updateNotesRef.current(updated);
  }, [highlights]);

  useEffect(() => {
    recalculate();
  }, [recalculate]);
}
