import React from "react";

/**
 * SkipReviewConfirmModal — friction confirm before letting the student
 * skip the post-test review. Uses MODAL_NESTED so it stacks above ReviewModal.
 */
const SkipReviewConfirmModal = ({ isOpen, onConfirm, onCancel }) => {
  if (!isOpen) return null;

  return (
    <div
      role="dialog"
      aria-modal="true"
      className="fixed inset-0 z-modal-nested flex items-center justify-center bg-black/40 p-4 backdrop-blur-sm"
    >
      <div className="w-full max-w-sm rounded-2xl bg-white p-6 shadow-xl">
        <h3 className="text-base font-semibold text-blue-950">Bỏ qua đánh giá?</h3>
        <p className="mt-2 text-sm text-gray-600">
          Phản hồi của bạn giúp tụi mình điều chỉnh độ khó và đề xuất bài tập phù hợp hơn cho cả lớp. Chỉ mất 10 giây thôi!
        </p>
        <div className="mt-5 flex gap-3">
          <button
            type="button"
            onClick={onCancel}
            className="flex-1 rounded-lg bg-orange-400 px-4 py-2 text-sm font-semibold text-white transition hover:bg-orange-500"
          >
            Tiếp tục đánh giá
          </button>
          <button
            type="button"
            onClick={onConfirm}
            className="flex-1 rounded-lg border border-gray-300 px-4 py-2 text-sm font-semibold text-gray-600 transition hover:bg-gray-50"
          >
            Bỏ qua
          </button>
        </div>
      </div>
    </div>
  );
};

export default SkipReviewConfirmModal;
