// Pattern explanation:
// 1. __1__ or __2__ etc (explicit numbered blanks)
// 2. (8)_____ or (8) _____ where underscores are REQUIRED immediately after (n) - (n) is label ONLY
// 3. _{3,} standalone underscores (3+ underscores) OR …{3,} (3+ ellipsis dots)
// NOTE: (n) alone without underscores is just a LABEL, not a blank!
const GAP_PATTERN = /__\s*(\d+)\s*__|(?:\(\s*(\d+)\s*\)\s*)?(?:_{3,}|…{3,})/g;

const parseNumber = (value) => {
  const parsed = Number.parseInt(value, 10);
  return Number.isFinite(parsed) ? parsed : null;
};

export const parseGapContent = (content = "") => {
  const source = typeof content === "string" ? content : String(content || "");
  const placeholders = [];
  if (!source) {
    return { normalizedContent: "", placeholders };
  }

  let index = 0;
  const normalizedContent = source.replace(GAP_PATTERN, (match, inlineNumber, parenNumber) => {
    const number = parseNumber(inlineNumber ?? parenNumber);
    const token = `__GAP_${index}__`;
    placeholders.push({
      token,
      index,
      raw: match,
      number,
      hasExplicitNumber: number !== null,
    });
    index += 1;
    return token;
  });

  return { normalizedContent, placeholders };
};

export const getGapPlaceholderCount = (content = "") => {
  const { placeholders } = parseGapContent(content);
  return placeholders.length;
};

export const getGapNumbersFromContent = (content = "") => {
  const { placeholders } = parseGapContent(content);
  if (!placeholders.length) {
    return [];
  }
  return placeholders.map((placeholder, position) => {
    if (placeholder.number !== null) {
      return placeholder.number;
    }
    return position + 1;
  });
};

export const countGapSlots = (question = {}) => {
  const answersLength = Array.isArray(question?.correctAnswers)
    ? question.correctAnswers.length
    : 0;
  const subQuestions = Array.isArray(question?.subQuestions) ? question.subQuestions : [];
  const subQuestionLength = subQuestions.length;
  const contentCount = getGapPlaceholderCount(question?.content || "");

  const baseCount = Math.max(answersLength, subQuestionLength, contentCount, 1);
  const groupedCount = subQuestions.filter(sq => sq.isGrouped).length;

  return Math.max(baseCount - groupedCount, 1);
};

export default {
  parseGapContent,
  getGapPlaceholderCount,
  getGapNumbersFromContent,
  countGapSlots,
};
