/**
 * Generate question prompt/title with global numbering
 * Replaces hardcoded question numbers with dynamic calculations
 * 
 * Used in both Builder and Preview to ensure consistent numbering
 */

/**
 * Generate question range title (e.g. "Questions 1-5")
 * @param {number} startNum - Starting question number
 * @param {number} endNum - Ending question number
 * @returns {string} Question range title
 */
export const generateQuestionRangeTitle = (startNum, endNum) => {
  if (startNum == null) return "";
  if (startNum === endNum) return `Question ${startNum}`;
  return `Questions ${startNum}-${endNum}`;
};

/**
 * Generate instruction group title (e.g. "Questions 1-2: Choose the correct letter")
 * @param {number} startNum - Starting question number
 * @param {number} endNum - Ending question number
 * @param {string} description - Optional description/instruction
 * @returns {string} Formatted title with numbering
 */
export const generateInstructionGroupTitle = (startNum, endNum, description = "") => {
  const rangeTitle = generateQuestionRangeTitle(startNum, endNum);
  if (description && rangeTitle) {
    return `${rangeTitle}: ${description}`;
  }
  return rangeTitle || description;
};

/**
 * Generate single question title with optional instruction
 * @param {number} questionNum - Single question number
 * @param {string} description - Optional question instruction/description
 * @returns {string} Question title
 */
export const generateQuestionTitle = (questionNum, description = "") => {
  if (questionNum == null) return description;
  const qLabel = `Question ${questionNum}`;
  if (description) {
    return `${qLabel}: ${description}`;
  }
  return qLabel;
};

/**
 * Update question prompt with dynamic numbering
 * @param {string} originalPrompt - Original prompt from template
 * @param {number} startNum - Starting question number
 * @param {number} endNum - Ending question number
 * @returns {string} Updated prompt with question numbers
 */
export const updatePromptWithNumbering = (originalPrompt, startNum, endNum) => {
  if (!originalPrompt) {
    return generateQuestionRangeTitle(startNum, endNum);
  }
  
  // If prompt already contains numbers like "Questions X-Y" or similar, keep it
  // Otherwise prepend the question range
  if (/question/i.test(originalPrompt)) {
    return originalPrompt;
  }
  
  const rangeTitle = generateQuestionRangeTitle(startNum, endNum);
  return rangeTitle ? `${rangeTitle}\n${originalPrompt}` : originalPrompt;
};

/**
 * Calculate gap number for gap-filling questions using global numbering context
 * @param {number} gapIndex - Index of the gap (0-based)
 * @param {number} questionStartNum - Starting number of the question from global numbering
 * @returns {number} The calculated gap number
 */
export const calculateGapNumber = (gapIndex, questionStartNum = 1) => {
  return questionStartNum + gapIndex;
};
