const AUDIO_UPLOAD_TIMEOUT_MS = 8_000;

/**
 * Maps `sectionTabs[].type` (lowercase) to canonical `category` (TitleCase)
 * matching testBank_index.category. Returns null when sections are mixed
 * or when the type isn't in the v1 review-supported set — caller bypasses
 * the review modal in that case.
 */
function deriveReviewCategory(sectionTabs) {
  const types = (sectionTabs || []).map((s) => s?.type).filter(Boolean);
  if (types.length === 0) return null;
  const first = types[0];
  if (!types.every((t) => t === first)) return null;
  if (first === "reading") return "Reading";
  if (first === "listening") return "Listening";
  return null;
}

/**
 * Builds the `review` payload that ships in EXAM_RESULT to the portal.
 * `state` is what ReviewModal handed up; null/undefined means the gating
 * skipped the modal (no vote written).
 */
function buildReviewPayload(state, ctx) {
  if (!state) return null;
  const { triggeredBy, isPracticeMode, isPreviewMode, category } = ctx;
  const source = isPracticeMode ? "practice" : isPreviewMode ? "preview" : "exam";
  if (state.skipped) {
    return {
      category,
      skipped: true,
      domains: [],
      comment: "",
      triggeredBy,
      source,
    };
  }
  return {
    category,
    skipped: false,
    difficulty: state.difficulty,
    domains: Array.isArray(state.domains) ? state.domains : [],
    comment: typeof state.comment === "string" ? state.comment : "",
    triggeredBy,
    source,
  };
}

/**
 * Shared retry logic for modal retry buttons (ExamCompleteModal, SpeakingFollowupModal).
 * 1. If recovery hook already synced → skip write, flip to success
 * 2. If in-flight guard blocks → poll localStorage until synced
 * 3. Otherwise → normal write
 */
const handleModalRetry = async (examCode, setSubmitStatus, clearPersistedExamStorage, label) => {
  const pk = `weaver_${examCode}_pending_submission`;
  const raw = localStorage.getItem(pk);

  // Already synced — nothing to do
  if (raw) {
    const parsed = JSON.parse(raw);
    if (parsed?.synced) {
      console.log(`ℹ️ [${label}] Already synced — skipping retry.`);
      setSubmitStatus("success");
      clearPersistedExamStorage();
      return;
    }
  }

  setSubmitStatus("submitting");
  try {
    if (raw) {
      const pendingPayload = JSON.parse(raw);
      await submitExamResult(examCode, pendingPayload);
      localStorage.setItem(pk, JSON.stringify({ ...pendingPayload, synced: true, syncedAt: Date.now() }));
    }
    setSubmitStatus("success");
    clearPersistedExamStorage();
  } catch (e) {
    if (e.message === 'Submission already in progress — please wait.') {
      // Recovery hook is mid-write — poll until it marks synced
      console.log(`ℹ️ [${label}] Blocked by in-flight guard — polling for sync...`);
      const poll = setInterval(() => {
        try {
          const r = localStorage.getItem(pk);
          if (!r) { clearInterval(poll); return; }
          const p = JSON.parse(r);
          if (p?.synced) {
            clearInterval(poll);
            setSubmitStatus("success");
            clearPersistedExamStorage();
          }
        } catch (_) { clearInterval(poll); }
      }, 500);
      return;
    }
    console.error(`${label} retry failed:`, e);
    setSubmitStatus("error");
  }
};

const SUBMIT_STRATEGIES = {
  exam: {
    onFinalize: async (examCode, payload, opts) => {
      await submitExamResult(examCode, payload, opts);
    },
    onSpeakingDetected: (setters) => {
      setters.setIsSpeakingFollowupOpen(true);
      setters.setHasShownSpeakingFollowup(true);
    },
  },
  practice: {
    onFinalize: async () => ({ gradeOnly: true }),
    onSpeakingDetected: () => {},
  },
  preview: {
    onFinalize: async (examCode, payload) => {
      console.log("Preview payload:", payload);
      return { gradeOnly: true };
    },
    onSpeakingDetected: () => {},
  },
};

function resolveStrategy(isPreviewMode, isPracticeMode) {
  if (isPreviewMode) return SUBMIT_STRATEGIES.preview;
  if (isPracticeMode) return SUBMIT_STRATEGIES.practice;
  return SUBMIT_STRATEGIES.exam;
}

/**
 * useExamSubmission — encapsulates the entire exam submission lifecycle
 */
export function useExamSubmission({
  examCode,
  candidateProfile,
  studentInfo,
  isPreviewMode,
  isPracticeMode,
  isEmbedded,
  sectionTabs,
  sectionTabsAll,
  nonSpeakingKeys,
  examContent,
  answerKeyMap,
  answersRef, // mutable ref: { current: answersObject }
  gradeExam,
  setQuestionResults,
  setScoreSummary,
  scoreSummary,
  questionResults,
  setReviewMode,
  setFocusRequest,
  setActiveSection,
  startSkillTimerAtIndex,
  getSkillDurationSeconds,
  isSkillTimedMode,
  currentSkillIndex,
  gradeSection,
  hasSubmitted,
  setHasSubmitted,
  submittedSections,
  setSubmittedSections,
  startedAt,
}) {
  const strategy = useMemo(
    () => resolveStrategy(isPreviewMode, isPracticeMode),
    [isPreviewMode, isPracticeMode]
  );

  // ── Local submission state ──
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitStatus, setSubmitStatus] = useState("submitting");
  const [audioUploadSkipped, setAudioUploadSkipped] = useState(false);
  const [recoveredSubmission, setRecoveredSubmission] = useState(null);
  // Portal handshake — only meaningful in embedded mode. null outside embed.
  //   'pending'  → postMessage sent, waiting for EXAM_RESULT_ACK
  //   'acked'    → portal confirmed write
  //   'timeout'  → no ACK within 5s OR portal replied success:false
  // Treated as informational (warning on timeout), NOT a blocking failure —
  // the authoritative success signal is the Firestore write in submitExamResult.
  const [ackStatus, setAckStatus] = useState(null);

  // ── Modal states ──
  const [isExamCompleteModalOpen, setIsExamCompleteModalOpen] = useState(false);
  const [isResultModalOpen, setIsResultModalOpen] = useState(false);
  const [hasSeenResultModal, setHasSeenResultModal] = useState(false);
  const [isSubmitConfirmOpen, setIsSubmitConfirmOpen] = useState(false);
  const [isSpeakingFollowupOpen, setIsSpeakingFollowupOpen] = useState(false);
  const [hasShownSpeakingFollowup, setHasShownSpeakingFollowup] =
    useState(false);
  const [isSubmitSectionConfirmOpen, setIsSubmitSectionConfirmOpen] =
    useState(false);
  const [pendingSubmitSectionKey, setPendingSubmitSectionKey] = useState(null);

  // Review modal state (v1 — Reading/Listening only, gated by feature flag)
  const [isReviewModalOpen, setIsReviewModalOpen] = useState(false);
  const [isSkipReviewConfirmOpen, setIsSkipReviewConfirmOpen] = useState(false);
  // Draft state lives here (not inside ReviewModal) because the surrounding
  // `Modals` useMemo recreates its function definition on every dep change,
  // which unmounts ReviewModal and would wipe any internal state.
  const [reviewDraftDifficulty, setReviewDraftDifficulty] = useState(null);
  const [reviewDraftDomains, setReviewDraftDomains] = useState([]);
  const [reviewDraftComment, setReviewDraftComment] = useState("");
  // ReviewModal output staged here so handleConfirmSubmit can pick it up
  // without a state-driven re-render between modal close and submission.
  const reviewStateRef = useRef(null);
  const pendingTriggeredByRef = useRef("voluntary");

  const resetReviewDraft = useCallback(() => {
    setReviewDraftDifficulty(null);
    setReviewDraftDomains([]);
    setReviewDraftComment("");
  }, []);

  const toggleReviewDraftDomain = useCallback((value) => {
    setReviewDraftDomains((prev) => {
      const has = prev.includes(value);
      return has ? prev.filter((v) => v !== value) : [...prev, value];
    });
  }, []);
  // Feature flag, fetched once on mount. Defaults to true (fail-open).
  const [reviewModalFlag, setReviewModalFlag] = useState(() =>
    Boolean(getCachedFeatureFlags()?.reviewModal),
  );
  useEffect(() => {
    let active = true;
    getFeatureFlags()
      .then((flags) => {
        if (active) setReviewModalFlag(Boolean(flags?.reviewModal));
      })
      .catch(() => {});
    return () => {
      active = false;
    };
  }, []);
  const reviewCategory = useMemo(
    () => deriveReviewCategory(sectionTabs),
    [sectionTabs],
  );

  const finalizeSubmitRef = useRef(false);
  // Stash of the last EXAM_RESULT we posted to Portal, so waitForAck's onRetry
  // can re-post the same message bytes (Portal dedups on payload._docId).
  // Set inside `onPosted` callbacks passed to submitExamResult / postEmbeddedResult.
  const lastPostedRef = useRef(null);
  const [incompleteQuestionsModal, setIncompleteQuestionsModal] = useState({
    open: false,
    items: [],
    sectionKey: null,
  });

  // ── Report generation state ──
  const [isGeneratingReport, setIsGeneratingReport] = useState(false);
  const [reportPdfBlob, setReportPdfBlob] = useState(null);

  // violation count — set externally by AlertTabOut callback
  const violationCountRef = useRef(0);

  // ═══════════════════════════════════════════════════════════
  // OFFLINE DETECTION
  // ═══════════════════════════════════════════════════════════
  useEffect(() => {
    if (isPreviewMode) return;
    const handleOffline = () => {
      console.warn("🔌 [offline event] Browser went offline");
      if (isSubmitting && submitStatus === "submitting") {
        console.error(
          "🔌 [offline event] Was submitting — flipping modal to error"
        );
        setSubmitStatus("error");
      }
    };
    const handleOnline = () => {
      console.log("🟢 [online event] Browser is back online");
    };
    window.addEventListener("offline", handleOffline);
    window.addEventListener("online", handleOnline);
    return () => {
      window.removeEventListener("offline", handleOffline);
      window.removeEventListener("online", handleOnline);
    };
  }, [isSubmitting, submitStatus, isPreviewMode]);

  // ═══════════════════════════════════════════════════════════
  // BLOCK TAB CLOSE DURING SUBMISSION
  // ═══════════════════════════════════════════════════════════
  useEffect(() => {
    if (isPreviewMode) return;
    const handleBeforeUnload = (e) => {
      if (isSubmitting) {
        e.preventDefault();
        e.returnValue = "";
      }
    };
    window.addEventListener("beforeunload", handleBeforeUnload);
    return () => {
      window.removeEventListener("beforeunload", handleBeforeUnload);
    };
  }, [isSubmitting, isPreviewMode]);

  // ═══════════════════════════════════════════════════════════
  // clearPersistedExamStorage
  // ═══════════════════════════════════════════════════════════
  const clearPersistedExamStorage = useCallback(() => {
    try {
      if (!isPreviewMode) {
        const normalizedCode = String(examCode || "")
          .trim()
          .toUpperCase()
          .replace(/\s+/g, "_");
        localStorage.removeItem("studentInfo");
        localStorage.removeItem("weaver:candidateProfile");
        localStorage.removeItem("weaver:pendingExamCode");
        localStorage.removeItem(`weaver_sections_${normalizedCode}`);
        localStorage.removeItem(`weaver_draft_${normalizedCode}`);
        localStorage.removeItem(`weaver_${examCode}_autosave`);
        const localKeys = Object.keys(localStorage || {});
        localKeys.forEach((k) => {
          if (!k) return;
          if (
            k.indexOf(`weaver_${normalizedCode}`) === 0 ||
            (k.startsWith("weaver_") && k.includes(normalizedCode))
          ) {
            if (!k.endsWith("_pending_submission")) {
              localStorage.removeItem(k);
            }
          }
        });
      }
    } catch (err) {}
  }, [examCode, isPreviewMode]);

  // ═══════════════════════════════════════════════════════════
  // handleConfirmSubmit — the core submission function
  // ═══════════════════════════════════════════════════════════
  const handleConfirmSubmit = useCallback(async () => {
    console.log(
      "🐛 [handleConfirmSubmit] ENTRY. guard values: finalizeRef:",
      finalizeSubmitRef.current,
      "isSubmitting:",
      isSubmitting,
      "hasSubmitted:",
      hasSubmitted,
      "isPracticeMode:",
      isPracticeMode,
      "isPreviewMode:",
      isPreviewMode
    );
    if (finalizeSubmitRef.current || isSubmitting || hasSubmitted) {
      console.log(
        "🐛 [handleConfirmSubmit] BLOCKED by guard. finalizeRef:",
        finalizeSubmitRef.current,
        "isSubmitting:",
        isSubmitting,
        "hasSubmitted:",
        hasSubmitted
      );
      return;
    }
    finalizeSubmitRef.current = true;
    setIsSubmitConfirmOpen(false);
    setIsReviewModalOpen(false);
    setIsSkipReviewConfirmOpen(false);
    console.log(
      "🐛 [handleConfirmSubmit] PROCEEDING with submit. isPreviewMode:",
      isPreviewMode
    );

    // Drain the staged review payload exactly once. Cleared after read so
    // a defensive re-call can never double-submit a vote.
    const reviewPayload = buildReviewPayload(reviewStateRef.current, {
      triggeredBy: pendingTriggeredByRef.current,
      isPracticeMode,
      isPreviewMode,
      category: reviewCategory,
    });
    reviewStateRef.current = null;
    setIsSubmitting(true);
    setHasSubmitted(true);
    let submitSucceeded = false;
    try {
      let finalAnswers = { ...answersRef.current };

      console.log("📋 Answer Key Map:", answerKeyMap);
      console.log("📝 User Answers (Final):", finalAnswers);

      const { summary, questionResults: results } = gradeExam(
        finalAnswers,
        answerKeyMap
      );

      console.log("📊 Grading Summary:", summary);
      console.log("✅ Question Results:", results);

      setScoreSummary(summary);
      setQuestionResults(results);
      setReviewMode(true);
      setFocusRequest(null);

      if (isPreviewMode) {
        console.log(
          "🐛 [handleConfirmSubmit] PREVIEW PATH — opening ResultModal"
        );
        setIsResultModalOpen(true);
        setHasSeenResultModal(true);
        if (isEmbedded && window.parent !== window) {
          // Attach ACK listener BEFORE posting so there's no race. postEmbeddedResult
          // is async (getDoc testBank_index) so the listener is live well before
          // postMessage fires, but we belt-and-suspender it here anyway.
          //
          // onRetry re-posts the same stashed message on each waitForAck
          // attempt. Portal dedups on payload._docId so this is safe.
          setAckStatus("pending");
          lastPostedRef.current = null;
          waitForAck(examCode, 5000, 2, 1000, (attempt) => {
            const stash = lastPostedRef.current;
            if (!stash) {
              console.warn(`[useExamSubmission] ACK retry #${attempt} (preview): no stashed post yet, skipping re-post`);
              return;
            }
            console.warn(`[useExamSubmission] ACK retry #${attempt} (preview): re-posting EXAM_RESULT for ${examCode}`);
            window.parent.postMessage(stash.message, stash.targetOrigin);
          })
            .then(() => setAckStatus("acked"))
            .catch((ackErr) => {
              console.warn("[useExamSubmission] ACK timeout/failure (preview):", ackErr.message);
              setAckStatus("timeout");
              // Practice/preview mode does NO examSubmissions write — postMessage
              // is the only delivery path. An unACKed result is otherwise lost,
              // so persist a recoverable copy to backup_submit (ACKDROP_ prefix).
              // Best-effort: a failed backup must not surface to the student.
              const stash = lastPostedRef.current;
              const droppedPayload = stash?.message?.payload || {
                examCode,
                summary,
                answers: finalAnswers,
                questionResults: results,
                _startedAt: startedAt || null,
              };
              backupDroppedResult(examCode, droppedPayload, {
                mode: isPracticeMode ? "practice" : "preview",
                targetOrigin: stash?.targetOrigin || null,
              }).catch(() => {});
            });
          postEmbeddedResult(examCode, summary, finalAnswers, results, startedAt, {
            onPosted: (info) => { lastPostedRef.current = info; },
            review: reviewPayload,
          }).catch((e) =>
            console.warn("[postEmbeddedResult] failed:", e.message)
          );
        }
      } else {
        const hasSpeaking1v1 = examContent?.options?.speakingMode === "1v1";
        console.log(
          "🐛 [handleConfirmSubmit] NON-PREVIEW PATH — hasSpeaking1v1:",
          hasSpeaking1v1
        );
        if (hasSpeaking1v1) {
          console.log(
            "🐛 [handleConfirmSubmit] Opening SpeakingFollowupModal"
          );
          strategy.onSpeakingDetected({
            setIsSpeakingFollowupOpen,
            setHasShownSpeakingFollowup,
          });
        } else {
          console.log("🐛 [handleConfirmSubmit] Opening ExamCompleteModal");
          setIsExamCompleteModalOpen(true);
        }
      }

      if (isPreviewMode) {
        console.log(
          "📢 [Preview Mode] Generating submission payload for inspection..."
        );
        const cloneAnswers = cleanWritingAnswers(
          JSON.parse(JSON.stringify(finalAnswers || {})),
          examContent
        );
        const safeAnswers = sanitizeForFirestore(cloneAnswers);
        const safeResults = sanitizeForFirestore(results);
        const safeSummary = sanitizeForFirestore(summary);
        const safeCandidate = candidateProfile
          ? sanitizeForFirestore(candidateProfile)
          : null;
        const storedProfile = JSON.parse(
          localStorage.getItem("weaver:candidateProfile") || "null"
        );
        const student = candidateProfile || studentInfo || storedProfile || {};
        const candidateData = safeCandidate || null;
        const payload = {
          examCode,
          _startedAt: startedAt || Date.now(),
          answers: safeAnswers,
          summary: safeSummary,
          questionResults: safeResults,
          candidate: candidateData,
          studentName:
            student?.fullName || candidateData?.fullName || null,
          email: student?.email || candidateData?.email || null,
          phone: student?.phone || candidateData?.phone || null,
        };
        console.log(
          "📢 [Preview Mode] FIREBASE PAYLOAD (JSON):",
          JSON.stringify(payload, null, 2)
        );
      }

      if (!isPreviewMode) {
        const cloneAnswers = cleanWritingAnswers(
          JSON.parse(JSON.stringify(finalAnswers || {})),
          examContent
        );

        const safeAnswers = sanitizeForFirestore(cloneAnswers);
        const safeResults = sanitizeForFirestore(results);
        const safeSummary = sanitizeForFirestore(summary);
        const safeCandidate = candidateProfile
          ? sanitizeForFirestore(candidateProfile)
          : null;

        const storedProfile = JSON.parse(
          localStorage.getItem("weaver:candidateProfile") || "null"
        );
        const student = candidateProfile || studentInfo || storedProfile || {};
        const candidateData = safeCandidate || null;
        const payload = {
          examCode,
          _docId: generateDocId(), // Deterministic ID — all retries write to the same Firestore doc
          _startedAt: startedAt || Date.now(),
          answers: safeAnswers,
          summary: safeSummary,
          questionResults: safeResults,
          candidate: candidateData,
          studentName:
            student?.fullName || candidateData?.fullName || null,
          email: student?.email || candidateData?.email || null,
          phone: student?.phone || candidateData?.phone || null,
          review: reviewPayload,
        };

        const pendingKey = `weaver_${examCode}_pending_submission`;

        try {
          localStorage.setItem(pendingKey, JSON.stringify(payload));
          console.log(
            "💾 [Safety Net] Saved payload to localStorage BEFORE audio upload"
          );
        } catch (storageErr) {
          console.warn(
            "⚠️ Could not save pending submission to localStorage:",
            storageErr
          );
        }

        try {
          const answersWithAudio = await Promise.race([
            uploadSpeakingAudioBlobs(examCode, cloneAnswers),
            new Promise((_, reject) =>
              setTimeout(
                () => reject(new Error("Audio upload timed out")),
                AUDIO_UPLOAD_TIMEOUT_MS
              )
            ),
          ]);
          payload.answers = sanitizeForFirestore(answersWithAudio);
          try {
            localStorage.setItem(pendingKey, JSON.stringify(payload));
            console.log(
              "💾 [Upgrade] Overwritten localStorage with audio URLs"
            );
          } catch (e) {}
        } catch (audioErr) {
          console.warn(
            "⚠️ Audio upload failed/timed out — submitting without audio URLs:",
            audioErr.message
          );
          setAudioUploadSkipped(true);
        }

        const issues = findUnsupported(payload);
        if (issues.length > 0) {
          console.warn("🛑 Unsafe payload fields before submit:", issues);
        }

        let sanitizedPayload;
        try {
          sanitizedPayload = preparePayloadForFirestore(payload);
        } catch (sanitizeErr) {
          console.error(
            "⚠️ preparePayloadForFirestore crashed, falling back to raw payload:",
            sanitizeErr
          );
          sanitizedPayload = payload;
        }

        try {
          localStorage.setItem(pendingKey, JSON.stringify(sanitizedPayload));
          console.log("💾 [Upgraded] Saved sanitized payload to localStorage");
        } catch (storageErr) {}

        // Start ACK handshake BEFORE onFinalize fires its postMessage. The
        // exam-side Firestore write inside submitExamResult happens first, so
        // the listener is registered well ahead of the postMessage that Portal
        // replies to. Treated as informational — not a blocking failure.
        //
        // onRetry re-posts the same stashed message on each waitForAck
        // attempt. Portal dedups on payload._docId so re-posts never trigger
        // a second commitExamResult call.
        if (isEmbedded && window.parent !== window) {
          setAckStatus("pending");
          lastPostedRef.current = null;
          waitForAck(examCode, 5000, 2, 1000, (attempt) => {
            const stash = lastPostedRef.current;
            if (!stash) {
              console.warn(`[useExamSubmission] ACK retry #${attempt} (exam): no stashed post yet, skipping re-post`);
              return;
            }
            console.warn(`[useExamSubmission] ACK retry #${attempt} (exam): re-posting EXAM_RESULT for ${examCode}`);
            window.parent.postMessage(stash.message, stash.targetOrigin);
          })
            .then(() => setAckStatus("acked"))
            .catch((ackErr) => {
              console.warn("[useExamSubmission] ACK timeout/failure (exam):", ackErr.message);
              setAckStatus("timeout");
            });
        }

        let submitError = null;
        const SUBMIT_MIN_SPIN_MS = 2000;
        const SUBMIT_MAX_TIMEOUT_MS = 30000;

        const finalizePromise = strategy.onFinalize(examCode, sanitizedPayload, {
          onPosted: (info) => { lastPostedRef.current = info; },
        })
          .catch((err) => {
            submitError = err;
            backupFailedSubmission(examCode, payload, err).catch(() => {});
          });

        // Wait at least MIN_SPIN, at most MAX_TIMEOUT. After max timeout, force error state.
        const minSpinPromise = new Promise((r) => setTimeout(r, SUBMIT_MIN_SPIN_MS));
        const maxTimeoutPromise = new Promise((r) => setTimeout(r, SUBMIT_MAX_TIMEOUT_MS));

        // Race: first one to resolve/reject wins. We wrap finalizePromise so it always resolves.
        const wrappedFinalize = finalizePromise.then(() => 'done');
        const raceResult = await Promise.race([
          wrappedFinalize,
          maxTimeoutPromise.then(() => 'timeout'),
        ]);

        // Ensure minimum spin time regardless of outcome
        await minSpinPromise;

        if (raceResult === 'timeout') {
          console.error("⏰ [Submit] Firestore write timed out after", SUBMIT_MAX_TIMEOUT_MS, "ms — forcing error state");
          if (!submitError) {
            submitError = new Error(`Submission timed out after ${SUBMIT_MAX_TIMEOUT_MS / 1000}s`);
          }
        }

        // Don't re-await finalizePromise — it may still be hanging.
        // If it succeeded, we already caught that via raceResult === 'done'.
        // If it timed out, we've already set submitError above.

        if (!submitError) {
          submitSucceeded = true;
          setSubmitStatus("success");

          examTrackingService.setAnsweredCount(
            Object.values(finalAnswers || {}).reduce((acc, sectionAnswers) => {
              if (
                typeof sectionAnswers === "object" &&
                sectionAnswers !== null
              ) {
                return (
                  acc +
                  Object.values(sectionAnswers).filter(
                    (v) => v !== null && v !== undefined && v !== ""
                  ).length
                );
              }
              return acc;
            }, 0)
          );
          examTrackingService.finalize("submitted").catch(() => {});

          try {
            const syncedPayload = { ...payload, synced: true, syncedAt: Date.now() };
            localStorage.setItem(pendingKey, JSON.stringify(syncedPayload));
          } catch (_) {}
          console.log(
            "✅ Marked as synced in localStorage (Firestore write succeeded)"
          );
        } else {
          setSubmitStatus("error");
          throw submitError;
        }
      }
    } catch (error) {
      console.error("Unable to submit exam results:", error);
      setSubmitStatus("error");
      // No window.confirm — it blocks the JS thread, preventing the recovery
      // hook's retry interval from firing. The ExamCompleteModal shows error
      // state with a retry button, and useSubmissionRecovery handles automatic
      // retries in the background. localStorage already has the pending_submission.
    } finally {
      setIsSubmitting(false);
      if (submitSucceeded) {
        clearPersistedExamStorage();
      }
    }
  }, [
    isSubmitting,
    hasSubmitted,
    answersRef,
    answerKeyMap,
    gradeExam,
    setScoreSummary,
    setQuestionResults,
    setReviewMode,
    setFocusRequest,
    isPreviewMode,
    isEmbedded,
    examCode,
    examContent,
    candidateProfile,
    studentInfo,
    strategy,
    clearPersistedExamStorage,
    isPracticeMode,
    setHasSubmitted,
    startedAt,
    reviewCategory,
  ]);

  // ═══════════════════════════════════════════════════════════
  // ReviewModal — gating + handlers
  // ═══════════════════════════════════════════════════════════

  /**
   * Returns true when the post-submit ReviewModal should fire for this run.
   * - Feature flag must be on (defaults true; admin can flip in Firestore Console)
   * - Category must be a v1-supported one (Reading/Listening only)
   * - Must be embedded (`isEmbedded === true`). Standalone WeaverTest
   *   (test.weaver.edu.vn opened directly) has no postMessage path back to
   *   the portal — `postEmbeddedResult` short-circuits when
   *   `window.parent === window`, so any review the student filled out would
   *   silently disappear. Better to not solicit feedback we can't capture.
   * - Must be in practice mode (`isPracticeMode === true`) — `/practice/` and
   *   `/homework/` routes. Other routes are excluded because:
   *     - `/exam/{examCode}` (standalone standardized exam): already validated
   *       by the test author; not the kind of test we want students to retag.
   *     - `?preview=true` / examManager preview / `weaver_preview_draft_*`
   *       (dev / content-author paths): these aren't real student opinion.
   */
  const shouldOpenReviewModal = useCallback(() => {
    if (!reviewModalFlag) return false;
    if (!isReviewEnabledForCategory(reviewCategory)) return false;
    if (!isPracticeMode) return false;
    if (!isEmbedded) return false;
    return true;
  }, [reviewModalFlag, reviewCategory, isPracticeMode, isEmbedded]);

  /**
   * Wrapper for SubmitConfirmModal.onConfirm. If review is gated in,
   * close the confirm dialog and hand off to ReviewModal. Otherwise,
   * proceed straight to handleConfirmSubmit (legacy behavior).
   */
  const handleSubmitConfirmOk = useCallback(() => {
    if (shouldOpenReviewModal()) {
      pendingTriggeredByRef.current = "voluntary";
      resetReviewDraft();
      setIsSubmitConfirmOpen(false);
      setIsReviewModalOpen(true);
      return;
    }
    handleConfirmSubmit();
  }, [shouldOpenReviewModal, handleConfirmSubmit, resetReviewDraft]);

  const handleReviewSubmit = useCallback(() => {
    reviewStateRef.current = {
      skipped: false,
      difficulty: reviewDraftDifficulty,
      domains: reviewDraftDomains,
      comment: reviewDraftComment,
    };
    setIsReviewModalOpen(false);
    handleConfirmSubmit();
  }, [
    handleConfirmSubmit,
    reviewDraftDifficulty,
    reviewDraftDomains,
    reviewDraftComment,
  ]);

  const handleReviewSkipRequest = useCallback(() => {
    setIsSkipReviewConfirmOpen(true);
  }, []);

  const handleReviewSkipConfirm = useCallback(() => {
    reviewStateRef.current = { skipped: true };
    setIsSkipReviewConfirmOpen(false);
    setIsReviewModalOpen(false);
    handleConfirmSubmit();
  }, [handleConfirmSubmit]);

  const handleReviewSkipCancel = useCallback(() => {
    setIsSkipReviewConfirmOpen(false);
  }, []);

  // ═══════════════════════════════════════════════════════════
  // handleSubmitExam — open confirm dialog with validation
  // ═══════════════════════════════════════════════════════════
  const handleSubmitExam = useCallback(() => {
    if (isPreviewMode) {
      setIsSubmitConfirmOpen(true);
      return;
    }
    let allIncomplete = [];
    const sectionsToCheck =
      Array.isArray(sectionTabs) && sectionTabs.length > 0
        ? sectionTabs
        : [];

    sectionsToCheck.forEach((section) => {
      const sectionKey = section.key;
      const incomplete = findIncompleteQuestions(
        sectionKey,
        examContent,
        answersRef.current
      );
      if (incomplete && incomplete.length > 0) {
        allIncomplete = [...allIncomplete, ...incomplete];
      }
    });

    if (allIncomplete.length > 0) {
      setIncompleteQuestionsModal({
        open: true,
        items: allIncomplete,
        sectionKey: null,
      });
      return;
    }

    setIsSubmitConfirmOpen(true);
  }, [isPreviewMode, sectionTabs, examContent, answersRef]);

  // ═══════════════════════════════════════════════════════════
  // handleSubmitSection — submit a single section
  // ═══════════════════════════════════════════════════════════
  const handleSubmitSection = useCallback(
    (sectionKeyArg, activeSection) => {
      const sectionKey = sectionKeyArg || activeSection;
      if (!sectionKey) return;
      const missing = findIncompleteQuestions(
        sectionKey,
        examContent,
        answersRef.current
      );
      if (missing.length > 0) {
        setIncompleteQuestionsModal({
          open: true,
          items: missing,
          sectionKey,
        });
        return;
      }
      setPendingSubmitSectionKey(sectionKey);
      setIsSubmitSectionConfirmOpen(true);
    },
    [examContent, answersRef]
  );

  // ═══════════════════════════════════════════════════════════
  // handleConfirmSubmitSection — grade and advance
  // ═══════════════════════════════════════════════════════════
  const handleConfirmSubmitSection = useCallback(async () => {
    const sectionKey = pendingSubmitSectionKey;
    if (!sectionKey) return;
    setIsSubmitSectionConfirmOpen(false);
    let previousSubmitted = Array.from(submittedSections || []);
    try {
      const currentSubmitted = Array.from(
        new Set([...(previousSubmitted || []), sectionKey])
      );
      const idx = sectionTabs.findIndex((t) => t.key === sectionKey);
      let nextIdx = -1;
      for (let i = idx + 1; i < sectionTabs.length; i += 1) {
        if (!currentSubmitted.includes(sectionTabs[i].key)) {
          nextIdx = i;
          break;
        }
      }
      setSubmittedSections(currentSubmitted);
      if (nextIdx >= 0) {
        const nextKey = sectionTabs[nextIdx].key;
        setActiveSection(nextKey);
        if (isSkillTimedMode) {
          const duration = getSkillDurationSeconds(nextIdx);
          startSkillTimerAtIndex(nextIdx, duration);
        }
      } else {
        if (isSkillTimedMode) {
          const savedStudentRaw = localStorage.getItem("studentInfo") || "{}";
          const savedStudent =
            studentInfo ||
            (savedStudentRaw ? JSON.parse(savedStudentRaw) : {});
          const hasStudentInfo =
            savedStudent && Object.keys(savedStudent).length > 0;
          const hasCandidateProfile = !!candidateProfile;
          if (!hasStudentInfo && !hasCandidateProfile) {
            if (!isSubmitConfirmOpen) setIsSubmitConfirmOpen(true);
          } else {
            handleConfirmSubmit();
          }
        }
      }
      gradeSection(sectionKey).catch((err) =>
        console.error("Failed to grade section (background):", err)
      );
    } catch (error) {
      console.error("Failed to submit section:", error);
      setSubmittedSections(previousSubmitted || []);
    } finally {
      setPendingSubmitSectionKey(null);
    }
  }, [
    pendingSubmitSectionKey,
    submittedSections,
    sectionTabs,
    isSkillTimedMode,
    getSkillDurationSeconds,
    startSkillTimerAtIndex,
    setActiveSection,
    studentInfo,
    candidateProfile,
    isSubmitConfirmOpen,
    handleConfirmSubmit,
    gradeSection,
    setSubmittedSections,
  ]);

  // ═══════════════════════════════════════════════════════════
  // handleReview / handleResultModalClose / handleCloseSpeakingFollowup
  // ═══════════════════════════════════════════════════════════
  const handleReview = useCallback(() => {
    console.log(
      "🐛 [handleReview] Closing ResultModal, setting reviewMode."
    );
    setIsResultModalOpen(false);
    setReviewMode(true);
  }, [setReviewMode]);

  const handleResultModalClose = useCallback(() => {
    console.log("🐛 [handleResultModalClose] Closing ResultModal (Done).");
    setIsResultModalOpen(false);
  }, []);

  const handleCloseSpeakingFollowup = useCallback(() => {
    setIsSpeakingFollowupOpen(false);
    window.location.href = "/";
  }, []);

  // ═══════════════════════════════════════════════════════════
  // PDF report generation
  // ═══════════════════════════════════════════════════════════
  const handlePreviewReport = useCallback(async () => {
    if (reportPdfBlob) {
      const { openPdfInPopup } = await import("../../../utils/docxPreview");
      openPdfInPopup(reportPdfBlob, `Report Preview - ${examCode}`);
    } else {
      setIsGeneratingReport(true);
      try {
        await generateFilledPDFReport(scoreSummary || {});
      } catch (error) {
        console.error("Failed to generate report:", error);
        alert("Failed to generate report. Please try again.");
      } finally {
        setIsGeneratingReport(false);
      }
    }
  }, [reportPdfBlob, examCode, scoreSummary]);

  const generateFilledPDFReport = useCallback(
    async (gradeData) => {
      try {
        setIsGeneratingReport(true);
        const { fetchDocxTemplate, fillPDFTemplate } = await import(
          "../../../utils/pdfFiller"
        );
        const template = await fetchDocxTemplate();
        if (!template) {
          throw new Error("Failed to fetch DOCX template.");
        }
        const filledDocxBlob = await fillPDFTemplate(
          template,
          gradeData,
          candidateProfile
        );
        if (isPreviewMode) {
          const { API_BASE_URL } = await import("../../../constants");
          const formData = new FormData();
          formData.append(
            "file",
            filledDocxBlob,
            `Report_${examCode}.docx`
          );
          const response = await fetch(
            `${API_BASE_URL}/api/convert-docx-to-pdf`,
            { method: "POST", body: formData }
          );
          if (!response.ok) {
            throw new Error(
              `Backend conversion failed: ${response.statusText}`
            );
          }
          const pdfBlob = await response.blob();
          setReportPdfBlob(pdfBlob);
        } else {
          // non-preview mode doesn't store docx blob
        }
      } catch (error) {
        console.error("Error generating report:", error);
        alert(`Failed to generate report: ${error.message}`);
      } finally {
        setIsGeneratingReport(false);
      }
    },
    [candidateProfile, isPreviewMode, examCode]
  );

  // ═══════════════════════════════════════════════════════════
  // AUTO-ADVANCE FINALIZE (timer=0 on last section)
  // ═══════════════════════════════════════════════════════════
  const autoAdvanceFinalizeRef = useRef(false);

  const triggerAutoFinalize = useCallback(() => {
    if (autoAdvanceFinalizeRef.current) return;
    autoAdvanceFinalizeRef.current = true;
    const savedStudentRaw = localStorage.getItem("studentInfo") || "{}";
    const savedStudent =
      studentInfo || (savedStudentRaw ? JSON.parse(savedStudentRaw) : {});
    const hasStudentInfo = savedStudent && Object.keys(savedStudent).length > 0;
    const hasCandidateProfile = !!candidateProfile;
    if (!hasStudentInfo && !hasCandidateProfile) {
      if (!isSubmitConfirmOpen) setIsSubmitConfirmOpen(true);
    } else if (shouldOpenReviewModal()) {
      // Auto-finalize still shows the review modal (per v1 spec). The skip
      // rate on these triggers is a v1 telemetry goal — if it's much higher
      // than voluntary, we'll revisit in v2.
      pendingTriggeredByRef.current = "autoFinalize";
      resetReviewDraft();
      setIsReviewModalOpen(true);
    } else {
      handleConfirmSubmit();
    }
    setTimeout(() => {
      autoAdvanceFinalizeRef.current = false;
    }, 500);
  }, [
    studentInfo,
    candidateProfile,
    isSubmitConfirmOpen,
    handleConfirmSubmit,
    shouldOpenReviewModal,
    resetReviewDraft,
  ]);

  // ═══════════════════════════════════════════════════════════
  // EXPOSED VALUES
  // ═══════════════════════════════════════════════════════════

  // ── Modals bundle ──
  const Modals = useMemo(() => {
    const ModalBundle = ({ activeSection }) => (
      <>
        <IncompleteQuestionsModal
          isOpen={incompleteQuestionsModal.open}
          items={incompleteQuestionsModal.items}
          onClose={() =>
            setIncompleteQuestionsModal({
              open: false,
              items: [],
              sectionKey: null,
            })
          }
          onFocusFirst={() => {
            const target = incompleteQuestionsModal.items?.[0];
            if (!target) return;
            setActiveSection(
              incompleteQuestionsModal.sectionKey || activeSection
            );
            setFocusRequest({
              sectionKey:
                incompleteQuestionsModal.sectionKey || activeSection,
              questionId: target.id,
              meta: target.meta || {},
              attempts: 0,
            });
            setIncompleteQuestionsModal({
              open: false,
              items: [],
              sectionKey: null,
            });
          }}
          onSkipSubmit={() => {
            const sectionKey =
              incompleteQuestionsModal.sectionKey || activeSection;
            setIncompleteQuestionsModal({
              open: false,
              items: [],
              sectionKey: null,
            });
            if (sectionKey) {
              setPendingSubmitSectionKey(sectionKey);
              setIsSubmitSectionConfirmOpen(true);
            } else {
              setIsSubmitConfirmOpen(true);
            }
          }}
        />
        <SubmitConfirmModal
          isOpen={isSubmitConfirmOpen}
          isSubmitting={isSubmitting}
          onConfirm={handleSubmitConfirmOk}
          onCancel={() => setIsSubmitConfirmOpen(false)}
          title={"Submit Exam?"}
          message={
            "Are you sure you want to submit your exam? Once submitted, you cannot make any changes."
          }
          confirmLabel={"Submit"}
          violationCount={violationCountRef.current}
        />
        <SubmitConfirmModal
          isOpen={isSubmitSectionConfirmOpen}
          isSubmitting={false}
          onConfirm={handleConfirmSubmitSection}
          onCancel={() => setIsSubmitSectionConfirmOpen(false)}
          title={"Submit Section?"}
          message={
            "Bạn có chắc chắn muốn qua phần thi tiếp theo? Bạn không thể quay lại phần thi đã submit"
          }
          confirmLabel={"Submit"}
        />
        {/* ReviewModal and SkipReviewConfirmModal are intentionally NOT rendered
            here. They live in index.jsx so that the surrounding `Modals` useMemo
            (which recreates ModalBundle on every dep change) doesn't unmount
            them and wipe their working state. */}
        {isExamCompleteModalOpen && (
          <ExamCompleteModal
            isOpen={isExamCompleteModalOpen}
            submitStatus={submitStatus}
            ackStatus={ackStatus}
            audioUploadSkipped={audioUploadSkipped}
            onClose={() => {
              setIsExamCompleteModalOpen(false);
              window.location.href = "/";
            }}
            onRetry={() => handleModalRetry(examCode, setSubmitStatus, clearPersistedExamStorage, 'ExamCompleteModal')}
          />
        )}
        {isResultModalOpen && (
          <ResultModal
            isOpen={isResultModalOpen}
            scoreSummary={scoreSummary || {}}
            questionResults={questionResults || {}}
            onClose={handleResultModalClose}
            onReview={handleReview}
            isPreviewMode={isPreviewMode}
            hasReportBlob={!!reportPdfBlob}
            isGeneratingReport={isGeneratingReport}
            onPreviewReport={handlePreviewReport}
            sectionTabsAll={sectionTabsAll}
            isPracticeMode={isPracticeMode}
            isEmbedded={isEmbedded}
            ackStatus={ackStatus}
          />
        )}
        <SpeakingFollowupModal
          isOpen={isSpeakingFollowupOpen}
          onClose={handleCloseSpeakingFollowup}
          speakingMeetUrl={examContent?.options?.speakingMeetUrl}
          nonSpeakingCount={nonSpeakingKeys?.length || 0}
          submitStatus={submitStatus}
          audioUploadSkipped={audioUploadSkipped}
          onRetry={() => handleModalRetry(examCode, setSubmitStatus, clearPersistedExamStorage, 'SpeakingFollowupModal')}
        />
      </>
    );
    return ModalBundle;
  }, [
    incompleteQuestionsModal,
    isSubmitConfirmOpen,
    isSubmitting,
    handleSubmitConfirmOk,
    isSubmitSectionConfirmOpen,
    handleConfirmSubmitSection,
    isExamCompleteModalOpen,
    submitStatus,
    ackStatus,
    audioUploadSkipped,
    examCode,
    clearPersistedExamStorage,
    isResultModalOpen,
    scoreSummary,
    questionResults,
    handleResultModalClose,
    handleReview,
    isPreviewMode,
    reportPdfBlob,
    isGeneratingReport,
    handlePreviewReport,
    sectionTabsAll,
    isPracticeMode,
    isEmbedded,
    isSpeakingFollowupOpen,
    handleCloseSpeakingFollowup,
    examContent,
    nonSpeakingKeys,
    setActiveSection,
    setFocusRequest,
  ]);

  return {
    // State
    hasSubmitted,
    setHasSubmitted,
    isSubmitting,
    submitStatus,
    setSubmitStatus,
    ackStatus,
    audioUploadSkipped,
    submittedSections,
    setSubmittedSections,
    recoveredSubmission,
    setRecoveredSubmission,
    isExamCompleteModalOpen,
    setIsExamCompleteModalOpen,
    isResultModalOpen,
    setIsResultModalOpen,
    hasSeenResultModal,
    setHasSeenResultModal,
    isSubmitConfirmOpen,
    setIsSubmitConfirmOpen,
    isSpeakingFollowupOpen,
    hasShownSpeakingFollowup,
    isSubmitSectionConfirmOpen,
    pendingSubmitSectionKey,
    incompleteQuestionsModal,
    setIncompleteQuestionsModal,

    // Report
    isGeneratingReport,
    reportPdfBlob,
    setReportPdfBlob,

    // Functions
    handleSubmitExam,
    handleConfirmSubmit,
    handleSubmitSection,
    handleConfirmSubmitSection,
    handleReview,
    handleResultModalClose,
    handleCloseSpeakingFollowup,
    clearPersistedExamStorage,
    handlePreviewReport,
    generateFilledPDFReport,

    // Refs for external access
    finalizeSubmitRef,
    violationCountRef,
    triggerAutoFinalize,

    // Review modal state + handlers (rendered in index.jsx — see comment in
    // Modals JSX above explaining why they live outside the useMemo'd bundle)
    isReviewModalOpen,
    isSkipReviewConfirmOpen,
    reviewCategory,
    reviewDraftDifficulty,
    reviewDraftDomains,
    reviewDraftComment,
    setReviewDraftDifficulty,
    toggleReviewDraftDomain,
    setReviewDraftComment,
    handleReviewSubmit,
    handleReviewSkipRequest,
    handleReviewSkipConfirm,
    handleReviewSkipCancel,

    // Modals component
    Modals,
  };
}
