import React from "react";
import QuestionCard from "../Question/QuestionCard";
import { createBaseQuestion } from "../../../../utils/question/questionDefaults";
import { generateId } from "../../../../utils/question/idUtils";

function CustomSectionBuilder({ data = {}, onChange }) {
  const section = {
    title: "",
    instructions: "",
    questions: [],
    groups: [],
    displayOrder: [],
    ...data,
  };

  const handleTitleChange = (event) => {
    onChange({ ...section, title: event.target.value });
  };

  const handleInstructionsChange = (event) => {
    onChange({ ...section, instructions: event.target.value });
  };

  const handleAddStandaloneQuestion = () => {
    const questions = section.questions || [];
    onChange({
      ...section,
      questions: [...questions, createBaseQuestion()],
    });
  };

  const handleRemoveStandaloneQuestion = (questionIndex) => {
    const questions = (section.questions || []).filter((_, index) => index !== questionIndex);
    onChange({ ...section, questions });
  };

  const handleStandaloneQuestionChange = (questionIndex, fieldOrUpdater, value) => {
    const questions = (section.questions || []).map((question, index) => {
      if (index !== questionIndex) return question;

      if (typeof fieldOrUpdater === "function") {
        const nextQuestion = fieldOrUpdater(question);
        return nextQuestion || question;
      }

      if (fieldOrUpdater && typeof fieldOrUpdater === "object") {
        return { ...question, ...fieldOrUpdater };
      }

      if (typeof fieldOrUpdater === "string") {
        return { ...question, [fieldOrUpdater]: value };
      }

      return question;
    });

    onChange({ ...section, questions });
  };

  const handleAddGroup = () => {
    const groups = section.groups || [];
    onChange({
      ...section,
      groups: [
        ...groups,
        {
          id: generateId("G"),
          title: `Group ${groups.length + 1}`,
          description: "",
          questions: [],
        },
      ],
    });
  };

  const handleRemoveGroup = (groupIndex) => {
    const groups = (section.groups || []).filter((_, index) => index !== groupIndex);
    onChange({ ...section, groups });
  };

  const handleGroupChange = (groupIndex, field, value) => {
    const groups = (section.groups || []).map((group, index) => {
      if (index !== groupIndex) return group;
      return { ...group, [field]: value };
    });

    onChange({ ...section, groups });
  };

  const handleAddGroupQuestion = (groupIndex) => {
    const groups = (section.groups || []).map((group, index) => {
      if (index !== groupIndex) return group;
      return {
        ...group,
        questions: [...(group.questions || []), createBaseQuestion()],
      };
    });

    onChange({ ...section, groups });
  };

  const handleRemoveGroupQuestion = (groupIndex, questionIndex) => {
    const groups = (section.groups || []).map((group, index) => {
      if (index !== groupIndex) return group;
      return {
        ...group,
        questions: (group.questions || []).filter((_, idx) => idx !== questionIndex),
      };
    });

    onChange({ ...section, groups });
  };

  const handleGroupQuestionChange = (groupIndex, questionIndex, fieldOrUpdater, value) => {
    const groups = (section.groups || []).map((group, index) => {
      if (index !== groupIndex) return group;
      return {
        ...group,
        questions: (group.questions || []).map((question, idx) => {
          if (idx !== questionIndex) return question;

          if (typeof fieldOrUpdater === "function") {
            const nextQuestion = fieldOrUpdater(question);
            return nextQuestion || question;
          }

          if (fieldOrUpdater && typeof fieldOrUpdater === "object") {
            return { ...question, ...fieldOrUpdater };
          }

          if (typeof fieldOrUpdater === "string") {
            return { ...question, [fieldOrUpdater]: value };
          }

          return question;
        }),
      };
    });

    onChange({ ...section, groups });
  };

  const renderOrderedItems = () => {
    const groupedQuestionIds = new Set();
    (section.groups || []).forEach((group) => {
      (group.questions || []).forEach((question) => {
        groupedQuestionIds.add(question.id);
      });
    });

    const standaloneQuestions = (section.questions || []).filter(
      (question) => !groupedQuestionIds.has(question.id)
    );
    const hasStandaloneQuestions = standaloneQuestions.length > 0;
    const hasGroups = (section.groups || []).length > 0;

    const defaultItems = [
      ...(hasStandaloneQuestions ? [{ type: "standalone" }] : []),
      ...(section.groups || []).map((_, index) => ({ type: "group", index })),
    ];

    const orderedItems = section.displayOrder && section.displayOrder.length
      ? section.displayOrder
      : defaultItems;

    if (!hasStandaloneQuestions && !hasGroups) {
      return (
        <div className="rounded-lg border border-dashed border-slate-300 bg-white p-6 text-center text-sm text-slate-500">
          Start by adding a question or group using the buttons below.
        </div>
      );
    }

    return orderedItems.map((item, orderIndex) => {
      if (item.type === "standalone") {
        return (
          <div key={`standalone-${orderIndex}`} className="space-y-4">
            {standaloneQuestions.map((question) => {
              const questionIndex = (section.questions || []).findIndex(
                (candidate) => candidate.id === question.id
              );
              if (questionIndex === -1) return null;

              return (
                <QuestionCard
                  key={question.id}
                  question={question}
                  questionNumber={questionIndex + 1}
                  numberingPrefix={questionIndex + 1}
                  onChange={(updates) => handleStandaloneQuestionChange(questionIndex, updates)}
                  sectionMeta={{ sectionKey: "custom", type: "standalone", questionIndex }}
                  renderActions={() => (
                    <button
                      type="button"
                      onClick={() => handleRemoveStandaloneQuestion(questionIndex)}
                      className="rounded border border-red-200 px-3 py-1 text-xs font-semibold text-red-600 hover:bg-red-50 hover:text-red-700"
                    >
                      Delete
                    </button>
                  )}
                />
              );
            })}
          </div>
        );
      }

      if (item.type === "group") {
        const group = section.groups?.[item.index];
        if (!group) {
          return null;
        }

        return (
          <div
            key={group.id || `group-${item.index}`}
            className="space-y-3 rounded-xl border border-orange-200 bg-orange-50 p-4"
          >
            <div className="flex items-center justify-between gap-2">
              <input
                type="text"
                value={group.title || ""}
                onChange={(event) => handleGroupChange(item.index, "title", event.target.value)}
                placeholder="Group title"
                className="flex-1 rounded border px-3 py-1 text-sm font-semibold text-slate-800 placeholder-slate-400 focus:border-orange-500 focus:outline-none"
              />
              <button
                type="button"
                onClick={() => handleRemoveGroup(item.index)}
                className="text-xs font-semibold text-rose-500 hover:text-rose-600"
              >
                Delete
              </button>
            </div>

            <textarea
              value={group.description || ""}
              onChange={(event) => handleGroupChange(item.index, "description", event.target.value)}
              placeholder="Group description (optional)"
              rows={2}
              className="w-full rounded border px-3 py-2 text-sm focus:border-orange-500 focus:outline-none"
            />

            <div className="space-y-3">
              {(group.questions || []).map((question, questionIndex) => (
                <QuestionCard
                  key={question.id}
                  question={question}
                  questionNumber={questionIndex + 1}
                  numberingPrefix={`${item.index + 1}.${questionIndex + 1}`}
                  onChange={(updates) =>
                    handleGroupQuestionChange(item.index, questionIndex, updates)
                  }
                  sectionMeta={{
                    sectionKey: "custom",
                    type: "group",
                    groupId: group.id,
                    groupIndex: item.index,
                    questionIndex,
                  }}
                  renderActions={() => (
                    <button
                      type="button"
                      onClick={() => handleRemoveGroupQuestion(item.index, questionIndex)}
                      className="rounded border border-red-200 px-2 py-1 text-xs font-semibold text-red-500 hover:bg-red-50"
                    >
                      Delete
                    </button>
                  )}
                />
              ))}

              <button
                type="button"
                onClick={() => handleAddGroupQuestion(item.index)}
                className="w-full px-4 py-2 text-sm font-medium text-orange-700 bg-orange-100 border border-orange-300 rounded-lg hover:bg-orange-200 transition"
              >
                + Add question to group
              </button>
            </div>
          </div>
        );
      }

      return null;
    });
  };

  return (
    <div className="w-full h-full overflow-auto bg-gray-50 p-6">
      <div className="mx-auto flex max-w-4xl flex-col gap-6">
        <div className="rounded-lg border border-gray-200 bg-white p-5 shadow-sm">
          <label className="mb-2 block text-sm font-semibold text-gray-700">
            Section Title
          </label>
          <input
            type="text"
            value={section.title || ""}
            onChange={handleTitleChange}
            placeholder="Enter section title"
            className="w-full rounded-md border border-gray-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-purple-500"
          />
        </div>

        <div className="rounded-lg border border-gray-200 bg-white p-5 shadow-sm">
          <label className="mb-2 block text-sm font-semibold text-gray-700">
            Instructions
          </label>
          <textarea
            value={section.instructions || ""}
            onChange={handleInstructionsChange}
            placeholder="Enter instructions for this section"
            rows={6}
            className="w-full rounded-md border border-gray-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-purple-500"
          />
        </div>

        <div className="rounded-lg border border-blue-200 bg-blue-50 p-4">
          <p className="text-sm text-blue-800">
            <strong>Note:</strong> Custom sections support standalone questions and grouped questions.
            Use the buttons below to start building your section.
          </p>
        </div>

        {renderOrderedItems()}

        <div className="flex gap-3">
          <button
            type="button"
            onClick={handleAddStandaloneQuestion}
            className="flex-1 rounded-lg border border-purple-200 bg-purple-50 px-4 py-3 text-sm font-semibold text-purple-700 hover:bg-purple-100 transition"
          >
            + Add question
          </button>
          <button
            type="button"
            onClick={handleAddGroup}
            className="flex-1 rounded-lg border border-orange-200 bg-orange-50 px-4 py-3 text-sm font-semibold text-orange-700 hover:bg-orange-100 transition"
          >
            + Add group
          </button>
        </div>
      </div>
    </div>
  );
}

export default CustomSectionBuilder;
