import React, { useEffect, useRef, useState } from "react";

// True when this test was launched from the /booking flow (lead saved in localStorage,
// path 'test', not yet completed). Lets us send the student back to finish booking
// instead of the generic home screen — without touching the exam pipeline.
function bookingTestInFlight() {
  try {
    const s = JSON.parse(localStorage.getItem("wv_booking_lead") || "null");
    return !!(s && s.path === "test" && s.testStartedAt && !s.done);
  } catch (e) {
    return false;
  }
}

const ExamCompleteModal = ({ isOpen, submitStatus, ackStatus, audioUploadSkipped, onClose, onRetry }) => {
  const [fromBooking] = useState(bookingTestInFlight);
  const redirectedRef = useRef(false);

  // Auto-return to /booking once the submission is recorded (and the Portal sync,
  // if any, isn't still pending). One-shot via ref + no timer-clearing cleanup, so
  // re-render churn can't cancel it before it fires. (ackStatus is null in the
  // standalone placement test booking uses — it only matters in embedded mode.)
  useEffect(() => {
    if (redirectedRef.current) return;
    if (isOpen && fromBooking && submitStatus === "success" && ackStatus !== "pending") {
      redirectedRef.current = true;
      setTimeout(() => { window.location.assign("/booking"); }, 1200);
    }
  }, [isOpen, fromBooking, submitStatus, ackStatus]);

  if (!isOpen) return null;

  return (
    <div
      role="dialog"
      aria-hidden={!isOpen}
      className="fixed inset-0 z-modal flex items-center justify-center p-4 backdrop-blur-sm bg-black/40 transition-colors duration-300"
    >
      <div className="w-full max-w-lg rounded-2xl bg-white p-6 shadow-xl transform transition-all duration-300 opacity-100 scale-100 translate-y-0">

        {/* ── SUBMITTING state ── */}
        {submitStatus === 'submitting' && (
          <>
            <div className="flex items-center gap-4">
              <div className="flex h-[60px] w-[60px] items-center justify-center">
                <svg className="animate-spin h-10 w-10 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
                </svg>
              </div>
              <div className="flex-1">
                <h2 className="text-lg md:text-xl font-semibold text-slate-900">Đang nộp bài, vui lòng đừng đóng tab...</h2>
                <p className="mt-1 text-sm text-slate-500">Vui lòng không đóng tab này.</p>
              </div>
            </div>
          </>
        )}

        {/* ── SUCCESS state ── */}
        {submitStatus === 'success' && (
          <>
            <div className="flex items-center gap-4">
              <div className="flex h-[60px] w-[60px] items-center justify-center bg-transparent shadow-none">
                <img src="/assets/images/celebration_icon.png" alt="Chúc mừng" className="h-full w-full object-contain" loading="lazy" />
              </div>
              <div className="flex-1">
                <h2 className="text-lg md:text-xl font-semibold text-slate-900">Hoàn thành bài thi!</h2>
                <p className="mt-1 text-sm text-slate-600">Chúc mừng bạn đã nỗ lực hoàn thành xong bài thi.</p>
              </div>
            </div>

            <div className="mt-5 flex items-start gap-3">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 shrink-0 text-emerald-500 mt-1" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14" />
                <polyline points="22 4 12 14.01 9 11.01" />
              </svg>
              <div>
                <p className="text-sm text-slate-600">Bài làm của bạn đã được ghi nhận hệ thống. Kết quả chi tiết sẽ được trung tâm gửi thông báo qua Email hoặc Zalo.</p>
              </div>
            </div>

            {fromBooking && ackStatus !== 'pending' && (
              <div className="mt-3 flex items-start gap-2 rounded-md bg-orange-50 border border-orange-200 px-3 py-2">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 shrink-0 text-orange-500 mt-0.5 animate-spin" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
                </svg>
                <p className="text-xs text-orange-700">Đang đưa bạn trở lại trang đặt lịch tư vấn...</p>
              </div>
            )}

            {audioUploadSkipped && (
              <div className="mt-3 flex items-start gap-2 rounded-md bg-amber-50 border border-amber-200 px-3 py-2">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 shrink-0 text-amber-500 mt-0.5" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                </svg>
                <p className="text-xs text-amber-700">Phần ghi âm Speaking chưa được tải lên do kết nối mạng. Giáo viên sẽ liên hệ lại nếu cần.<br /><span className="text-amber-500">Speaking recordings could not be uploaded due to connection issues. Your teacher will follow up if needed.</span></p>
              </div>
            )}

            {ackStatus === 'pending' && (
              <div className="mt-3 flex items-start gap-2 rounded-md bg-blue-50 border border-blue-200 px-3 py-2">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 shrink-0 text-blue-500 mt-0.5 animate-spin" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
                </svg>
                <p className="text-xs text-blue-700">Đang đồng bộ kết quả với Portal, vui lòng đợi trong giây lát.<br /><span className="text-blue-500">Syncing your result with the Portal — please wait a moment before leaving.</span></p>
              </div>
            )}

            {ackStatus === 'timeout' && (
              <div className="mt-3 flex items-start gap-2 rounded-md bg-amber-50 border border-amber-200 px-3 py-2">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 shrink-0 text-amber-500 mt-0.5" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                </svg>
                <p className="text-xs text-amber-700">Bài làm đã được lưu, nhưng kết quả có thể chưa hiển thị trên Portal ngay. Giáo viên vẫn sẽ thấy điểm số của bạn.<br /><span className="text-amber-500">Your submission was saved, but the Portal may not display the result immediately. Your teacher will still see your score.</span></p>
              </div>
            )}

            <div className="mt-6 flex justify-end gap-3">
              <button
                onClick={fromBooking ? () => window.location.assign('/booking') : onClose}
                disabled={ackStatus === 'pending'}
                className="rounded-lg bg-emerald-500 px-6 py-2 text-sm font-semibold text-white transition hover:bg-emerald-600 focus:outline-none focus:ring-2 focus:ring-emerald-200 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {fromBooking ? 'Tiếp tục đặt lịch' : 'Về trang chủ'}
              </button>
            </div>
          </>
        )}

        {/* ── ERROR state ── */}
        {submitStatus === 'error' && (
          <>
            <div className="flex items-center gap-4">
              <div className="flex h-[60px] w-[60px] items-center justify-center text-4xl">
                &#9888;
              </div>
              <div className="flex-1">
                <h2 className="text-lg md:text-xl font-semibold text-red-700">Gửi bài thất bại!</h2>
                <p className="mt-1 text-sm text-slate-600">Bài thi chưa được gửi thành công. Câu trả lời đã được lưu tạm trên máy.</p>
              </div>
            </div>

            <div className="mt-4 rounded-lg bg-red-50 border border-red-200 p-4">
              <p className="text-sm font-semibold text-red-800">Đừng đóng tab này!</p>
              <p className="mt-1 text-sm text-red-700">Hệ thống sẽ tự động thử gửi lại. Bạn cũng có thể nhấn nút bên dưới để thử ngay.</p>
              <p className="mt-2 text-xs text-red-500">Your answers are saved locally. The system will auto-retry, or you can retry now.</p>
            </div>

            <div className="mt-6 flex justify-end gap-3">
              <button
                onClick={onRetry}
                className="rounded-lg bg-red-600 px-6 py-2 text-sm font-semibold text-white transition hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-red-200"
              >
                Thử gửi lại
              </button>
            </div>
          </>
        )}

      </div>
    </div>
  );
};

export default ExamCompleteModal;
