import { storage } from "../../../controller/firebase";
import { ref, uploadBytes, getDownloadURL } from "firebase/storage";

/**
 * Upload in-memory audio blobs (local object URLs) in speaking answers
 * to Firebase Storage, replacing raw blobs with persisted download URLs.
 *
 * @param {string} examCode
 * @param {object} answers
 * @returns {Promise<object>} answers with speaking blobs replaced by URLs
 */
export async function uploadSpeakingAudioBlobs(examCode, answers) {
  console.log("🔄 Starting audio upload for exam:", examCode);
  if (!answers) {
    console.log("❌ No answers provided");
    return answers;
  }
  const newAnswers = { ...answers };
  try {
    if (!newAnswers.speaking || typeof newAnswers.speaking !== "object") {
      console.log("❌ No speaking answers or not object");
      return newAnswers;
    }
    const entries = Object.entries(newAnswers.speaking);
    console.log("📝 Found speaking entries:", entries.length);
    const uploadPromises = entries.map(async ([partId, item]) => {
      console.log(`🔍 Checking part ${partId}:`, {
        hasBlob: !!item?.blob,
        mimeType: item?.mimeType,
      });
      if (!item) return;
      if (item?.blob && item?.mimeType) {
        console.log(`📤 Uploading blob for ${partId}`);
        const mimeParts = (item.mimeType || "").split("/");
        const ext = mimeParts[1] || "webm";
        const fileName = `${Date.now()}_${partId}.${ext}`;
        const path = `speaking/${examCode}/${fileName}`;
        const storageRefObj = ref(storage, path);
        await uploadBytes(storageRefObj, item.blob, {
          contentType: item.mimeType,
        });
        const url = await getDownloadURL(storageRefObj);
        console.log(`✅ Uploaded ${partId} to:`, url);
        newAnswers.speaking[partId] = {
          url,
          storagePath: path,
          mimeType: item.mimeType,
          createdAt: item.createdAt,
          duration: item.duration,
        };
      } else {
        console.log(`⏭️ Skipping ${partId} - no blob or mimeType`);
      }
    });
    await Promise.all(uploadPromises);
    console.log("🎉 All uploads completed");
  } catch (error) {
    console.error("❌ Failed to upload speaking blobs:", error);
  }
  return newAnswers;
}
