import React, { useMemo, useState } from "react";
import PassageContentEditor from "./PassageContentEditor";
import QuestionCard from "../Question/QuestionCard";
import { cloneDefaultOptions } from "../../../../utils/question/questionUtils";
import { getQuestionSlotCount } from "../../../../utils/question/questionMetrics";
import {
  DEFAULT_MATCHING_HEADING_TITLE,
  MATCHING_HEADINGS_DEFAULT_DESCRIPTION,
} from "../../../../utils/question/questionDefaults";
import { generateId } from "../../../../utils/question/idUtils";
import { getOrderedSections } from "../../../../utils/passageHelpers";
import { useNumbering } from "../../../../contexts/NumberingContext";
import { generateQuestionRangeTitle } from "../../../../utils/question/questionTitleGenerator";

const ensureArray = (value) => (Array.isArray(value) ? value : []);

const createBaseQuestion = () => ({
  id: generateId("RQ"),
  description: "",
  prompt: "",
  type: "fill-in-the-blanks",
  inputMode: "text",
  placeholder: "",
  options: cloneDefaultOptions(),
  correctAnswers: [],
  inlineTemplate: "",
  subQuestions: [],
  matchingHeadingListTitle: DEFAULT_MATCHING_HEADING_TITLE,
  matchingHeadingItems: ["", "", ""],
  matchingHeadingAnswers: ["", "", ""],
});

const createMatchingHeadingsQuestion = () => ({
  ...createBaseQuestion(),
  type: "matching-headings",
  description: MATCHING_HEADINGS_DEFAULT_DESCRIPTION,
  prompt: "Questions 1-3",
  options: [],
  correctAnswers: ["", "", ""],
});

const createTrueFalseNotGivenQuestion = () => ({
  ...createBaseQuestion(),
  type: "true-false-not-given",
  description: "Do the following statements agree with the information given in the Reading Passage?",
  prompt: "Questions 1-5",
  options: [],
  useTableView: true,
  hint: "TRUE - if the statement agrees with the information\nFALSE - if the statement contradicts the information\nNOT GIVEN - if there is no information on this.",
  subQuestions: [
    { id: generateId("SQ"), prompt: "", correctAnswers: [""] },
  ],
  correctAnswers: [""],
});

const createPassage = (index) => ({
  id: generateId("P"),
  title: `Passage ${index + 1}`,
  content: [],
  questions: [],
  imageUrl: "",
  imagePosition: "above",
  instructionGroups: [],
});

const shiftGroupsAfterInsertion = (groups, insertedIndex, attachGroupIndex = null) => {
  const insertedPosition = insertedIndex + 1;
  return ensureArray(groups).map((group, index) => {
    const start = Number(group.startIndex) || 1;
    const end = Number(group.endIndex) || start;

    if (index === attachGroupIndex) {
      if (insertedPosition < start) {
        return {
          ...group,
          startIndex: start + 1,
          endIndex: end + 1,
        };
      }
      return {
        ...group,
        startIndex: Math.min(start, insertedPosition),
        endIndex: end + 1,
      };
    }

    if (insertedPosition <= start) {
      return {
        ...group,
        startIndex: start + 1,
        endIndex: end + 1,
      };
    }

    if (insertedPosition <= end) {
      return {
        ...group,
        endIndex: end + 1,
      };
    }

    return group;
  });
};

const shiftGroupsAfterRemoval = (groups, removedIndex) => {
  const removedPosition = removedIndex + 1;
  return ensureArray(groups)
    .map((group) => {
      const start = Number(group.startIndex) || 1;
      const end = Number(group.endIndex) || start;

      if (removedPosition < start) {
        return {
          ...group,
          startIndex: Math.max(1, start - 1),
          endIndex: Math.max(1, end - 1),
        };
      }

      if (removedPosition >= start && removedPosition <= end) {
        return {
          ...group,
          endIndex: Math.max(start, end - 1),
        };
      }

      return group;
    })
    .filter((group) => {
      const start = Number(group.startIndex) || 1;
      const end = Number(group.endIndex) || start;
      return end >= start;
    });
};

const findGroupIndex = (groups, questionNumber) =>
  ensureArray(groups).findIndex((group) => {
    const start = Number(group.startIndex) || 1;
    const end = Number(group.endIndex) || start;
    return questionNumber >= start && questionNumber <= end;
  });

function ReadingBuilder({ data, onChange, focusRequest }) {
  const { getQuestionNumber } = useNumbering();
  const [activePassageIndex, setActivePassageIndex] = useState(0);

  // Handle external focus requests (e.g. from Sidebar)
  React.useEffect(() => {
    if (focusRequest && typeof focusRequest.passageIndex === "number") {
      console.log("📍 ReadingBuilder switching tab to passage:", focusRequest.passageIndex);
      setActivePassageIndex(focusRequest.passageIndex);
    }
  }, [focusRequest]);


  const reading = useMemo(
    () => ({
      title: "",
      instructions: "",
      timeAllotted: "",
      passages: [],
      ...data,
    }),
    [data]
  );

  const updateReading = (updates) => {
    onChange({
      ...reading,
      ...updates,
    });
  };

  const updatePassages = (updater) => {
    const current = ensureArray(reading.passages);
    const next = typeof updater === "function" ? updater(current) : updater;
    updateReading({ passages: next });
  };

  const handlePassageChange = (passageIndex, updates) => {
    updatePassages((passages) =>
      passages.map((passage, idx) => {
        if (idx !== passageIndex) return passage;
        if (typeof updates === "function") {
          return updates(passage) || passage;
        }
        return { ...passage, ...updates };
      })
    );
  };

  const handleQuestionChange = (passageIndex, questionIndex, updates) => {
    handlePassageChange(passageIndex, (passage) => {
      const questions = ensureArray(passage.questions);
      const nextQuestions = questions.map((question, idx) => {
        if (idx !== questionIndex) return question;
        if (typeof updates === "function") {
          return updates(question) || question;
        }
        return { ...question, ...updates };
      });

      return { ...passage, questions: nextQuestions };
    });
  };

  const handleAddQuestion = (
    passageIndex,
    {
      attachToGroup = null,
      questionFactory = createBaseQuestion,
      insertAt,
    } = {}
  ) => {
    handlePassageChange(passageIndex, (passage) => {
      const questions = ensureArray(passage.questions);
      const insertionIndexRaw =
        typeof insertAt === "function"
          ? insertAt({ passage, questions })
          : typeof insertAt === "number"
            ? insertAt
            : questions.length;
      const insertionIndex = Math.min(Math.max(insertionIndexRaw, 0), questions.length);

      const nextQuestions = [
        ...questions.slice(0, insertionIndex),
        questionFactory(),
        ...questions.slice(insertionIndex),
      ];

      const nextGroups = shiftGroupsAfterInsertion(
        passage.instructionGroups,
        insertionIndex,
        attachToGroup
      );

      return {
        ...passage,
        questions: nextQuestions,
        instructionGroups: nextGroups,
      };
    });
  };

  const handleDuplicateQuestion = (passageIndex, questionIndex) => {
    handlePassageChange(passageIndex, (passage) => {
      const questions = ensureArray(passage.questions);
      const source = questions[questionIndex];
      if (!source) return passage;

      const clonedQuestion = {
        ...source,
        id: generateId("RQ"),
        subQuestions: Array.isArray(source.subQuestions)
          ? source.subQuestions.map((sub) => ({
            ...sub,
            id: generateId("SQ"),
          }))
          : [],
      };

      const insertIndex = questionIndex + 1;
      const nextQuestions = [
        ...questions.slice(0, insertIndex),
        clonedQuestion,
        ...questions.slice(insertIndex),
      ];

      const attachGroup = findGroupIndex(passage.instructionGroups, questionIndex + 1);
      const nextGroups = shiftGroupsAfterInsertion(
        passage.instructionGroups,
        insertIndex,
        attachGroup >= 0 ? attachGroup : null
      );

      return {
        ...passage,
        questions: nextQuestions,
        instructionGroups: nextGroups,
      };
    });
  };

  const handleRemoveQuestion = (passageIndex, questionIndex) => {
    handlePassageChange(passageIndex, (passage) => {
      const questions = ensureArray(passage.questions);
      const nextQuestions = questions.filter((_, idx) => idx !== questionIndex);
      const nextGroups = shiftGroupsAfterRemoval(
        passage.instructionGroups,
        questionIndex
      );

      return {
        ...passage,
        questions: nextQuestions,
        instructionGroups: nextGroups,
      };
    });
  };

  const handleAddPassage = () => {
    updatePassages((passages) => [...passages, createPassage(passages.length)]);
  };

  const handleRemovePassage = (passageIndex) => {
    updatePassages((passages) => passages.filter((_, idx) => idx !== passageIndex));
    // Reset active passage index if needed
    if (activePassageIndex >= passageIndex) {
      setActivePassageIndex(Math.max(0, activePassageIndex - 1));
    }
  };

  const handleImageSelect = (file, passageIndex) => {
    if (!file) return;
    handlePassageChange(passageIndex, {
      imageFile: file,
      imageUrl: typeof URL !== "undefined" ? URL.createObjectURL(file) : "",
    });
  };

  const handleAddInstructionGroup = (passageIndex) => {
    handlePassageChange(passageIndex, (passage) => {
      const groups = ensureArray(passage.instructionGroups);
      const questions = ensureArray(passage.questions);
      const lastGroup = groups[groups.length - 1];
      const base = lastGroup
        ? Number(lastGroup.endIndex ?? lastGroup.startIndex ?? questions.length)
        : questions.length;
      const startIndex = Math.max(1, base + 1);

      return {
        ...passage,
        questions: [...questions, createMatchingHeadingsQuestion()],
        instructionGroups: [
          ...groups,
          {
            id: generateId("RG"),
            title: "",
            startIndex,
            endIndex: startIndex,
          },
        ],
      };
    });
  };

  const handleAddQuestionToGroup = (passageIndex, groupIndex) => {
    handleAddQuestion(passageIndex, {
      attachToGroup: groupIndex,
      questionFactory: createMatchingHeadingsQuestion,
      insertAt: ({ passage, questions }) => {
        const group = ensureArray(passage.instructionGroups)[groupIndex];
        if (!group) return questions.length;
        const end = Number(group.endIndex) || Number(group.startIndex) || questions.length;
        return Math.min(Math.max(end, 0), questions.length);
      },
    });
  };

  const handleInstructionGroupChange = (passageIndex, groupIndex, updates) => {
    handlePassageChange(passageIndex, (passage) => {
      const groups = ensureArray(passage.instructionGroups).map((group, idx) =>
        idx === groupIndex ? { ...group, ...updates } : group
      );
      return { ...passage, instructionGroups: groups };
    });
  };

  const handleRemoveInstructionGroup = (passageIndex, groupIndex) => {
    handlePassageChange(passageIndex, (passage) => {
      const groups = ensureArray(passage.instructionGroups).filter(
        (_, idx) => idx !== groupIndex
      );
      return { ...passage, instructionGroups: groups };
    });
  };

  const questionOffsets = useMemo(() => {
    const offsets = [];
    let running = 0;
    ensureArray(reading.passages).forEach((passage) => {
      offsets.push(running);
      const passageTotal = ensureArray(passage.questions).reduce((sum, question) => {
        return sum + getQuestionSlotCount(question);
      }, 0);
      running += passageTotal;
    });
    return offsets;
  }, [reading.passages]);

  return (
    <div className="space-y-10">
      <div className="grid gap-6 md:grid-cols-3">
        <div>
          <label className="text-xs font-semibold uppercase tracking-wide text-slate-500">
            Reading title
          </label>
          <input
            type="text"
            value={reading.title}
            onChange={(event) => updateReading({ title: event.target.value })}
            className="mt-1 w-full rounded-xl border border-slate-200 px-4 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
            placeholder="IELTS Reading Test 1"
          />
        </div>
        <div>
          <label className="text-xs font-semibold uppercase tracking-wide text-slate-500">
            Instructions
          </label>
          <textarea
            value={reading.instructions}
            onChange={(event) => updateReading({ instructions: event.target.value })}
            rows={4}
            className="mt-1 w-full rounded-xl border border-slate-200 px-4 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
            placeholder="Provide guidance for candidates completing the reading section."
          />
        </div>
        <div>
          <label className="text-xs font-semibold uppercase tracking-wide text-slate-500">
            Time allotted
          </label>
          <input
            type="text"
            value={reading.timeAllotted || ""}
            onChange={(event) => updateReading({ timeAllotted: event.target.value })}
            className="mt-1 w-full rounded-xl border border-slate-200 px-4 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
            placeholder="e.g., 25 minutes"
          />
        </div>
      </div>

      <div className="flex items-center justify-between">
        <h3 className="text-lg font-semibold text-slate-900">Passages</h3>
        <button
          type="button"
          onClick={handleAddPassage}
          className="rounded-lg border border-blue-200 px-3 py-1.5 text-sm font-medium text-blue-700 transition hover:bg-blue-50"
        >
          + Add passage
        </button>
      </div>

      {/* Passages Tab Interface */}
      <div className="space-y-4">
        {/* Tab Headers */}
        <div className="flex items-center gap-2 border-b border-slate-200 overflow-x-auto">
          {ensureArray(reading.passages).map((passage, passageIndex) => (
            <button
              key={passage.id}
              onClick={() => setActivePassageIndex(passageIndex)}
              className={`px-4 py-2 text-sm font-medium transition border-b-2 whitespace-nowrap ${activePassageIndex === passageIndex
                ? "border-orange-500 text-orange-500 bg-blue-50"
                : "border-transparent text-slate-600 hover:text-slate-900"
                }`}
            >
              Passage {passageIndex + 1}
            </button>
          ))}
        </div>

        {/* Tab Content */}
        {ensureArray(reading.passages).map((passage, passageIndex) => {
          const isActive = activePassageIndex === passageIndex;

          const questions = ensureArray(passage.questions);
          const passageOffset = questionOffsets[passageIndex] || 0;
          const sections = getOrderedSections(passage, passageIndex);

          return (
            <div
              key={passage.id}
              className={`space-y-4 rounded-2xl border border-slate-200 bg-slate-50 p-5 ${isActive ? "" : "hidden"}`}
            >
              <div className="flex items-start justify-end gap-3">
                <button
                  type="button"
                  onClick={() => handleRemovePassage(passageIndex)}
                  className="text-xs font-semibold text-rose-500 hover:text-rose-600"
                >
                  Remove passage
                </button>
              </div>

              <div className="flex-1 space-y-3">
                <div className="flex items-center gap-3">
                  <input
                    type="text"
                    value={passage.title || ""}
                    onChange={(event) =>
                      handlePassageChange(passageIndex, {
                        title: event.target.value,
                      })
                    }
                    className="flex-1 rounded-xl border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-800 focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100 text-center"
                    placeholder={`Passage ${passageIndex + 1}`}
                  />
                  <div className="flex items-center gap-2">
                    <input
                      type="file"
                      id={`reading-passage-image-${passageIndex}`}
                      accept="image/*"
                      onChange={(event) =>
                        handleImageSelect(event.target.files?.[0], passageIndex)
                      }
                      className="hidden"
                    />
                    <label
                      htmlFor={`reading-passage-image-${passageIndex}`}
                      className={`inline-flex items-center gap-2 rounded-lg border px-3 py-1.5 text-sm font-medium transition ${passage.imageUrl
                        ? "border-green-200 text-green-700 hover:bg-green-50"
                        : "border-blue-200 text-blue-700 hover:bg-blue-50"
                        }`}
                    >
                      {passage.imageUrl ? "Change image" : "Add image"}
                    </label>
                    {passage.imageUrl ? (
                      <button
                        type="button"
                        onClick={() =>
                          handlePassageChange(passageIndex, {
                            imageUrl: "",
                            imageFile: null,
                          })
                        }
                        className="text-xs font-medium text-rose-500 hover:text-rose-600"
                      >
                        Remove
                      </button>
                    ) : null}
                  </div>
                </div>

                {passage.imageUrl ? (
                  <div className="flex flex-col items-center gap-2 rounded-lg border border-slate-200 bg-white p-3">
                    <img
                      src={passage.imageUrl}
                      alt={`${passage.title || `Passage ${passageIndex + 1}`
                        } illustration`}
                      className="max-h-56 w-full rounded object-contain"
                    />
                    <div className="flex items-center gap-2">
                      <button
                        type="button"
                        onClick={() =>
                          handlePassageChange(passageIndex, {
                            imagePosition: "above",
                          })
                        }
                        className={`rounded border px-2 py-1 text-xs ${passage.imagePosition !== "below"
                          ? "border-blue-300 bg-blue-100 text-blue-700"
                          : "border-slate-200 bg-white text-slate-600"
                          }`}
                      >
                        Place above text
                      </button>
                      <button
                        type="button"
                        onClick={() =>
                          handlePassageChange(passageIndex, {
                            imagePosition: "below",
                          })
                        }
                        className={`rounded border px-2 py-1 text-xs ${passage.imagePosition === "below"
                          ? "border-blue-300 bg-blue-100 text-blue-700"
                          : "border-slate-200 bg-white text-slate-600"
                          }`}
                      >
                        Place below text
                      </button>
                    </div>
                  </div>
                ) : null}

                <PassageContentEditor
                  passage={passage}
                  passageIndex={passageIndex}
                  onChange={handlePassageChange}
                />
              </div>

              <div className="space-y-4">
                {sections.map((section) => {
                  if (section.type === "group") {
                    const { group, groupIndex } = section;
                    if (!group) return null;
                    const start = Math.max(1, Number(group.startIndex) || 1);
                    const end = Math.max(
                      start,
                      Number(group.endIndex) || start
                    );
                    const groupQuestionIndices = questions
                      .map((_, idx) => idx)
                      .filter((idx) => {
                        const questionNumber = idx + 1;
                        return questionNumber >= start && questionNumber <= end;
                      });

                    return (
                      <div
                        key={group.id || `group-${passageIndex}-${groupIndex}`}
                        className="space-y-3 rounded-xl border border-orange-200 bg-orange-50 p-4"
                      >
                        <div className="flex items-center justify-between">
                          <div className="flex flex-1 flex-col gap-1">
                            <input
                              type="text"
                              value={group.title || ""}
                              onChange={(event) =>
                                handleInstructionGroupChange(
                                  passageIndex,
                                  groupIndex,
                                  {
                                    title: event.target.value,
                                  }
                                )
                              }
                              placeholder="Group instruction title"
                              className="rounded border border-orange-200 bg-white px-3 py-1.5 text-sm font-semibold text-orange-700 focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
                            />
                            {groupQuestionIndices.length > 0 && (
                              <p className="text-[11px] uppercase tracking-wide text-orange-600">
                                {(() => {
                                  const firstIdx = groupQuestionIndices[0];
                                  const lastIdx = groupQuestionIndices[groupQuestionIndices.length - 1];
                                  const firstQ = questions[firstIdx];
                                  const lastQ = questions[lastIdx];
                                  const startNum = getQuestionNumber("reading", passage.id, firstQ?.id);
                                  const endNum = getQuestionNumber("reading", passage.id, lastQ?.id);

                                  // Parse range if it's a string like "1-5"
                                  let start = startNum;
                                  let end = endNum;
                                  if (typeof startNum === "string" && startNum.includes("-")) {
                                    const parts = startNum.split("-");
                                    start = parseInt(parts[0]) || 1;
                                  } else {
                                    start = parseInt(startNum) || 1;
                                  }

                                  if (typeof endNum === "string" && endNum.includes("-")) {
                                    const parts = endNum.split("-");
                                    end = parseInt(parts[parts.length - 1]) || 1;
                                  } else {
                                    end = parseInt(endNum) || start;
                                  }

                                  return `Covers questions ${start} - ${end}`;
                                })()}
                              </p>
                            )}
                          </div>
                          <div className="flex items-center gap-2">
                            <button
                              type="button"
                              onClick={() =>
                                handleAddQuestionToGroup(
                                  passageIndex,
                                  groupIndex
                                )
                              }
                              className="rounded border border-blue-200 bg-white px-3 py-1 text-xs font-semibold text-blue-600 hover:bg-blue-50"
                            >
                              + Add question to group
                            </button>
                            <button
                              type="button"
                              onClick={() =>
                                handleRemoveInstructionGroup(
                                  passageIndex,
                                  groupIndex
                                )
                              }
                              className="text-xs font-semibold text-rose-500 hover:text-rose-600"
                            >
                              Remove group
                            </button>
                          </div>
                        </div>

                        <div className="space-y-3">
                          {groupQuestionIndices.map((questionIndex) => {
                            const question = questions[questionIndex];
                            if (!question) return null;

                            // Get question number from global numbering context
                            const questionNumber = getQuestionNumber("reading", passage.id, question.id);

                            return (
                              <QuestionCard
                                key={question.id || `question-${questionIndex}`}
                                question={question}
                                questionNumber={questionNumber}
                                numberingPrefix={questionNumber}
                                sectionMeta={{
                                  sectionKey: "reading",
                                  passageId: passage.id,
                                  passageIndex,
                                  groupId: group.id,
                                  groupIndex,
                                  questionIndex,
                                }}
                                onChange={(updates) =>
                                  handleQuestionChange(
                                    passageIndex,
                                    questionIndex,
                                    updates
                                  )
                                }
                                renderActions={() => (
                                  <div className="flex items-center gap-2">
                                    <button
                                      type="button"
                                      onClick={() =>
                                        handleDuplicateQuestion(
                                          passageIndex,
                                          questionIndex
                                        )
                                      }
                                      className="rounded border border-blue-200 px-3 py-1 text-xs font-semibold text-blue-600 hover:bg-blue-50"
                                    >
                                      Duplicate
                                    </button>
                                    <button
                                      type="button"
                                      onClick={() =>
                                        handleRemoveQuestion(
                                          passageIndex,
                                          questionIndex
                                        )
                                      }
                                      className="rounded border border-red-200 px-3 py-1 text-xs font-semibold text-red-600 hover:bg-red-50"
                                    >
                                      Delete
                                    </button>
                                  </div>
                                )}
                              />
                            );
                          })}
                        </div>
                      </div>
                    );
                  }

                  if (section.type === "ungrouped") {
                    const groupedSet =
                      section.groupedQuestionIndices || new Set();
                    const ungroupedQuestions = questions
                      .map((question, idx) => ({ question, idx }))
                      .filter(({ idx }) => !groupedSet.has(idx));

                    if (!ungroupedQuestions.length) {
                      return null;
                    }

                    return (
                      <div
                        key={section.id}
                        className="space-y-3 rounded-xl border border-slate-200 bg-white p-4"
                      >
                        <div className="flex items-center justify-between">
                          <p className="text-sm font-semibold text-slate-700">
                            Questions Builder
                          </p>
                          <button
                            type="button"
                            onClick={() => handleAddQuestion(passageIndex)}
                            className="rounded border border-blue-200 px-3 py-1 text-xs font-semibold text-blue-600 hover:bg-blue-50"
                          >
                            + Add question
                          </button>
                        </div>

                        <div className="space-y-3">
                          {ungroupedQuestions.map(({ question, idx }) => {
                            // Get question number from global numbering context
                            const questionNumber = getQuestionNumber("reading", passage.id, question.id);
                            return (
                              <QuestionCard
                                key={question.id || `question-${idx}`}
                                question={question}
                                questionNumber={questionNumber}
                                numberingPrefix={questionNumber}
                                sectionMeta={{
                                  sectionKey: "reading",
                                  passageId: passage.id,
                                  passageIndex,
                                  groupId: null,
                                  groupIndex: null,
                                  questionIndex: idx,
                                }}
                                onChange={(updates) =>
                                  handleQuestionChange(
                                    passageIndex,
                                    idx,
                                    updates
                                  )
                                }
                                renderActions={() => (
                                  <div className="flex items-center gap-2">
                                    <button
                                      type="button"
                                      onClick={() =>
                                        handleDuplicateQuestion(
                                          passageIndex,
                                          idx
                                        )
                                      }
                                      className="rounded border border-blue-200 px-3 py-1 text-xs font-semibold text-blue-600 hover:bg-blue-50"
                                    >
                                      Duplicate
                                    </button>
                                    <button
                                      type="button"
                                      onClick={() =>
                                        handleRemoveQuestion(passageIndex, idx)
                                      }
                                      className="rounded border border-red-200 px-3 py-1 text-xs font-semibold text-red-600 hover:bg-red-50"
                                    >
                                      Delete
                                    </button>
                                  </div>
                                )}
                              />
                            );
                          })}
                        </div>
                      </div>
                    );
                  }

                  return null;
                })}
              </div>

              <div className="flex items-center gap-2">
                <button
                  type="button"
                  onClick={() => handleAddQuestion(passageIndex)}
                  className="rounded-lg border border-blue-200 px-3 py-1.5 text-sm font-medium text-blue-700 transition hover:bg-blue-50"
                >
                  + Add question
                </button>
                <button
                  type="button"
                  onClick={() => handleAddInstructionGroup(passageIndex)}
                  className="rounded-lg border border-green-200 px-3 py-1.5 text-sm font-medium text-green-700 transition hover:bg-green-50"
                >
                  + Add group
                </button>
              </div>
            </div>
          );
        })}

        {ensureArray(reading.passages).length === 0 ? (
          <div className="rounded-xl border border-dashed border-slate-300 bg-white p-6 text-center text-sm text-slate-500">
            Add a passage to start building the reading section.
          </div>
        ) : null}
      </div>
    </div>
  );
}

export default ReadingBuilder;
