import React, { useMemo, useState, useCallback, useContext } from "react";
import { parseGapContent } from "../../../utils/question/gapFilling";
import { ensureGapFillTable, synchronizeGapFillTableQuestion } from "../../../utils/question/gapFillTable";
import RegradeContext from "../../../contexts/RegradeContext";
import AnswerKeyEditor from "../_shared/AnswerKeyEditor";
import { normalizeAnswer, matchesAnswer } from "../../../utils/normalizeAnswer";

const parseInteger = (value) => {
  const parsed = Number.parseInt(value, 10);
  return Number.isFinite(parsed) ? parsed : null;
};

const parseQuestionNumberRange = (questionNumber) => {
  if (!questionNumber) {
    return { start: null, end: null };
  }

  const matches = String(questionNumber)
    .match(/\d+/g)
    ?.map((value) => Number.parseInt(value, 10))
    .filter((value) => Number.isFinite(value));

  if (!matches || matches.length === 0) {
    return { start: null, end: null };
  }

  const [first, second] = matches;

  if (matches.length >= 2 && Number.isFinite(second) && second >= first) {
    return { start: first, end: second };
  }

  return { start: first ?? null, end: null };
};

const GapFillTablePreview = ({
  question,
  value,
  onChange,
  disabled = false,
  reviewMode = false,
  correctAnswers = [],
  name,
  questionNumber = 1,
  sectionKey = '',
  // === NEW: Edit Mode Props ===
  editMode = false,
  onQuestionChange,
  onOpenSpreadsheet,
}) => {

  const { start: rangeStart } = useMemo(
    () => parseQuestionNumberRange(questionNumber),
    [questionNumber]
  );
  const hasGlobalRange = Number.isFinite(rangeStart);

  const tablePlan = useMemo(() => {
    const ensured = ensureGapFillTable(question?.table);
    const descriptors = [];
    const rows = ensured.rows.map((row, rowIndex) => {
      const cells = row.cells
        .filter((cell) => !cell.isSpanned)
        .map((cell, cellIndex) => {
          const content = cell.content || "";
          const { normalizedContent, placeholders } = parseGapContent(content);
          const descriptorIndices = placeholders.map((placeholder) => {
            const descriptorIndex = descriptors.length;
            descriptors.push({
              rowIndex,
              cellIndex,
              placeholder,
              rowId: row.id,
              cellId: cell.id,
            });
            return descriptorIndex;
          });
          const parts = normalizedContent.split(/(__GAP_\d+__)/);
          return {
            id: cell.id,
            parts,
            descriptorIndices,
            originalContent: content, // Keep original content for edit mode
            colSpan: Number.isInteger(cell.colSpan) && cell.colSpan > 1 ? cell.colSpan : 1,
            rowSpan: Number.isInteger(cell.rowSpan) && cell.rowSpan > 1 ? cell.rowSpan : 1,
          };
        });
      return {
        id: row.id,
        type: row.type === "header" ? "header" : "body",
        noBorderBottom: row.noBorderBottom === true,
        cells,
      };
    });

    return {
      caption: ensured.caption,
      rows,
      descriptors,
    };
  }, [question?.table]);

  const baseSubQuestions = useMemo(() => Array.isArray(question?.subQuestions)
    ? question.subQuestions
    : [], [question?.subQuestions]);
  const baseCorrectAnswers = useMemo(() => Array.isArray(question?.correctAnswers)
    ? question.correctAnswers
    : [], [question?.correctAnswers]);
  const supplementalCorrectAnswers = useMemo(() => Array.isArray(correctAnswers)
    ? correctAnswers
    : [], [correctAnswers]);

  const gapCount = useMemo(
    () =>
      Math.max(
        tablePlan.descriptors.length,
        baseSubQuestions.length,
        baseCorrectAnswers.length,
        supplementalCorrectAnswers.length
      ),
    [
      tablePlan.descriptors.length,
      baseSubQuestions.length,
      baseCorrectAnswers.length,
      supplementalCorrectAnswers.length,
    ]
  );

  const normalizedUserAnswers = useMemo(() => {
    const answers = Array.isArray(value) ? value.slice() : [];
    if (answers.length > gapCount) {
      answers.length = gapCount;
    }
    while (answers.length < gapCount) {
      answers.push("");
    }
    return answers;
  }, [value, gapCount]);

  const previewCorrectAnswers = useMemo(
    () =>
      Array.from({ length: gapCount }).map((_, index) => {
        if (supplementalCorrectAnswers[index] !== undefined) {
          return supplementalCorrectAnswers[index];
        }
        if (baseCorrectAnswers[index] !== undefined) {
          return baseCorrectAnswers[index];
        }
        const subQuestion = baseSubQuestions[index];
        if (subQuestion?.correctAnswers?.length) {
          return subQuestion.correctAnswers[0];
        }
        return "";
      }),
    [supplementalCorrectAnswers, baseCorrectAnswers, baseSubQuestions, gapCount]
  );

  const gapDescriptors = useMemo(
    () =>
      Array.from({ length: gapCount }).map((_, index) => {
        const descriptor = tablePlan.descriptors[index];
        const placeholder = descriptor?.placeholder;
        const subQuestion = baseSubQuestions[index];
        const explicitNumber = parseInteger(subQuestion?.gapIndex);
        const fallbackNumber = parseInteger(placeholder?.number);
        const globalNumber = hasGlobalRange ? rangeStart + index : null;

        let displayNumber = globalNumber;
        if (!Number.isFinite(displayNumber)) {
          if (Number.isFinite(explicitNumber)) {
            displayNumber = explicitNumber;
          } else if (Number.isFinite(fallbackNumber)) {
            displayNumber = fallbackNumber;
          } else {
            displayNumber = index + 1;
          }
        }
        return {
          ...descriptor,
          displayNumber,
          slotIndex: index,
          slotId: subQuestion?.id || placeholder?.token || `gap-${index}`,
        };
      }),
    [tablePlan.descriptors, baseSubQuestions, gapCount, hasGlobalRange, rangeStart]
  );

  // === MUST be before any returns ===
  const placeholders = useMemo(() => {
    const ensured = ensureGapFillTable(question?.table);
    const result = [];
    ensured.rows.forEach((row, rowIndex) => {
      row.cells.forEach((cell, cellIndex) => {
        const content = cell.content || '';
        const matches = content.matchAll(/__(\d+)__|_+/g);
        for (const match of matches) {
          const number = match[1] ? parseInt(match[1], 10) : result.length + 1;
          result.push({
            rowIndex,
            cellIndex,
            number,
            rowId: row.id,
            cellId: cell.id,
          });
        }
      });
    });
    return result;
  }, [question?.table]);

  const normalizedAnswersForEdit = useMemo(() => {
    const answers = Array.isArray(question?.correctAnswers) ? question.correctAnswers.slice() : [];
    const targetLength = Math.max(gapCount, placeholders.length);
    while (answers.length < targetLength) answers.push('');
    return answers;
  }, [question?.correctAnswers, gapCount, placeholders.length]);

  const isInteractive = typeof onChange === "function";
  const { isRegrade, setKeyEdit } = useContext(RegradeContext);

  const handleAnswerChange = (answerIndex, answer) => {
    if (!isInteractive || disabled || (reviewMode)) return;
    const nextAnswers = normalizedUserAnswers.slice();
    nextAnswers[answerIndex] = answer;
    onChange(nextAnswers);
  };

  // === EDIT MODE: Cell content change handler ===
  const handleCellEdit = useCallback((rowId, cellId, newContent) => {
    if (!editMode || !onQuestionChange) return;

    const ensured = ensureGapFillTable(question?.table);
    const nextTable = {
      ...ensured,
      rows: ensured.rows.map(row => {
        if (row.id !== rowId) return row;
        return {
          ...row,
          cells: row.cells.map(cell => {
            if (cell.id !== cellId) return cell;
            return { ...cell, content: newContent };
          }),
        };
      }),
    };

    onQuestionChange(prev => synchronizeGapFillTableQuestion(
      { ...prev, table: nextTable },
      { table: nextTable }
    ));
  }, [editMode, onQuestionChange, question?.table]);

  // === EDIT MODE: Correct answer change handler ===
  const handleCorrectAnswerChange = useCallback((index, newValue) => {
    if (!editMode || !onQuestionChange) return;

    onQuestionChange(prev => {
      const synchronized = synchronizeGapFillTableQuestion(prev);
      const nextAnswers = Array.isArray(synchronized.correctAnswers)
        ? synchronized.correctAnswers.slice()
        : [];
      if (index >= 0 && index < nextAnswers.length) {
        nextAnswers[index] = newValue;
      }
      const nextSubQuestions = Array.isArray(synchronized.subQuestions)
        ? synchronized.subQuestions.map((sub, subIndex) => ({
          ...sub,
          correctAnswers: [nextAnswers[subIndex] || ""],
        }))
        : [];
      return {
        ...synchronized,
        correctAnswers: nextAnswers,
        subQuestions: nextSubQuestions,
      };
    });
  }, [editMode, onQuestionChange]);

  if (!question) {
    return null;
  }

  // Modified empty state for edit mode
  if (gapCount === 0 && !editMode) {
    return (
      <div className="rounded border border-dashed border-slate-300 bg-slate-50 px-3 py-2 text-sm text-slate-500">
        Add blanks to the table cells to preview this question.
      </div>
    );
  }

  const renderCellContent = (cellPlan) => {
    let cursor = 0;
    return cellPlan.parts.map((part, index) => {
      const match = part.match(/__GAP_(\d+)__/);
      if (match) {
        const descriptorIndex = cellPlan.descriptorIndices[cursor] ?? parseInt(match[1], 10);
        cursor += 1;
        const cappedFallbackNumber = hasGlobalRange
          ? rangeStart + descriptorIndex
          : descriptorIndex + 1;

        const descriptor = gapDescriptors[descriptorIndex] || {
          slotIndex: descriptorIndex,
          displayNumber: cappedFallbackNumber,
          slotId: `gap-${descriptorIndex}`,
        };
        const answerIndex = descriptor.slotIndex ?? descriptorIndex;
        const answerNumber = descriptor.displayNumber;
        const userAnswer = normalizedUserAnswers[answerIndex] || "";
        const normalizedUserAnswer = normalizeAnswer(userAnswer);
        const rawCorrectAnswer = previewCorrectAnswers[answerIndex];

        // Use the shared matcher so the review-mode green/red painting matches
        // exactly what examScoring.js (and the CF grader) accept. This handles
        // "/" and "|" separators AND bracket expansion — previously this
        // component only split on "|", so keys like "decoration / decorations"
        // or "(£) 115 / a/one hundred (and) fifteen" silently failed.
        const isCorrectState = reviewMode
          ? matchesAnswer(userAnswer, rawCorrectAnswer)
          : false;
        const isIncorrectState =
          reviewMode &&
          rawCorrectAnswer !== undefined &&
          rawCorrectAnswer !== null &&
          rawCorrectAnswer !== '' &&
          normalizedUserAnswer &&
          !isCorrectState;

        const baseInputClass =
          "min-w-[120px] inline-block border-x-0 border-t-0 border-b border-dotted border-slate-400 bg-transparent px-1 py-0 text-sm leading-none font-medium text-blue-900 focus:outline-none placeholder:text-slate-400 align-baseline transition-colors translate-y-[-2px]";
        const disabledClass =
          disabled || (reviewMode) || !isInteractive
            ? "cursor-not-allowed opacity-80"
            : "focus:border-blue-500";
        const reviewClass = reviewMode
          ? isCorrectState
            ? "border-green-500 text-green-700"
            : isIncorrectState
              ? "border-red-500 text-red-700"
              : "border-slate-300 text-slate-800"
          : "border-slate-300 text-slate-800";

        return (
          <span
            key={`gap-${descriptorIndex}`}
            className="inline-flex items-center gap-1 mx-1 align-baseline"
          >
            <span className="inline-flex h-5 min-w-[1.25rem] flex-shrink-0 items-center justify-center rounded border border-orange-300 bg-orange-100 px-1 text-[10px] font-bold text-orange-600 align-middle">
              {answerNumber}
            </span>
            <input
              type="text"
              name={name}
              value={userAnswer}
              onChange={(event) => handleAnswerChange(answerIndex, event.target.value)}
              disabled={disabled || (reviewMode) || !isInteractive}
              data-testid={`gap-fill-table-input-${answerNumber}`}
              data-question-slot-index={answerIndex}
              data-question-slot-id={descriptor.slotId}
              data-question-slot-number={answerNumber}
              className={`${baseInputClass} ${disabledClass} ${reviewClass}`}
              placeholder="Answer"
            />
          </span>
        );
      }

      if (!part) {
        return null;
      }

      return (
        <span
          key={`text-${index}`}
          className="whitespace-pre-line text-sm text-slate-700"
          dangerouslySetInnerHTML={{ __html: part }}
        />
      );
    });
  };

  // === EDITABLE CELL COMPONENT for edit mode ===
  const EditableCell = ({ rowId, cellId, content, className }) => {
    const [isEditing, setIsEditing] = useState(false);
    const [editValue, setEditValue] = useState(content);
    const inputRef = React.useRef(null);

    React.useEffect(() => {
      if (isEditing && inputRef.current) {
        inputRef.current.focus();
        inputRef.current.select();
      }
    }, [isEditing]);

    React.useEffect(() => {
      if (!isEditing) setEditValue(content);
    }, [content, isEditing]);

    if (!editMode) {
      return <div className={className}>{renderCellContent({ parts: content ? content.split(/(__GAP_\d+__)/) : [''], descriptorIndices: [] })}</div>;
    }

    if (isEditing) {
      return (
        <input
          ref={inputRef}
          type="text"
          value={editValue}
          onChange={(e) => setEditValue(e.target.value)}
          onBlur={() => {
            handleCellEdit(rowId, cellId, editValue);
            setIsEditing(false);
          }}
          onKeyDown={(e) => {
            if (e.key === 'Enter') {
              handleCellEdit(rowId, cellId, editValue);
              setIsEditing(false);
            }
            if (e.key === 'Escape') {
              setEditValue(content);
              setIsEditing(false);
            }
          }}
          className="w-full rounded border border-blue-400 px-2 py-1 text-sm focus:outline-none focus:ring-2 focus:ring-blue-200"
          placeholder="Enter cell content..."
        />
      );
    }

    // Display mode (edit mode but not actively editing)
    return (
      <div
        onClick={() => setIsEditing(true)}
        className={`cursor-pointer rounded px-1 py-0.5 transition-colors hover:bg-blue-50 hover:ring-1 hover:ring-blue-200 ${className} ${!content ? 'text-slate-400 italic' : ''}`}
        title="Click to edit"
      >
        {content ? (
          <div className="leading-relaxed">{renderCellContent({ parts: content.split(/(__GAP_\d+__)/), descriptorIndices: [] })}</div>
        ) : (
          'Click to edit...'
        )}
      </div>
    );
  };

  const headerRows = tablePlan.rows.filter((row) => row.type === "header");
  const bodyRows = tablePlan.rows.filter((row) => row.type !== "header");
  const effectiveBodyRows = bodyRows.length > 0 ? bodyRows : tablePlan.rows;

  return (
    <div className="space-y-4">
      {/* Edit mode toolbar */}
      {editMode && (
        <div className="flex items-center justify-between rounded-lg border border-blue-200 bg-blue-50 px-3 py-2">
          <div className="text-xs text-blue-600">
            <span className="font-semibold">📝 Edit Mode</span> — Click cells to edit. Use <code className="rounded bg-blue-100 px-1">__1__</code>, <code className="rounded bg-blue-100 px-1">__2__</code> for blanks.
          </div>
          {onOpenSpreadsheet && (
            <button
              type="button"
              onClick={onOpenSpreadsheet}
              className="rounded border border-emerald-300 bg-emerald-50 px-2 py-1 text-xs font-semibold text-emerald-600 transition hover:bg-emerald-100"
            >
              ⊞ Spreadsheet
            </button>
          )}
        </div>
      )}

      <div className={`overflow-x-auto rounded-lg border ${editMode ? 'border-blue-300' : 'border-black'}`}>
        <table className="w-full border-collapse bg-white">
          {tablePlan.caption ? (
            <caption className={`border-b ${editMode ? 'border-blue-200' : 'border-black'} px-4 py-2 text-center text-sm font-semibold text-slate-700`}>
              {editMode ? (
                <EditableCell
                  rowId="caption"
                  cellId="caption"
                  content={tablePlan.caption}
                  className="inline-block"
                />
              ) : tablePlan.caption}
            </caption>
          ) : null}

          {headerRows.length > 0 ? (
            <thead>
              {headerRows.map((row, rowIdx) => (
                <tr key={row.id}>
                  {row.cells.map((cell, cellIdx) => {
                    const isFirstCol = cellIdx === 0;
                    const isLastCol = cellIdx === row.cells.length - 1;
                    const borderColor = editMode ? 'border-blue-200' : 'border-black';

                    let borderClasses = `px-3 py-2 text-left text-xs font-semibold uppercase tracking-wide text-slate-700`;
                    if (!row.noBorderBottom) borderClasses += ` border-b ${borderColor}`;
                    if (!isFirstCol) borderClasses += ` border-l ${borderColor}`;
                    if (!isLastCol) borderClasses += ` border-r ${borderColor}`;

                    const originalContent = cell.originalContent || '';

                    return (
                      <th
                        key={cell.id}
                        colSpan={cell.colSpan > 1 ? cell.colSpan : undefined}
                        rowSpan={cell.rowSpan > 1 ? cell.rowSpan : undefined}
                        className={borderClasses}
                      >
                        {editMode ? (
                          <EditableCell rowId={row.id} cellId={cell.id} content={originalContent} />
                        ) : (
                          <div className="leading-relaxed">{renderCellContent(cell)}</div>
                        )}
                      </th>
                    );
                  })}
                </tr>
              ))}
            </thead>
          ) : null}

          <tbody>
            {effectiveBodyRows.map((row, rowIdx) => (
              <tr key={row.id}>
                {row.cells.map((cell, cellIdx) => {
                  const isFirstCol = cellIdx === 0;
                  const isLastRow = rowIdx === effectiveBodyRows.length - 1;
                  const isLastCol = cellIdx === row.cells.length - 1;
                  const borderColor = editMode ? 'border-blue-200' : 'border-black';

                  let borderClasses = `px-3 py-2 align-top bg-white`;
                  if (!isLastRow) borderClasses += ` border-b ${borderColor}`;
                  if (!isFirstCol) borderClasses += ` border-l ${borderColor}`;
                  if (!isLastCol) borderClasses += ` border-r ${borderColor}`;

                  const originalContent = cell.originalContent || '';

                  return (
                    <td
                      key={cell.id}
                      colSpan={cell.colSpan > 1 ? cell.colSpan : undefined}
                      rowSpan={cell.rowSpan > 1 ? cell.rowSpan : undefined}
                      className={borderClasses}
                    >
                      {editMode ? (
                        <EditableCell rowId={row.id} cellId={cell.id} content={originalContent} />
                      ) : (
                        <div className="leading-relaxed">{renderCellContent(cell)}</div>
                      )}
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Edit Mode: Answer inputs */}
      {editMode && gapCount > 0 && (
        <div className="rounded-lg border border-slate-200 bg-slate-50 p-4">
          <div className="mb-3 flex items-center justify-between">
            <p className="text-sm font-semibold text-slate-700">
              Answers ({gapCount} blank{gapCount === 1 ? '' : 's'})
            </p>
            <span className="text-xs text-slate-500">
              Use <code className="rounded bg-white px-1">|</code> for alternatives (e.g., "2 weeks|two weeks")
            </span>
          </div>
          <div className="grid gap-2 md:grid-cols-2">
            {Array.from({ length: gapCount }).map((_, index) => {
              const displayNumber = hasGlobalRange ? rangeStart + index : index + 1;
              return (
                <div key={`answer-${index}`} className="flex items-center gap-2">
                  <span className="inline-flex h-6 min-w-[2rem] flex-shrink-0 items-center justify-center rounded border border-orange-300 bg-orange-100 px-2 text-xs font-semibold text-orange-600">
                    {displayNumber}
                  </span>
                  <input
                    type="text"
                    value={normalizedAnswersForEdit[index] || ''}
                    onChange={(e) => handleCorrectAnswerChange(index, e.target.value)}
                    className="flex-1 rounded-lg border border-slate-300 px-3 py-1.5 text-sm text-slate-700 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
                    placeholder={`Answer for blank ${displayNumber}`}
                  />
                </div>
              );
            })}
          </div>
        </div>
      )}
      {isRegrade && reviewMode && (
        <AnswerKeyEditor
          correctAnswers={question.correctAnswers}
          questionType={question.type}
          onChange={(patch) => setKeyEdit(sectionKey, question.id, patch)}
        />
      )}
    </div>
  );
};

export default GapFillTablePreview;
