import { collection, doc, getDoc, setDoc, serverTimestamp } from "firebase/firestore";
import { db } from "./firebase";
import { useState, useEffect } from "react";

export function useFirebase(service, collectionName, documentName) {
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    let isMounted = true;

    const execute = async () => {
      if (!service || !collectionName) return;

      setLoading(true);
      setError(null);

      try {
        let response = null;

        switch (service) {
          case Services.GET_DOCUMENT_BY_NAME: {
            response = await fetchDocumentByName(collectionName, documentName);
            break;
          }
          default:
            throw new Error(`Unsupported firebase service: ${service}`);
        }

        if (isMounted) {
          setData(response);
        }
      } catch (err) {
        if (isMounted) {
          console.error(err);
          setError(err);
        }
      } finally {
        if (isMounted) {
          setLoading(false);
        }
      }
    };

    execute();

    return () => {
      isMounted = false;
    };
  }, [service, collectionName, documentName]);

  return { data, loading, error };
}

const fetchDocumentByName = async (collectionName, documentName) => {
  if (!documentName) {
    throw new Error("Document name is required to fetch document");
  }

  // Normalize exam code to uppercase for 'exams' collection (legacy convention)
  // For 'testBank' collection, keep original case (IDs are lowercase like cam10_reading_test_01)
  const normalizedDocName = collectionName === 'testBank'
    ? String(documentName).trim()
    : String(documentName).trim().toUpperCase().replace(/\s+/g, '_');

  console.log('📡 Fetching document:', {
    database: db._databaseId?.database || 'unknown',
    collection: collectionName,
    document: normalizedDocName,
    originalInput: documentName,
  });

  const docRef = doc(db, collectionName, normalizedDocName);
  const docSnap = await getDoc(docRef);

  if (docSnap.exists()) {
    console.log('✅ Document found:', normalizedDocName);
    return docSnap.data();
  }

  console.warn('❌ Document not found:', normalizedDocName, 'in', db._databaseId?.database || 'unknown');
  return null;
};

const saveExamData = async (collectionName, documentName, data) => {
  const docRef = doc(db, collectionName, documentName);
  const payload =
    data && typeof data === "object" && !Array.isArray(data)
      ? data
      : { data };
  await setDoc(docRef, payload, { merge: true });
};

const saveExamDefinition = async (examCode, payload) => {
  if (!examCode) throw new Error("Exam code is required");
  console.log("saveExamDefinition payload", examCode, payload);

  const docRef = doc(db, "exams", examCode);
  await setDoc(
    docRef,
    {
      ...payload,
      meta: {
        ...(payload?.meta || {}),
        updatedAt: serverTimestamp(),
      },
    }
  );
};

/**
 * Patch a homework document's answer keys and increment meta.keyVersion.
 *
 * IMPORTANT — Firestore array-merge quirk:
 *   setDoc({ merge: true }) does NOT deep-merge inside arrays.
 *   Firestore field paths don't support numeric indices, so we CANNOT write
 *   a dotted path like "grammar.questions.3.correctAnswers" — it would replace
 *   the whole "questions" array on any shape drift.
 *   The safe pattern is to pass the ENTIRE affected section sub-object back
 *   (e.g. the whole `grammar` object with the edited question already spliced in).
 *   That is exactly what applyKeyEdits() produces, so callers should pass
 *   `{ [sectionKey]: examContent[sectionKey] }` for each edited section.
 *
 * @param {string} examCode           - homework document id
 * @param {object} sectionPatches     - { [sectionKey]: <full section sub-object> }
 * @param {object} options
 * @param {string} options.lastKeyUpdatedBy  - teacher uid (stamped in meta)
 * @returns {{ keyVersion: number }}
 */
const saveHomeworkAnswerKey = async (examCode, sectionPatches, { lastKeyUpdatedBy = 'unknown' } = {}) => {
  if (!examCode) throw new Error("Exam code is required");
  // homework collection merged into testBank (2026-05-09) — single source of truth
  const docRef = doc(db, "testBank", examCode);

  // Read current meta to safely increment keyVersion
  let currentMeta = {};
  try {
    const snap = await getDoc(docRef);
    if (snap.exists()) currentMeta = snap.data()?.meta || {};
  } catch (e) {
    console.warn('[saveHomeworkAnswerKey] Could not read current meta, starting keyVersion at 0:', e.message);
  }

  const nextKeyVersion = (currentMeta.keyVersion ?? 0) + 1;

  await setDoc(docRef, {
    ...sectionPatches,
    meta: {
      ...currentMeta,
      keyVersion: nextKeyVersion,
      lastKeyUpdatedAt: serverTimestamp(),
      lastKeyUpdatedBy,
    },
  }, { merge: true });

  console.log('[saveHomeworkAnswerKey] Saved key patches for', examCode, '| keyVersion:', nextKeyVersion, '| sections:', Object.keys(sectionPatches));
  return { keyVersion: nextKeyVersion };
};

const getExamDefinition = async (examCode) => {
  if (!examCode) throw new Error("Exam code is required");
  return fetchDocumentByName("exams", examCode);
};

export const generateDocId = () => {
  const now = new Date();
  const pad = (n) => String(n).padStart(2, '0');
  const ts = `${pad(now.getDate())}${pad(now.getMonth() + 1)}${now.getFullYear()}${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;
  const rand = Math.random().toString(36).substring(2, 6);
  return `${ts}_${rand}`;
};

// Track simulated failures so simulateError=once only blocks the FIRST attempt (retries succeed).
let _simulateErrorCount = 0;

// Persist ?simulateError flag to sessionStorage so it survives the InformationCollect redirect.
// The /exam/ route redirects to InformationCollect, which strips query params on the way back.
const _getSimulateError = () => {
  try {
    const fromUrl = new URLSearchParams(window.location.search).get('simulateError');
    if (fromUrl) {
      sessionStorage.setItem('__debug_simulateError', fromUrl);
      console.log('🧪 [simulateError] from URL:', fromUrl);
      return fromUrl;
    }
    const fromSession = sessionStorage.getItem('__debug_simulateError');
    if (fromSession) console.log('🧪 [simulateError] from sessionStorage:', fromSession);
    return fromSession;
  } catch (_) { return null; }
};

// ╔══════════════════════════════════════════════════════════════════════════════╗
// ║  submitExamResult — THE CORE WRITE                                         ║
// ║                                                                             ║
// ║  Writes the graded exam payload to Firestore `examSubmissions` collection.  ║
// ║  Called from handleConfirmSubmit() in index.jsx.                            ║
// ║                                                                             ║
// ║  FAILURE DEFENSES (in order of speed):                                      ║
// ║  1. navigator.onLine check   → instant throw if browser knows it's offline  ║
// ║  2. 3-second timeout         → catches dead connections / Firestore hanging ║
// ║  3. offline event listener   → in index.jsx, flips modal to error state     ║
// ║  4. window.confirm popup     → browser-native fallback in index.jsx catch   ║
// ║                                                                             ║
// ║  If this function throws, the caller (handleConfirmSubmit) catches it and:  ║
// ║  - Flips the ExamComplete modal to error state (React)                      ║
// ║  - Shows a window.confirm popup (browser-native backup)                     ║
// ║  - localStorage backup was already saved BEFORE this function was called    ║
// ║  - Periodic retry (30s) + modal retry button handle recovery                ║
// ║                                                                             ║
// ║  DEDUP DEFENSE: _submissionsInFlight tracks active writes by examCode.      ║
// ║  All retry paths (window.confirm, useSubmissionRecovery, modal button)      ║
// ║  converge here, so this is the single chokepoint that prevents duplicate    ║
// ║  Firestore documents when the network recovers while multiple retries are   ║
// ║  in flight simultaneously.                                                  ║
// ║                                                                             ║
// ║  DEBUG: add ?simulateError=once or ?simulateError=true to URL to test.      ║
// ║  Flag persists through InformationCollect redirect via sessionStorage.      ║
// ╚══════════════════════════════════════════════════════════════════════════════╝

// Module-level in-flight guard. Keyed by examCode so concurrent calls from
// different retry paths (window.confirm spam, useSubmissionRecovery interval,
// modal retry button) all share the same lock. Cleared in finally so a genuine
// retry after a real failure can still proceed.
const _submissionsInFlight = new Set();

const submitExamResult = async (examCode, payload, opts = {}) => {
  // ── Dedup guard: one write at a time per examCode ──
  if (_submissionsInFlight.has(examCode)) {
    console.warn(`⚠️ [submitExamResult] Duplicate call blocked — submission already in flight for ${examCode}`);
    throw new Error('Submission already in progress — please wait.');
  }
  _submissionsInFlight.add(examCode);
  try {
    // --- Debug: simulate Firestore failure for stress testing ---
    //   ?simulateError=true   → fail EVERY call (test localStorage persistence across page loads)
    //   ?simulateError=once   → fail FIRST call only (test full recovery in one session)
    //   Clear with: sessionStorage.removeItem('__debug_simulateError')
    const simulateError = _getSimulateError();
    if (simulateError === 'true') {
      console.error('🧪 [STRESS TEST] Simulating Firestore write failure (every call)!');
      throw new Error('[STRESS TEST] Simulated Firestore write failure');
    }
    if (simulateError === 'once' && _simulateErrorCount === 0) {
      _simulateErrorCount++;
      console.error('🧪 [STRESS TEST] Simulating Firestore write failure (first call only)!');
      throw new Error('[STRESS TEST] Simulated Firestore write failure (once)');
    }
    try { sessionStorage.removeItem('__debug_simulateError'); } catch (_) { }

    // --- Defense 1: instant offline check ---
    if (typeof navigator !== 'undefined' && !navigator.onLine) {
      console.error('🔌 [submitExamResult] navigator.onLine is FALSE — failing immediately');
      throw new Error('You are offline. Your answers are saved locally and will be submitted when you reconnect.');
    }
    console.log('📡 [submitExamResult] Starting Firestore write. navigator.onLine:', navigator.onLine);

    const colRef = collection(db, "examSubmissions");
    // Reuse doc ID from pending_submission if available — ensures retries
    // overwrite the same Firestore document instead of creating duplicates.
    const docId = payload._docId || generateDocId();
    const docRef = doc(colRef, docId);

    // --- Defense 2: 3-second timeout ---
    // Firestore setDoc() hangs FOREVER when offline (no reject, no resolve).
    // 3s is aggressive but we'd rather show the error fast than leave the
    // student staring at a spinner.
    const WRITE_TIMEOUT_MS = 3_000;
    await Promise.race([
      setDoc(docRef, {
        examCode,
        ...payload,
        createdAt: serverTimestamp(),
      }),
      new Promise((_, reject) =>
        setTimeout(() => reject(new Error('Firestore write timed out — check your connection.')), WRITE_TIMEOUT_MS)
      ),
    ]);

    // Breadcrumb for the /booking round-trip: same-origin tabs share localStorage,
    // so the booking tab can resolve THIS exact submission (no scanning). Harmless
    // for every other entry point. See src/Pages/Booking/bookingData.js.
    try {
      localStorage.setItem('wv_last_submission', JSON.stringify({ examCode, docId, at: Date.now() }));
    } catch (_) { /* ignore */ }

    // If embedded in portal iframe, post result back with test metadata
    const isEmbedded = new URLSearchParams(window.location.search).get('embedded') === 'true';
    if (isEmbedded && window.parent !== window) {
      let testMeta = {};
      try {
        const indexSnap = await getDoc(doc(db, 'testBank_index', examCode));
        if (indexSnap.exists()) testMeta = indexSnap.data();
      } catch (e) {
        console.warn('[submitExamResult] Could not fetch testBank_index:', e.message);
      }

      const categoryKey = (testMeta.category || '').toLowerCase();
      const sections = payload.summary?.sections || {};

      if (['grammar', 'vocabulary'].includes(categoryKey)) {
        const currentKey = Object.keys(sections).find(k => k.toLowerCase() === categoryKey)
          || Object.keys(sections)[0];
        if (currentKey && currentKey !== categoryKey) {
          sections[categoryKey] = sections[currentKey];
        }
      }

      // ACK is purely informational for the caller — it's tracked by the
      // handshake in useExamSubmission, not here. This is fire-and-forget.
      // _docId is the Portal-side dedup key — a re-post with the same _docId
      // short-circuits to ACK without re-running commitExamResult.
      const message = {
        type: 'EXAM_RESULT',
        payload: {
          examCode,
          title: testMeta.title || examCode,
          category: testMeta.category || 'Practice',
          difficulty: testMeta.difficulty || 'medium',
          types: testMeta.types || [],
          summary: { ...payload.summary, sections },
          answers: payload.answers || {},
          questionResults: payload.questionResults || {},
          _startedAt: payload._startedAt || null,
          _docId: payload._docId || docId,
          review: payload.review || null,
        }
      };
      const targetOrigin = resolveParentOrigin();
      // DEBUG: log the listening answers payload for troubleshooting Faye wrong-question reconstruction
      try {
        const listeningAnswers = message.payload.answers?.listening || {};
        const listeningKeys = Object.keys(listeningAnswers);
        console.log('📨 [submitExamResult] EXAM_RESULT listening answers keys:', listeningKeys);
        listeningKeys.forEach((k) => {
          const v = listeningAnswers[k];
          console.log(`   [submitExamResult] listening[${k}] =`, v, `(type: ${Array.isArray(v) ? 'array' : typeof v})`);
        });
      } catch (e) { /* ignore debug crash */ }

      window.parent.postMessage(message, targetOrigin);
      if (typeof opts.onPosted === 'function') {
        try { opts.onPosted({ message, targetOrigin }); }
        catch (e) { console.warn('[submitExamResult] onPosted threw:', e); }
      }
    }
  } finally {
    _submissionsInFlight.delete(examCode);
  }
};

/**
 * Resolve the parent (Portal) origin to use as the `targetOrigin` for
 * postMessage. We derive it from the parent's actual URL (`document.referrer`)
 * so we honor whatever scheme the Portal was served over.
 *
 * The old logic rewrote the host in our OWN origin (`https://test…` →
 * `https://portal…`), which hardcoded `https`. When the Portal page was served
 * over plain `http`, the browser saw a scheme mismatch and silently dropped
 * every EXAM_RESULT — no ACK, and in practice/preview mode (no Firestore write)
 * the result was lost entirely.
 *
 * Falls back to the host-swap when the referrer is unavailable or is a
 * self-referral (an internal iframe reload, where referrer points back at the
 * test origin rather than the Portal parent).
 */
const resolveParentOrigin = () => {
  try {
    if (typeof document !== 'undefined' && document.referrer) {
      const refOrigin = new URL(document.referrer).origin;
      if (refOrigin && refOrigin !== window.location.origin) {
        return refOrigin;
      }
    }
  } catch (e) {
    /* malformed referrer — fall through to host-swap */
  }
  return window.location.origin
    .replace('test.weaver.edu.vn', 'portal.weaver.edu.vn')
    .replace('localhost:5174', 'localhost:5173')
    .replace('localhost:3000', 'localhost:5173')
    .replace('localhost:3001', 'localhost:5173');
};

/**
 * Post exam result to parent window (portal) without writing to Firestore.
 * Used by preview/practice mode when embedded in an iframe.
 *
 * Mints a client-side `_docId` so the Portal can dedup re-posts. There is no
 * Firestore doc on this path — `_docId` is a postMessage dedup nonce only.
 */
const postEmbeddedResult = async (examCode, summary, answers, questionResults, startedAt, opts = {}) => {
  if (window.parent === window) return; // not in an iframe

  let testMeta = {};
  try {
    const indexSnap = await getDoc(doc(db, 'testBank_index', examCode));
    if (indexSnap.exists()) testMeta = indexSnap.data();
  } catch (e) {
    console.warn('[postEmbeddedResult] Could not fetch testBank_index:', e.message);
  }

  const categoryKey = (testMeta.category || '').toLowerCase();
  const sections = summary?.sections || {};

  // For Grammar/Vocabulary, ensure the portal-expected key exists
  if (['grammar', 'vocabulary'].includes(categoryKey)) {
    const currentKey = Object.keys(sections).find(k => k.toLowerCase() === categoryKey)
      || Object.keys(sections)[0];

    if (currentKey && currentKey !== categoryKey) {
      sections[categoryKey] = sections[currentKey];
    }
  }

  const docId = opts._docId || generateDocId();

  // Fire-and-forget. ACK tracking (for showing a warning on timeout) is owned
  // by useExamSubmission — it attaches the listener before calling this fn.
  const message = {
    type: 'EXAM_RESULT',
    payload: {
      examCode,
      title: testMeta.title || examCode,
      category: testMeta.category || 'Practice',
      difficulty: testMeta.difficulty || 'medium',
      types: testMeta.types || [],
      summary: {
        ...summary,
        sections
      },
      answers: answers || {},
      questionResults: questionResults || {},
      _startedAt: startedAt || null,
      _docId: docId,
      review: opts.review || null,
    }
  };
  const targetOrigin = resolveParentOrigin();
  // DEBUG: log the listening answers payload for troubleshooting Faye wrong-question reconstruction
  try {
    const listeningAnswers = message.payload.answers?.listening || {};
    const listeningKeys = Object.keys(listeningAnswers);
    console.log('📨 [postEmbeddedResult] EXAM_RESULT listening answers keys:', listeningKeys);
    listeningKeys.forEach((k) => {
      const v = listeningAnswers[k];
      console.log(`   [postEmbeddedResult] listening[${k}] =`, v, `(type: ${Array.isArray(v) ? 'array' : typeof v})`);
    });
  } catch (e) { /* ignore debug crash */ }

  window.parent.postMessage(message, targetOrigin);
  console.log('📨 [postEmbeddedResult] Sent EXAM_RESULT to portal');
  if (typeof opts.onPosted === 'function') {
    try { opts.onPosted({ message, targetOrigin }); }
    catch (e) { console.warn('[postEmbeddedResult] onPosted threw:', e); }
  }
};

const testBackendConnection = async (payload) => {
  console.log('📡 [Backend] Testing Firestore connection to "test_submit"...');
  try {
    const colRef = collection(db, "test_submit");
    // Use the provided payload for the test submission
    const dataToSubmit = {
      ...payload,
      _testTimestamp: serverTimestamp(),
      _userAgent: typeof navigator !== 'undefined' ? navigator.userAgent : 'unknown'
    };

    console.log('📤 [Backend] Submitting dummy test payload:', dataToSubmit);

    const docId = generateDocId();

    const docRef = doc(colRef, docId);
    await setDoc(docRef, dataToSubmit);

    // Check if we actually got a document ID back - this is the critical check
    if (docRef && docRef.id) {
      console.log('✅ [Backend] Connection test successful. Document written with ID:', docRef.id);
      return docRef;
    } else {
      throw new Error("No document reference returned from setDoc");
    }
  } catch (error) {
    console.warn('❌ [Backend] Connection test failed:', error);
    throw error;
  }
};

/**
 * Manually sync a recovered exam result to Firestore 'backup_submit' collection.
 * Uses the same structure and ID generation as standard submit.
 */
const syncToBackupSubmit = async (examCode, payload) => {
  try {
    const docId = generateDocId();
    const colRef = collection(db, "backup_submit");
    const docRef = doc(colRef, docId);

    await setDoc(docRef, {
      payloadString: JSON.stringify(payload), // Stringify to avoid nested array/invalid data issues
      examCode: examCode || payload.examCode || "UNKNOWN",
      createdAt: serverTimestamp(),
      syncedAt: serverTimestamp(),
      isRecovered: true,
      recoveredBy: 'history_page'
    });
    console.log('✅ [Sync] Successfully synced recovered result to backup_submit with ID:', docId);
    return true;
  } catch (error) {
    console.error('❌ [Sync] Failed to sync recovered result:', error);
    throw error;
  }
};

/**
 * Last-resort persistence for an EMBEDDED practice/preview result whose
 * EXAM_RESULT postMessage never got an ACK from the Portal (e.g. the parent
 * page was served over a scheme our targetOrigin couldn't reach, or the
 * Portal listener was absent / crashed). Practice & preview mode do NO
 * `examSubmissions` write — postMessage is the only delivery path — so without
 * this the student's result is lost entirely.
 *
 * Doc IDs are prefixed `ACKDROP_` so an admin can scan for dropped results:
 *   backup_submit where __name__ >= 'ACKDROP_' and __name__ < 'ACKDROP`'
 * (or just eyeball the collection — the prefix sorts them together).
 */
const backupDroppedResult = async (examCode, payload, meta = {}) => {
  try {
    const docId = `ACKDROP_${generateDocId()}`;
    const colRef = collection(db, "backup_submit");
    const docRef = doc(colRef, docId);
    await setDoc(docRef, {
      payloadString: JSON.stringify(payload),
      examCode: examCode || payload?.examCode || "UNKNOWN",
      _docId: payload?._docId || null,
      reason: "ack_timeout_embedded",
      mode: meta.mode || "practice",
      parentReferrer: typeof document !== 'undefined' ? document.referrer : '',
      attemptedTargetOrigin: meta.targetOrigin || null,
      isDropped: true,
      droppedAt: serverTimestamp(),
      createdAt: serverTimestamp(),
    });
    console.warn('🛟 [ACKDROP] Backed up dropped result to backup_submit/', docId);
    return docId;
  } catch (error) {
    console.error('❌ [ACKDROP] Failed to back up dropped result:', error);
    throw error;
  }
};

const backupFailedSubmission = async (examCode, payload, error) => {
  try {
    const colRef = collection(db, "backup_submit_failed");
    console.warn("⚠️ Attempting to backup failed submission...", examCode);

    const docId = generateDocId();

    // Use setDoc with specific ID instead of addDoc
    const docRef = doc(colRef, docId);

    await setDoc(docRef, {
      examCode: examCode || "UNKNOWN",
      payloadString: JSON.stringify(payload), // Stringify to avoid nested array/invalid data issues
      error: error ? error.toString() : "Unknown error",
      backupTimestamp: serverTimestamp(),
      userAgent: typeof navigator !== 'undefined' ? navigator.userAgent : 'unknown'
    });
    console.log("✅ Backup of failed submission saved successfully with ID:", docId);
  } catch (backupErr) {
    console.error("❌ Critical: Failed to save backup submission!", backupErr);
  }
};


