/**
 * featureFlags — session-cached read of config/featureFlags.
 *
 * Exam app reads this once on first call (on mount of useExamSubmission) and
 * caches in module scope for the rest of the session. Reload reads fresh.
 *
 * Fail-open: if the doc is missing or the read fails, defaults to all-true.
 * The review modal isn't load-bearing — better to show it than to silently
 * disable on a transient Firestore hiccup. To kill the feature, an admin
 * sets `config/featureFlags.reviewModal = false` explicitly.
 */

import { doc, getDoc } from 'firebase/firestore';
import { db } from '../controller/firebase';

const DEFAULTS = Object.freeze({
  reviewModal: true,
});

let cached = null;
let inflight = null;

export async function getFeatureFlags() {
  if (cached) return cached;
  if (inflight) return inflight;

  inflight = (async () => {
    try {
      const snap = await getDoc(doc(db, 'config', 'featureFlags'));
      if (!snap.exists()) {
        cached = { ...DEFAULTS };
        return cached;
      }
      const data = snap.data() || {};
      cached = {
        reviewModal: typeof data.reviewModal === 'boolean' ? data.reviewModal : DEFAULTS.reviewModal,
      };
      return cached;
    } catch (err) {
      console.warn('[featureFlags] read failed, falling back to defaults:', err.message);
      cached = { ...DEFAULTS };
      return cached;
    } finally {
      inflight = null;
    }
  })();

  return inflight;
}

/**
 * Synchronous accessor for the cached value. Returns DEFAULTS until
 * getFeatureFlags() has resolved at least once. Components that depend on
 * the flag should `await getFeatureFlags()` on mount, store the result in
 * state, and only then render gated UI.
 */
export function getCachedFeatureFlags() {
  return cached || DEFAULTS;
}

// Test-only — lets unit tests reset between cases.
export function __resetFeatureFlagsForTests() {
  cached = null;
  inflight = null;
}
