/**
 * Helper functions for passage rendering and ordering
 */

/**
 * Get grouped question indices from instruction groups
 * @param {Array} instructionGroups - Array of instruction groups
 * @returns {Set} Set of question indices that are grouped
 */
export function getGroupedQuestionIndices(instructionGroups) {
  const groupedQuestionIndices = new Set();
  (instructionGroups || []).forEach((group) => {
    for (let i = group.startIndex; i <= group.endIndex; i++) {
      groupedQuestionIndices.add(i - 1);
    }
  });
  return groupedQuestionIndices;
}

/**
 * Check if passage has ungrouped questions
 * @param {Array} questions - Array of questions
 * @param {Set} groupedQuestionIndices - Set of grouped question indices
 * @returns {boolean} True if there are ungrouped questions
 */
export function hasUngroupedQuestions(questions, groupedQuestionIndices) {
  return questions?.some((_, qIdx) => !groupedQuestionIndices.has(qIdx));
}

/**
 * Get ordered sections (groups + ungrouped) for rendering
 * @param {Object} passage - Passage object
 * @param {number} passageIndex - Index of passage
 * @returns {Array} Array of section objects with type and data
 */
export function getOrderedSections(passage, passageIndex) {
  const groupedQuestionIndices = getGroupedQuestionIndices(passage.instructionGroups);
  const hasUngrouped = hasUngroupedQuestions(passage.questions, groupedQuestionIndices);

  // Create display order if not exists
  const displayOrder = passage.displayOrder || [
    ...(passage.instructionGroups?.map((g, idx) => ({ 
      type: 'group', 
      id: `group-${passageIndex}-${idx}`, 
      index: idx 
    })) || []),
    ...(hasUngrouped ? [{ 
      type: 'ungrouped', 
      id: `ungrouped-${passageIndex}` 
    }] : [])
  ];

  // Map display order to actual sections
  return displayOrder.map((item) => {
    if (item.type === 'group') {
      return {
        type: 'group',
        group: passage.instructionGroups[item.index],
        groupIndex: item.index,
        id: item.id
      };
    } else if (item.type === 'ungrouped') {
      return {
        type: 'ungrouped',
        groupedQuestionIndices,
        id: item.id
      };
    }
    return null;
  }).filter(Boolean);
}
