import React, { useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';

const AlertTabOut = ({
  isSuppressed = false,
  onViolation = null,
}) => {
  const [isVisible, setIsVisible] = useState(false);
  const [countdown, setCountdown] = useState(10);
  const [isCountingDown, setIsCountingDown] = useState(false);
  const intervalRef = useRef(null);
  const countdownRef = useRef(10);
  const navigate = useNavigate();

  const stopCountdown = (resetToInitial = false) => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
    }
    setIsCountingDown(false);
    if (resetToInitial) {
      countdownRef.current = 10;
      setCountdown(10);
    } else {
      setCountdown(countdownRef.current);
    }
  };

  const startCountdown = () => {
    if (intervalRef.current) return;
    countdownRef.current = 10;
    setCountdown(10);
    setIsCountingDown(true);
    setIsVisible(true);

    intervalRef.current = setInterval(() => {
      countdownRef.current -= 1;
      setCountdown(countdownRef.current);

      if (countdownRef.current <= 0) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
        if (document.hidden) {
          if (typeof onViolation === 'function') {
            onViolation();
          }
          startCountdown();
        } else {
          setIsCountingDown(false);
        }
      }
    }, 1000);
  };

  const handleConfirm = () => {
    stopCountdown(true);
    setIsVisible(false);
  };

  useEffect(() => {
    if (isSuppressed) {
      // Ensure any visible alert is cleared and countdown stopped when suppression is turned on
      stopCountdown(true);
      setIsVisible(false);
      return undefined;
    }
    // Prevent tab closing/switching
    const handleBeforeUnload = (e) => {
      e.preventDefault();
      const message = "Are you sure you want to leave? The exam will be cancelled.";
      e.returnValue = message;
      return message;
    };

    window.addEventListener('beforeunload', handleBeforeUnload);

    const handleVisibilityChange = () => {
      if (document.hidden) {
        console.log("Tab is hidden - showing alert");
        startCountdown();
      } else {
        console.log("Tab is visible - stopping countdown");
        stopCountdown();
      }
    };

    const handleBlur = () => {
      console.log("Window blur - showing alert");
      startCountdown();
    };

    const handleFocus = () => {
      console.log("Window focus - stopping countdown");
      stopCountdown();
    };

    // Listen for both visibility change and window focus/blur
    document.addEventListener('visibilitychange', handleVisibilityChange);
    window.addEventListener('blur', handleBlur);
    window.addEventListener('focus', handleFocus);

    return () => {
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      window.removeEventListener('blur', handleBlur);
      window.removeEventListener('focus', handleFocus);
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
      window.removeEventListener('beforeunload', handleBeforeUnload);
    };
  }, [navigate, isSuppressed]);

  if (!isVisible) return null;

  return (
    <div className="fixed top-0 left-0 w-full h-full flex items-center justify-center bg-black bg-opacity-80 z-alert">
      <div className="bg-white rounded-xl p-8 shadow-2xl max-w-md w-full mx-4 border-2 border-amber-500">
        <div className="flex flex-col items-center">
          <div className="text-amber-500 mb-4">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 animate-bounce" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
            </svg>
          </div>
          <h2 className="text-2xl font-bold text-amber-600 mb-4 text-center">Chú ý</h2>
          <p className="text-gray-700 mb-6 text-center font-medium">
            {isCountingDown
              ? `Bạn đã rời khỏi tab thi. Quay lại để tiếp tục. Thời gian tab ẩn sẽ được ghi nhận.`
              : 'Bạn đã quay lại tab thi. Nhấn nút bên dưới để tiếp tục làm bài.'}
          </p>
          {isCountingDown ? (
            <div className="text-center p-4 bg-amber-50 rounded-lg w-full">
              <div className="text-5xl font-bold text-amber-600 animate-pulse tabular-nums">
                {countdown}
              </div>
              <p className="text-sm text-amber-500 mt-2 font-semibold">
                GIÂY CÒN LẠI
              </p>
            </div>
          ) : (
            <button
              onClick={handleConfirm}
              className="w-full py-3 px-4 bg-amber-500 text-white font-semibold rounded-lg hover:bg-amber-600 transition-colors shadow-sm"
            >
              Tiếp tục làm bài
            </button>
          )}
          <p className="mt-6 text-sm text-gray-500 text-center">
            {isCountingDown
              ? ' Quay lại tab thi ngay để tiếp tục'
              : 'Hãy ở lại tab thi để hoàn thành bài thi'}
          </p>
        </div>
      </div>
    </div>
  );
};

export default AlertTabOut;
