import { useEffect, useMemo, useState, useRef } from "react";
import { useParams, useLocation, useNavigate } from "react-router-dom";
import { routerPaths } from "../../../constants";
import { getCandidateProfile } from "../utils/storage";

const LAST_EXAM_KEY = 'weaver:lastExamCode';

/**
 * Handles route parsing, auth guards, reload detection, and redirect effects.
 *
 * Returns all derived route/mode flags plus examCode, navigate, and state setters
 * needed by the parent component.
 */
export const useExamRouting = () => {
  const { examCode: urlExamCode } = useParams();
  const location = useLocation();
  const navigate = useNavigate();

  // Mode flags
  // /homework/ collapsed into /practice/ (2026-05-09): both routes are now
  // preview-mode and read from testBank. Old /homework/ links keep working
  // because they still hit <Examp /> with isPracticeMode=true logic.
  const isPracticeMode = location.pathname.startsWith('/practice') || location.pathname.startsWith('/homework');
  const isHistoryMode = location.pathname.startsWith('/history');
  const isEmbedded = new URLSearchParams(location.search).get('embedded') === 'true';
  const isRegradeMode = new URLSearchParams(location.search).get('mode') === 'review';

  // Capture ?simulateError flag to sessionStorage immediately
  useMemo(() => {
    try {
      const simErr = new URLSearchParams(location.search).get('simulateError');
      if (simErr) {
        sessionStorage.setItem('__debug_simulateError', simErr);
        console.log('🧪 [Examp] Captured simulateError flag:', simErr, '→ saved to sessionStorage as __debug_simulateError');
      }
    } catch (_) { }
  }, [location.search]);

  const candidateProfile = useMemo(() => getCandidateProfile(), []);

  // Detect preview mode
  const isPreviewMode = useMemo(() => {
    if (isPracticeMode) return true;
    if (location.state?.from === 'informationCollect') return false;
    if (location.state?.from === 'examManager') return true;
    try {
      const draftKey = `weaver_preview_draft_${urlExamCode}`;
      if (typeof sessionStorage !== 'undefined' && sessionStorage.getItem(draftKey)) {
        return true;
      }
    } catch (e) { }
    try {
      const params = new URLSearchParams(location.search);
      if (params.get('preview') === 'true') return true;
    } catch (e) { }
    return false;
  }, [location.state, location.search, urlExamCode, isPracticeMode]);

  const hasCompletedInfoStep = location.state?.from === 'informationCollect';

  // Auth check — fire once on mount
  const authCheckedRef = useRef(false);
  // Check if this is a resume from the pending-submission banner
  const isResumeFromBanner = useMemo(() => {
    try {
      return sessionStorage.getItem('weaver:resumeFromBanner') === 'true';
    } catch {
      return false;
    }
  }, []);

  const isReload = useMemo(() => {
    if (isHistoryMode) return false;
    if (isPreviewMode) return false;
    if (isResumeFromBanner) return false;
    if (authCheckedRef.current) return false;
    authCheckedRef.current = true;
    if (typeof window !== 'undefined' && window.weaverAuth) {
      window.weaverAuth = false;
      return false;
    }
    return true;
  }, [isPreviewMode, isHistoryMode, isResumeFromBanner]);

  const [studentInfo, setStudentInfo] = useState(null);
  const [isWelcomeScreenVisible, setIsWelcomeScreenVisible] = useState(
    isResumeFromBanner ? false : (!isHistoryMode && !isPracticeMode && (isReload || (!isPreviewMode && !hasCompletedInfoStep)))
  );

  // Compute history code directly from available submissions
  const historyCode = useMemo(() => {
    if (!isHistoryMode || typeof window === 'undefined') return null;
    try {
      let preferred = localStorage.getItem(LAST_EXAM_KEY) || localStorage.getItem('weaver:pendingExamCode');
      if (preferred && localStorage.getItem(`weaver_${preferred}_pending_submission`)) {
        return preferred; // Preferred code has a valid history payload
      }
      // Otherwise find the first available pending submission
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && key.startsWith('weaver_') && key.endsWith('_pending_submission')) {
          return key.replace('weaver_', '').replace('_pending_submission', '');
        }
      }
    } catch (_) {}
    return null;
  }, [isHistoryMode]);

  // Resolve exam code with fallbacks
  const previewDraft = location.state?.previewDraft;
  const fallbackLastExam = (() => {
    try { return localStorage.getItem(LAST_EXAM_KEY); } catch (e) { return null; }
  })();
  const examCode = isHistoryMode 
    ? (historyCode || urlExamCode || fallbackLastExam || "IELTS_SILVER_112")
    : (urlExamCode || candidateProfile?.examCode || fallbackLastExam || "IELTS_SILVER_112");

  // Detect collection from URL path. /practice/ and /homework/ both read from
  // testBank since the collections were merged (2026-05-09). /exam/ retains
  // the legacy `exams` collection for full-submit flows.
  const examCollection = isPracticeMode ? 'testBank' : 'exams';

  // ── Redirect effects ──

  // Clear storage and redirect on reload
  useEffect(() => {
    if (isPreviewMode) return;
    if (isReload) {
      console.warn("⚠️ Page reload detected. Clearing storage.");
      try {
        const keysToRemove = [];
        for (let i = 0; i < sessionStorage.length; i++) {
          const key = sessionStorage.key(i);
          if (key && (
            key.startsWith('weaver_') ||
            key.startsWith('audio_') ||
            key.startsWith('listening_ready_')   // NEW: ListeningSection's beforeunload
                                                  // only fires while listening is mounted;
                                                  // sweep here covers the cross-section case.
          )) {
            keysToRemove.push(key);
          }
        }
        keysToRemove.forEach(k => sessionStorage.removeItem(k));
        console.log('🧹 [Reload-Sweep] Cleared exam session storage. Keys removed:', keysToRemove);
      } catch (e) {
        console.error('Failed to clear storage on reload:', e);
      }
      navigate(routerPaths.INFORMATION_COLLECT, { state: { from: 'exam', examCode: urlExamCode } });
    }
  }, [isPreviewMode, isReload, navigate, urlExamCode]);

  // Redirect to InformationCollect if no profile
  useEffect(() => {
    if (isResumeFromBanner) return; // Resume from banner — bypass guard
    if (!isHistoryMode && !isPreviewMode && !candidateProfile && !hasCompletedInfoStep) {
      if (urlExamCode) {
        localStorage.setItem('weaver:pendingExamCode', urlExamCode);
        localStorage.setItem(LAST_EXAM_KEY, urlExamCode);
      }
      try {
        console.info("[Examp] Redirecting to InformationCollect (no profile)", { urlExamCode });
      } catch (logErr) { }
      navigate(routerPaths.INFORMATION_COLLECT, { state: { from: 'exam', examCode: urlExamCode } });
    }
  }, [isHistoryMode, isPreviewMode, candidateProfile, navigate, urlExamCode, hasCompletedInfoStep, isResumeFromBanner]);

  // Placement-test guard
  useEffect(() => {
    if (isResumeFromBanner) return; // Resume from banner — bypass guard
    try {
      if (!isHistoryMode && !isPreviewMode && String(urlExamCode || '').trim().toLowerCase() === 'placement-test' && !hasCompletedInfoStep) {
        if (urlExamCode) {
          localStorage.setItem('weaver:pendingExamCode', urlExamCode);
          localStorage.setItem(LAST_EXAM_KEY, urlExamCode);
        }
        try {
          console.info("[Examp] Placement-test guard → InformationCollect", { urlExamCode, hasCompletedInfoStep });
        } catch (logErr) { }
        navigate(routerPaths.INFORMATION_COLLECT, { state: { from: 'exam', examCode: urlExamCode } });
      }
    } catch (e) { /* ignore navigation errors */ }
  }, [isHistoryMode, isPreviewMode, urlExamCode, hasCompletedInfoStep, navigate, isResumeFromBanner]);

  // Consume the banner resume flag so it doesn't persist on next visit
  useEffect(() => {
    if (isResumeFromBanner) {
      try { sessionStorage.removeItem('weaver:resumeFromBanner'); } catch {}
    }
  }, [isResumeFromBanner]);

  return {
    urlExamCode,
    examCode,
    examCollection,
    location,
    navigate,
    previewDraft,
    candidateProfile,
    isPracticeMode,
    isHistoryMode,
    isEmbedded,
    isRegradeMode,
    isPreviewMode,
    isReload,
    hasCompletedInfoStep,
    studentInfo,
    setStudentInfo,
    isWelcomeScreenVisible,
    setIsWelcomeScreenVisible,
    LAST_EXAM_KEY,
  };
};
