import React from "react";

const DefaultPreview = ({ question, answer, onChange }) => {
  return (
    <div className="rounded border border-rose-400 bg-rose-50 p-4 text-sm text-rose-600">
      <p className="font-semibold">Unsupported question type</p>
      <p className="mt-1">
        The question type <code>{question?.type || "unknown"}</code> does not have a preview
        implementation yet.
      </p>
      {onChange && (
        <button
          type="button"
          className="mt-3 rounded bg-slate-200 px-3 py-1 text-xs font-medium text-slate-600"
          onClick={() => onChange(answer)}
        >
          Mark as reviewed
        </button>
      )}
    </div>
  );
};

export default DefaultPreview;
