import React, { useMemo } from "react";
import { getDomainsForCategory } from "../data/reviewDomains";

const DIFFICULTY_OPTIONS = [
  { value: "easy",      label: "Dễ" },
  { value: "medium",    label: "Trung bình" },
  { value: "hard",      label: "Khó" },
  { value: "nightmare", label: "Cực khó" },
];

const COMMENT_MAX = 1000;

/**
 * ReviewModal — soft-mandatory post-test feedback.
 * Fully controlled — `useExamSubmission` owns the draft state because the
 * surrounding `Modals` useMemo recreates its function definition on every
 * dep change, which would unmount this modal and wipe internal state.
 */
const ReviewModal = ({
  isOpen,
  category,
  isSubmitting = false,
  difficulty,
  selectedDomains,    // string[] — canonical domain values currently picked
  comment,
  onSelectDifficulty,
  onToggleDomain,
  onCommentChange,
  onSubmit,
}) => {
  const domainOptions = useMemo(() => getDomainsForCategory(category), [category]);
  const selectedSet = useMemo(
    () => new Set(Array.isArray(selectedDomains) ? selectedDomains : []),
    [selectedDomains],
  );

  if (!isOpen) return null;

  const canSubmit = !!difficulty && !isSubmitting;

  const handleSubmit = () => {
    if (!canSubmit) return;
    onSubmit?.();
  };

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-label="Đánh giá bài thi"
      className="fixed inset-0 z-modal flex items-center justify-center bg-black/40 p-4 backdrop-blur-sm overflow-y-auto"
    >
      <div className="my-auto w-full max-w-lg rounded-2xl bg-white p-6 shadow-xl transform transition-all duration-300 opacity-100 scale-100 translate-y-0">
        <h2 className="text-lg md:text-xl font-semibold text-blue-950">
          Cảm nhận về bài thi này?
        </h2>
        <p className="mt-1 text-sm text-gray-500">
          Phản hồi của bạn giúp tụi mình điều chỉnh độ khó và phân loại bài thi cho cả lớp, từ đó nâng cao chất lượng phục vụ các bạn.
        </p>

        {/* ── Difficulty picker ── */}
        <div className="mt-5">
          <p className="text-sm font-semibold text-slate-800">Độ khó</p>
          <div className="mt-2 grid grid-cols-2 gap-2 sm:grid-cols-4">
            {DIFFICULTY_OPTIONS.map((opt) => {
              const active = difficulty === opt.value;
              return (
                <button
                  key={opt.value}
                  type="button"
                  onClick={() => onSelectDifficulty?.(opt.value)}
                  disabled={isSubmitting}
                  className={
                    "rounded-lg border px-3 py-2 text-sm font-semibold transition disabled:opacity-50 " +
                    (active
                      ? "border-orange-400 bg-orange-400 text-white"
                      : "border-gray-300 bg-white text-gray-700 hover:bg-orange-50 hover:border-orange-300")
                  }
                >
                  {opt.label}
                </button>
              );
            })}
          </div>
        </div>

        {/* ── Domain multi-select (R/L only) ── */}
        {domainOptions.length > 0 && (
          <div className="mt-5">
            <p className="text-sm font-semibold text-slate-800">
              Bài thi này chủ yếu kiểm tra kỹ năng nào?
              <span className="ml-1 text-xs font-normal text-gray-400">(chọn nhiều)</span>
            </p>
            <div className="mt-2 flex flex-wrap gap-2">
              {domainOptions.map((opt) => {
                const active = selectedSet.has(opt.value);
                return (
                  <button
                    key={opt.value}
                    type="button"
                    onClick={() => onToggleDomain?.(opt.value)}
                    disabled={isSubmitting}
                    className={
                      "rounded-full border px-3 py-1.5 text-xs font-medium transition disabled:opacity-50 " +
                      (active
                        ? "border-orange-400 bg-orange-400 text-white"
                        : "border-gray-300 bg-white text-gray-600 hover:bg-orange-50 hover:border-orange-300")
                    }
                  >
                    {opt.label}
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {/* ── Comment ── */}
        <div className="mt-5">
          <label htmlFor="review-comment" className="text-sm font-semibold text-slate-800">
            Có gì muốn kể thêm không?
            <span className="ml-1 text-xs font-normal text-gray-400">(không bắt buộc)</span>
          </label>
          <textarea
            id="review-comment"
            value={comment || ""}
            onChange={(e) => onCommentChange?.(e.target.value.slice(0, COMMENT_MAX))}
            disabled={isSubmitting}
            rows={3}
            placeholder="VD: phần map khá khó nghe, đoạn 2 đọc nhanh quá..."
            className="mt-2 w-full resize-none rounded-lg border border-gray-300 p-3 text-sm text-gray-800 placeholder:text-gray-400 focus:border-orange-300 focus:outline-none focus:ring-2 focus:ring-orange-100 disabled:opacity-50"
          />
          <div className="mt-1 flex justify-end">
            <span className={"text-xs " + ((comment?.length || 0) >= COMMENT_MAX ? "text-red-500" : "text-gray-400")}>
              {comment?.length || 0}/{COMMENT_MAX}
            </span>
          </div>
        </div>

        {/* ── Actions ── */}
        <div className="mt-6 flex flex-col gap-2 sm:flex-row sm:justify-end">
          <button
            type="button"
            onClick={handleSubmit}
            disabled={!canSubmit}
            className="rounded-lg bg-orange-400 px-5 py-2 text-sm font-semibold text-white transition hover:bg-orange-500 disabled:cursor-not-allowed disabled:opacity-50"
          >
            {isSubmitting ? "Đang gửi..." : "Gửi đánh giá"}
          </button>
        </div>
      </div>
    </div>
  );
};

export default ReviewModal;
