import { useCallback } from "react";

export const useQuestionState = ({ question, onChange }) => {
  const updateQuestion = useCallback(
    (updater) => {
      if (!onChange) return;
      if (typeof updater === "function") {
        onChange((current) => updater(current || question));
      } else {
        onChange(updater);
      }
    },
    [onChange, question]
  );

  const updateField = useCallback(
    (field, value) => {
      updateQuestion((current) => ({
        ...(current || {}),
        [field]: value,
      }));
    },
    [updateQuestion]
  );

  return {
    updateQuestion,
    updateField,
  };
};
