/**
 * examTrackingService.js
 *
 * Singleton service để track hành vi user trong placement test.
 * - Chỉ active với examCode chứa "placement-test"
 * - Queue events locally → batch flush lên Firestore mỗi FLUSH_INTERVAL_MS
 * - Flush synchronous khi tab đóng (beforeunload + visibilitychange)
 * - Rolling event buffer: tối đa MAX_EVENTS sự kiện mới nhất
 *
 * Usage:
 *   import examTrackingService from './examTrackingService';
 *   examTrackingService.init(sessionId, candidateProfile, examCode);
 *   examTrackingService.track('formField', { field: 'email', charCount: 5 });
 *   examTrackingService.finalize('submitted');
 */

import { supabase } from './supabase';

const FLUSH_INTERVAL_MS = 10_000;
const MAX_EVENTS = 500;
const TRACKING_COLLECTION = 'exam_tracking';

// Masking removed as per user request to see full PII in tracking db
const MASKED_FIELDS = [];
const NO_VALUE_FIELDS = ['learningHistory', 'otherInfo', 'address'];

const safeMaskValue = (field, value) => {
  if (NO_VALUE_FIELDS.includes(field)) return null; // chỉ track charCount
  return String(value || '').substring(0, 100); // truncate 100 chars
};

// ─── Generate session ID ──────────────────────────────────────────────────────
const generateSessionId = () => {
  const now = new Date();
  const pad = (n) => String(n).padStart(2, '0');
  const ts = `${pad(now.getDate())}${pad(now.getMonth() + 1)}${now.getFullYear()}_${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;
  const rand = Math.random().toString(36).substring(2, 6);
  return `${ts}_${rand}`;
};

// ─── Service state ────────────────────────────────────────────────────────────
let _sessionId = null;
let _examCode = null;
let _candidate = null;
let _isActive = false;
let _startedAt = null;
let _lastActiveAt = null;
let _events = [];          // local event queue
let _pendingFlush = [];    // events waiting to be written
let _flushTimer = null;
let _deviceInfo = {};
let _summary = {
  totalEvents: 0,
  timeOnWelcome: 0,
  timeOnForm: 0,
  timeOnExam: 0,
  sectionTimes: {},
  answeredQuestions: 0,
  tabOutCount: 0,
  keyComboMap: {},
  idleMs: 0,
};
let _sectionStartTime = null;
let _currentSection = null;
let _phaseStartTime = null;
let _currentPhase = null; // 'form' | 'welcome' | 'exam'
let _lastWritingValues = {}; // Track last recorded text per question
let _initialized = false;

// ─── Check if exam should be tracked ─────────────────────────────────────────
const shouldTrack = (examCode) => {
  return String(examCode || '').toLowerCase().includes('placement');
};

// ─── Device info snapshot ─────────────────────────────────────────────────────
const captureDeviceInfo = () => ({
  userAgent: navigator.userAgent || '',
  screenW: window.screen?.width || 0,
  screenH: window.screen?.height || 0,
  lang: navigator.language || '',
  timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || '',
  platform: navigator.platform || '',
  viewportW: window.innerWidth || 0,
  viewportH: window.innerHeight || 0,
});

// ─── Core: add event to local queue ──────────────────────────────────────────
const _addEvent = (type, payload = {}) => {
  if (!_isActive) return;

  const now = Date.now();
  _lastActiveAt = now;

  const event = {
    t: now - _startedAt,   // ms relative to session start
    type,
    ...payload,
  };

  _events.push(event);
  _summary.totalEvents++;

  // Rolling buffer: if over max, move oldest to pending discard (we only keep recent)
  if (_events.length > MAX_EVENTS) {
    _events.shift();
  }
};

// ─── Supabase write ──────────────────────────────────────────────────────────
const _writeToSupabase = async () => {
  if (!_sessionId || !supabase) return;
  try {
    const payload = {
      session_id: _sessionId,
      exam_code: _examCode,
      status: 'in_progress',
      candidate: _candidate,
      started_at: _startedAt,
      last_active_at: _lastActiveAt,
      device_info: _deviceInfo,
      events: _events.slice(-MAX_EVENTS), // rolling 500
      summary: _summary,
      updated_at: new Date().toISOString(),
    };
    await supabase.from(TRACKING_COLLECTION).upsert(payload, { onConflict: 'session_id' });
  } catch (err) {
    console.warn('[ExamTracking] Flush failed:', err);
  }
};

// ─── Synchronous beacon flush (beforeunload) ─────────────────────────────────
const _beaconFlush = () => {
  // Use sendBeacon with JSON if available — best effort on page close
  try {
    const data = {
      sessionId: _sessionId,
      status: 'abandoned',
      lastActiveAt: _lastActiveAt,
      summary: _summary,
      events: _events.slice(-50), // send only last 50 on beacon
    };
    // Try Firestore REST endpoint as beacon (best effort, no auth since rules allow writes from authed users)
    // For now: just mark via localStorage so next load picks up
    localStorage.setItem(`weaver_tracking_${_sessionId}_abandoned`, JSON.stringify({
      sessionId: _sessionId,
      examCode: _examCode,
      candidate: _candidate,
      abandonedAt: Date.now(),
    }));
  } catch (_) {}
};

// ─── Start/stop timer ────────────────────────────────────────────────────────
const _startFlushTimer = () => {
  if (_flushTimer) return;
  _flushTimer = setInterval(() => {
    _writeToSupabase();
  }, FLUSH_INTERVAL_MS);
};

const _stopFlushTimer = () => {
  if (_flushTimer) {
    clearInterval(_flushTimer);
    _flushTimer = null;
  }
};

// ─── Phase timing helpers ─────────────────────────────────────────────────────
const _endCurrentPhase = () => {
  if (!_phaseStartTime || !_currentPhase) return;
  const elapsed = Date.now() - _phaseStartTime;
  if (_currentPhase === 'form') _summary.timeOnForm += elapsed;
  else if (_currentPhase === 'welcome') _summary.timeOnWelcome += elapsed;
  else if (_currentPhase === 'exam') _summary.timeOnExam += elapsed;
};

const _startPhase = (phase) => {
  _endCurrentPhase();
  _currentPhase = phase;
  _phaseStartTime = Date.now();
};

// ─── Section timing helpers ───────────────────────────────────────────────────
const _endCurrentSection = () => {
  if (!_sectionStartTime || !_currentSection) return;
  const elapsed = Date.now() - _sectionStartTime;
  _summary.sectionTimes[_currentSection] = (_summary.sectionTimes[_currentSection] || 0) + elapsed;
};

// ─── Visibility / Focus / beforeunload listeners ─────────────────────────────
let _visibilityHandler = null;
let _focusHandler = null;
let _blurHandler = null;
let _beforeUnloadHandler = null;

const _attachGlobalListeners = () => {
  _visibilityHandler = () => {
    const hidden = document.visibilityState === 'hidden';
    _addEvent('tabVisibility', { state: hidden ? 'hidden' : 'visible' });
    if (hidden) {
      _summary.tabOutCount++;
      _writeToSupabase(); // eager flush on tab hide
    }
  };

  _focusHandler = () => {
    _addEvent('windowFocus', { state: 'focused' });
  };

  _blurHandler = () => {
    _addEvent('windowBlur', { state: 'blurred' });
    _summary.tabOutCount++;
    _writeToSupabase(); // eager flush on blur
  };

  _beforeUnloadHandler = () => {
    _endCurrentPhase();
    _endCurrentSection();
    _beaconFlush();
    // Attempt synchronous mark as abandoned in localStorage
  };

  document.addEventListener('visibilitychange', _visibilityHandler);
  window.addEventListener('focus', _focusHandler);
  window.addEventListener('blur', _blurHandler);
  window.addEventListener('beforeunload', _beforeUnloadHandler);
};

const _detachGlobalListeners = () => {
  if (_visibilityHandler) document.removeEventListener('visibilitychange', _visibilityHandler);
  if (_focusHandler) window.removeEventListener('focus', _focusHandler);
  if (_blurHandler) window.removeEventListener('blur', _blurHandler);
  if (_beforeUnloadHandler) window.removeEventListener('beforeunload', _beforeUnloadHandler);
  
  _visibilityHandler = null;
  _focusHandler = null;
  _blurHandler = null;
  _beforeUnloadHandler = null;
};

// ═══════════════════════════════════════════════════════════════════════════════
// PUBLIC API
// ═══════════════════════════════════════════════════════════════════════════════

const examTrackingService = {

  /**
   * Khởi tạo session tracking.
   * @param {object} candidateProfile - profile từ studentInfo form
   * @param {string} examCode - e.g. "placement-test"
   */
  init(candidateProfile, examCode) {
    if (!shouldTrack(examCode)) return;
    if (_initialized) {
      console.warn('[ExamTracking] Already initialized. Skipping.');
      return;
    }

    _sessionId = generateSessionId();
    _examCode = examCode;
    _startedAt = Date.now();
    _lastActiveAt = _startedAt;
    _isActive = true;
    _initialized = true;
    _events = [];
    _summary = {
      totalEvents: 0,
      timeOnWelcome: 0,
      timeOnForm: 0,
      timeOnExam: 0,
      sectionTimes: {},
      answeredQuestions: 0,
      tabOutCount: 0,
      keyComboMap: {},
      idleMs: 0,
    };

    // Sanitize candidate — keep full fields as per user request
    _candidate = {
      fullName: candidateProfile?.fullName || '',
      email: candidateProfile?.email || '',
      phone: candidateProfile?.phone || '',
      dob: candidateProfile?.dob || '',
      address: candidateProfile?.address || '',
      skills: candidateProfile?.skills || [],
      goal: candidateProfile?.goal || '',
      learningHistoryLength: String(candidateProfile?.learningHistory || '').length,
    };

    _deviceInfo = captureDeviceInfo();

    // Write initial doc immediately
    if (supabase) {
      supabase.from(TRACKING_COLLECTION).upsert({
        session_id: _sessionId,
        exam_code: _examCode,
        status: 'in_progress',
        candidate: _candidate,
        started_at: _startedAt,
        last_active_at: _lastActiveAt,
        device_info: _deviceInfo,
        events: [],
        summary: _summary,
        created_at: new Date().toISOString(),
      }, { onConflict: 'session_id' }).then(({ error }) => {
        if (error) console.warn('[ExamTracking] Init write failed:', error.message);
      });
    }

    _attachGlobalListeners();
    _startFlushTimer();

    console.log('[ExamTracking] Session started:', _sessionId);
  },

  /**
   * Track một event bất kỳ.
   * @param {string} type - event type
   * @param {object} payload - dữ liệu kèm theo
   */
  track(type, payload = {}) {
    _addEvent(type, payload);
  },

  /**
   * Track writing content (Optimized: only record on Space key or significant change).
   */
  trackWriting(sectionKey, questionId, value) {
    if (!_isActive) return;
    
    const text = String(value || '');
    const charCount = text.length;
    
    // Only record if:
    // 1. Last character is a space (finished a word)
    // 2. OR length changed significantly (pasted text)
    // 3. OR it's a very short text (initial typing)
    const lastChar = text.slice(-1);
    const isSpace = lastChar === ' ' || lastChar === '\n';
    
    // Avoid duplicate space events: only record if the content (trimmed) has actually changed.
    const lastRecorded = _lastWritingValues[questionId] || '';
    
    // Condition to trigger event:
    // - Is a space AND the trimmed content has changed (new word finished)
    // - OR very beginning of typing
    // - OR periodic progress (every 20 chars) IF text has changed
    const contentChanged = text.trim() !== lastRecorded.trim();
    const significantChange = Math.abs(charCount - lastRecorded.length) > 10;

    if ((isSpace && contentChanged) || charCount < 5 || (charCount > 0 && charCount % 20 === 0) || significantChange) {
      if (text === lastRecorded) return; // double safety

      _lastWritingValues[questionId] = text;
      const type = isSpace ? 'writing_word' : 'writing_progress';
      _addEvent(type, { 
        sectionKey, 
        questionId, 
        charCount, 
        value: text.substring(0, 1000) 
      });
    }
  },

  /**
   * Track field input (với masking tự động).
   */
  trackField(field, value) {
    const maskedValue = safeMaskValue(field, value);
    const event = {
      field,
      charCount: String(value || '').length,
    };
    if (maskedValue !== null) event.value = maskedValue;
    _addEvent('formField', event);
  },

  /**
   * Track key combo (Ctrl+C, Ctrl+V, ...).
   */
  trackKeyCombo(combo) {
    _summary.keyComboMap[combo] = (_summary.keyComboMap[combo] || 0) + 1;
    _addEvent('keyCombo', { combo });
  },

  /**
   * Báo section exam đang active thay đổi.
   */
  trackSectionChange(from, to) {
    _endCurrentSection();
    _currentSection = to;
    _sectionStartTime = Date.now();
    _addEvent('sectionChange', { from, to });
  },

  /**
   * Gọi khi user bắt đầu phase mới.
   * @param {'form'|'welcome'|'exam'} phase
   */
  setPhase(phase) {
    _startPhase(phase);
    _addEvent('phaseChange', { phase });
  },

  /**
   * Cập nhật số câu đã trả lời.
   */
  setAnsweredCount(count) {
    _summary.answeredQuestions = count;
  },

  /**
   * Finalize session với outcome.
   * @param {'submitted'|'tab_out'|'window_closed'|'abandoned'} outcome
   */
  async finalize(outcome) {
    if (!_isActive || !_sessionId) return;

    _endCurrentPhase();
    _endCurrentSection();
    _stopFlushTimer();
    _detachGlobalListeners();
    _isActive = false;

    const status = outcome === 'submitted' ? 'submitted' : 'abandoned';
    _addEvent('sessionEnd', { outcome });

    try {
      if (supabase) {
        await supabase.from(TRACKING_COLLECTION).upsert({
          session_id: _sessionId,
          exam_code: _examCode, // Always include mandatory field for potential INSERT
          status,
          events: _events.slice(-MAX_EVENTS),
          summary: _summary,
          updated_at: new Date().toISOString(),
        }, { onConflict: 'session_id' });
        console.log('[ExamTracking] Session finalized:', _sessionId, outcome);
      }
    } catch (err) {
      console.warn('[ExamTracking] Finalize write failed:', err);
    }

    // Clear abandoned marker if submitted
    if (outcome === 'submitted') {
      try { localStorage.removeItem(`weaver_tracking_${_sessionId}_abandoned`); } catch (_) {}
    }
  },

  /** Trả về sessionId hiện tại */
  getSessionId() { return _sessionId; },

  /** Check xem service có đang active không */
  isActive() { return _isActive; },

  /**
   * Reset service state (dùng khi component unmount hoàn toàn).
   */
  destroy() {
    _stopFlushTimer();
    _detachGlobalListeners();
    _isActive = false;
    _initialized = false;
    _sessionId = null;
    _events = [];
    _lastWritingValues = {};
  },
};

export default examTrackingService;
