import React, { useState, useEffect } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import WelcomePage from "./welcome";
import StudentInfo from "./studentInfo";
import SimpleStudentInfo from "./SimpleStudentInfo";
import PendingSubmissionBanner from "./PendingSubmissionBanner";
import { routerPaths } from "../../constants";
import examTrackingService from '../../controller/examTrackingService';
import { readStoredProfile, resolveCandidateId } from '../../utils/candidateId';
import { doc, getDoc } from 'firebase/firestore';
import { db } from '../../controller/firebase';

/**
 * Apply a decoded prefill profile: persist it to localStorage, init tracking, and
 * decide the starting step. Shared by the legacy `?prefill=<base64>` path (sync,
 * self-contained URL) and the new `?k=<code>` short-link path (async — the profile
 * is fetched from short_links/{code}, so PII never rides in the URL).
 * Returns the step to land on (0 = show form; 1 = skip to welcome for a complete
 * /booking identity).
 */
function applyDecodedProfile(decoded, opts = {}) {
  const storedProfile = readStoredProfile();
  const source = decoded._source || (storedProfile && storedProfile._source) || 'shortlink';
  const profile = {
    fullName: decoded.fullName || decoded.name || '',
    email: decoded.email || '',
    dob: decoded.dob || '',
    phone: decoded.phone || '',
    address: decoded.address || '',
    learningHistory: decoded.learningHistory || '',
    skills: decoded.skills || [],
    goal: decoded.goal || '',
    otherInfo: decoded.otherInfo || '',
    startedAt: Date.now(),
    _source: source,
    // Monotonic join key: prefer the prefill's candidateId, else REUSE any
    // already-minted id from localStorage, else mint — never persist '' (an empty
    // join key defeats CRM intake reconciliation and would split a revisiting human
    // into a second lead on a candidateId-less prefill).
    _candidateId: resolveCandidateId(decoded.candidateId),
    // `?k=` staff link: StudentInfo shows the staff-filled fields READ-ONLY for
    // review and leaves the blanks editable so the lead can enrich them.
    ...(opts.lockPrefilled ? { _lockPrefilled: true } : {}),
  };
  try {
    window.localStorage.setItem('weaver:candidateProfile', JSON.stringify(profile));
  } catch (e) { /* ignore */ }
  examTrackingService.init(profile, 'placement-test');
  examTrackingService.track('formPrefilled', { source, candidateId: decoded.candidateId });
  // A complete /booking identity skips the redundant form (it was collected moments
  // ago in the booking flow). A `?k=` staff link does NOT skip — StudentInfo shows
  // the prefill so the lead can review (staff-filled fields locked) and enrich the
  // blanks; candidate._candidateId still rides on the submission for CRM reconcile.
  const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(profile.email);
  const complete = emailOk && profile.fullName.trim() && profile.dob.trim() && profile.phone.trim();
  if (source === 'booking' && complete) {
    examTrackingService.track('formSkipped', { source, candidateId: decoded.candidateId });
    return 1;
  }
  return 0;
}

const InformationCollect = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const incomingExamCode = location.state?.examCode || null;

  // Placement test uses full form, other exams use simple form
  const isPlacementTest = location.pathname === '/' ||
    (incomingExamCode && ['placement-test', 'test-uat'].includes(incomingExamCode));

  // Two ways a link can pre-fill the form:
  //   ?prefill=<base64>  — legacy, self-contained (whole profile encoded in the URL)
  //   ?k=<code>          — current, opaque code → profile fetched from short_links/{code}
  const params = new URLSearchParams(location.search);
  const prefillParam = params.get('prefill');
  const linkCode = params.get('k');

  // Start at step 0 (form). The legacy prefill is decoded synchronously here; the
  // ?k= path resolves async below (see resolvingLink). If prefill is present we
  // fill the form but do not auto-skip (booking-complete identities aside).
  const [step, setStep] = useState(() => {
    if (prefillParam) {
      try {
        // Safe Unicode (UTF-8) Base64 decoding using TextDecoder (handles Vietnamese characters)
        const binString = atob(prefillParam);
        const uint8Array = Uint8Array.from(binString, (c) => c.charCodeAt(0));
        const jsonStr = new TextDecoder().decode(uint8Array);
        return applyDecodedProfile(JSON.parse(jsonStr));
      } catch (e) {
        console.warn('[InformationCollect] Invalid prefill param, showing form normally', e);
      }
    }
    return 0;
  });

  // Resolve the ?k=<code> short link: fetch short_links/{code}, apply its prefill
  // payload, then drop the loader. Showing a loader until the profile is persisted
  // matters — the form components read localStorage on MOUNT, so they must mount
  // AFTER applyDecodedProfile has written it.
  const [resolvingLink, setResolvingLink] = useState(() => !!linkCode && !prefillParam);

  useEffect(() => {
    if (!linkCode || prefillParam) return;
    let cancelled = false;
    (async () => {
      try {
        const snap = await getDoc(doc(db, 'short_links', linkCode));
        if (cancelled) return;
        if (snap.exists()) {
          const data = snap.data() || {};
          // Payload is nested under `prefill`; tolerate a flat doc defensively.
          // lockPrefilled: a staff link — show the form prefilled with the staff
          // fields locked for review; the lead can still fill the blanks.
          setStep(applyDecodedProfile(data.prefill || data, { lockPrefilled: true }));
        } else {
          console.warn('[InformationCollect] short link not found:', linkCode);
        }
      } catch (e) {
        console.warn('[InformationCollect] failed to resolve short link', e);
      } finally {
        if (!cancelled) setResolvingLink(false);
      }
    })();
    return () => { cancelled = true; };
  }, [linkCode, prefillParam]);

  // When moving to step 2, navigate to exam page using the code from navigation state
  React.useEffect(() => {
    if (step === 2) {
      const examCode = incomingExamCode || "placement-test";
      try {
        // Set authorization flag for strict reload detection
        if (typeof window !== 'undefined') {
          window.weaverAuth = true;
        }

        console.info("[InformationCollect] Proceeding to exam", {
          incomingExamCode,
          resolvedExamCode: examCode
        });

        navigate(`${routerPaths.EXAM}/${examCode}`, {
          state: { from: "informationCollect" }
        });
      } catch (logErr) { }
    }
  }, [step, navigate, incomingExamCode]);

  const isWelcomePage = step === 1;

  return (
    <div
      className={
        isWelcomePage
          ? "fixed inset-0 w-screen h-screen flex items-center justify-center bg-[#faeadd] overflow-hidden pt-20 pb-4"
          : isPlacementTest
            ? "flex min-h-screen w-full items-start justify-center bg-[#faeadd] overflow-auto pt-12 pb-6"
            : "flex min-h-screen w-full items-center justify-center bg-[#faeadd] overflow-auto pt-8 pb-6"
      }
    >
      <PendingSubmissionBanner />
      {resolvingLink ? (
        <div className="text-[#5b3a29] text-lg font-medium animate-pulse">Đang tải thông tin…</div>
      ) : step === 0 ? (
        isPlacementTest ? (
          <StudentInfo setStep={setStep} />
        ) : (
          <SimpleStudentInfo setStep={setStep} examCode={incomingExamCode} />
        )
      ) : step === 1 ? (
        <WelcomePage setStep={setStep} incomingExamCode={incomingExamCode} />
      ) : null}
    </div>
  );
};

export default InformationCollect;
