import React from "react";
import {
  AudioRecorder,
  useAudioRecorder,
} from "react-audio-voice-recorder";

const SpeakingSection = ({
  sectionKey,
  section,
  answers = {},
  onAnswerChange,
}) => {
  if (!section) {
    return (
      <div className="flex h-full items-center justify-center bg-white">
        <p className="text-sm text-gray-500">
          Speaking content is not available for this exam.
        </p>
      </div>
    );
  }

  const handleUpdate = (partId, payload) => {
    onAnswerChange?.(sectionKey, partId, payload);
  };

  return (
    <div className="flex h-full flex-col overflow-hidden bg-white">

      {/* Scrollable Content */}
      <div
        className="flex-1 overflow-y-auto bg-white relative"
        data-highlight-surface-id="speaking-content-surface"
      >
        {/* Header - scrolls with content */}
        <div className="border-b border-gray-200 bg-white px-3 py-2">
          <h2 className="text-base font-bold text-blue-950 text-center uppercase">IELTS Speaking Practice</h2>
          <p className="text-xs text-gray-600 mt-0.5 text-center">
            Practice answering each part. Record your responses and listen back to evaluate your pronunciation and fluency.
          </p>
        </div>

        <div className="space-y-6 px-5 py-5">
          {section.parts?.map((part, index) => (
            <SpeakingPartCard
              key={part.id}
              part={part}
              index={index}
              answer={answers[part.id]}
              onUpdate={(payload) => handleUpdate(part.id, payload)}
              sectionKey={sectionKey}
            />
          ))}
        </div>
      </div>
    </div>
  );
};

const SpeakingPartCard = ({ part, index, answer, onUpdate, sectionKey }) => {
  const recorderControls = useAudioRecorder();

  const handleRecordingComplete = (blob) => {
    if (answer?.url) {
      URL.revokeObjectURL(answer.url);
    }

    const url = URL.createObjectURL(blob);
    onUpdate({
      url,
      createdAt: Date.now(),
      duration: recorderControls.recordingTime ?? null,
      mimeType: blob.type,
      blob,
    });
  };

  const handleReset = () => {
    if (answer?.url) {
      URL.revokeObjectURL(answer.url);
    }
    onUpdate(null);
    recorderControls.stopRecording();
  };

  React.useEffect(
    () => () => {
      if (answer?.url) {
        URL.revokeObjectURL(answer.url);
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [answer?.url]
  );

  return (
    <article
      id={`question-${sectionKey}-${part.id}`}
      className="space-y-4 rounded-xl border border-gray-200 bg-gray-50 px-5 py-5 shadow-sm"
      tabIndex={-1}
    >
      <header className="space-y-1">
        <p className="text-xs uppercase tracking-wide text-blue-500">
          Speaking Part {index + 1}
        </p>
        <h3 className="text-lg font-semibold text-blue-900 uppercase">{part.title}</h3>
      </header>

      <p className="text-sm leading-relaxed text-gray-700">{part.prompt}</p>

      <div className="flex flex-wrap gap-3 text-xs text-gray-500">
        {part.preparationTime && (
          <span className="rounded-full bg-white px-3 py-1 shadow-sm">
            Prep: {part.preparationTime}
          </span>
        )}
        {part.speakingTime && (
          <span className="rounded-full bg-white px-3 py-1 shadow-sm">
            Speaking time: {part.speakingTime}
          </span>
        )}
      </div>

      <div className="rounded-lg border border-dashed border-blue-200 bg-white p-4">
        <AudioRecorder
          onRecordingComplete={handleRecordingComplete}
          recorderControls={recorderControls}
          audioTrackConstraints={{
            noiseSuppression: true,
            echoCancellation: true,
          }}
          downloadOnSavePress={false}
          showVisualizer
        />
      </div>

      {answer?.url && (
        <div className="space-y-2 rounded-lg border border-blue-100 bg-white p-4">
          <p className="text-sm font-medium text-blue-900">
            Your latest recording
          </p>
          <audio
            controls
            src={answer.url}
            className="w-full"
            preload="metadata"
          />
          <div className="flex items-center justify-between text-xs text-gray-500">
            <span>
              Recorded at: {new Date(answer.createdAt).toLocaleTimeString()}
            </span>
            <button
              type="button"
              onClick={handleReset}
              className="text-red-500 hover:text-red-600"
            >
              Delete recording
            </button>
          </div>
        </div>
      )}
    </article>
  );
};

export default SpeakingSection;
