import React, { useCallback, useState } from "react";
import { useQuestionContext } from "../../../contexts/QuestionContext";
import { synchronizeGapFillTableQuestion } from "../../../utils/question/gapFillTable";
import GapFillTableSpreadsheetEditor from "./SpreadsheetEditor";
import GapFillTablePreview from "./Preview";

/**
 * GapFillTableBuilder - Uses Preview component with editMode for WYSIWYG editing
 */
const GapFillTableBuilder = () => {
  const { question, updateQuestion } = useQuestionContext();
  const [isSpreadsheetOpen, setSpreadsheetOpen] = useState(false);

  // Handler for table replacement from spreadsheet editor
  const handleTableReplace = useCallback(
    (nextTable) => {
      updateQuestion((current = question) =>
        synchronizeGapFillTableQuestion({ ...current, table: nextTable }, { table: nextTable })
      );
    },
    [question, updateQuestion]
  );

  // Handler for prompt change
  const handlePromptChange = useCallback(
    (event) => {
      const value = event.target.value;
      updateQuestion((current = question) => ({
        ...current,
        prompt: value,
      }));
    },
    [question, updateQuestion]
  );

  // Handler for hint change
  const handleHintChange = useCallback(
    (event) => {
      const value = event.target.value;
      updateQuestion((current = question) => ({
        ...current,
        hint: value,
      }));
    },
    [question, updateQuestion]
  );

  return (
    <>
      <div className="space-y-6">
        {/* Instructions / Prompt */}
        <div>
          <label className="text-xs font-medium uppercase tracking-wide text-slate-500">
            Instructions / Prompt
          </label>
          <textarea
            value={question?.prompt || ""}
            onChange={handlePromptChange}
            rows={2}
            className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2 text-sm text-slate-700 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
            placeholder="Complete the form below. Write ONE WORD AND/OR A NUMBER for each answer."
          />
        </div>

        {/* Hint */}
        <div>
          <label className="text-xs font-medium uppercase tracking-wide text-slate-500">
            Hint (Optional)
          </label>
          <input
            type="text"
            value={question?.hint || ""}
            onChange={handleHintChange}
            className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2 text-sm text-slate-700 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
            placeholder="Write NO MORE THAN TWO WORDS and/or a number..."
          />
        </div>

        {/* Table Preview with Edit Mode */}
        <GapFillTablePreview
          question={question}
          editMode={true}
          onQuestionChange={updateQuestion}
          onOpenSpreadsheet={() => setSpreadsheetOpen(true)}
        />
      </div>

      {/* Spreadsheet Editor Modal */}
      <GapFillTableSpreadsheetEditor
        isOpen={isSpreadsheetOpen}
        table={question?.table}
        onCancel={() => setSpreadsheetOpen(false)}
        onApply={(nextTable) => {
          handleTableReplace(nextTable);
          setSpreadsheetOpen(false);
        }}
      />
    </>
  );
};

export default GapFillTableBuilder;
