import React, { useState, useRef, useCallback, useEffect } from "react";
import { motion } from "framer-motion";
import examTrackingService from '../../controller/examTrackingService';
import { readStoredProfile, resolveCandidateId } from '../../utils/candidateId';
// Shared cross-form vocabulary (CRM CreateProfileModal keeps a byte-identical copy).
// Source of truth: TheWeaverWiki/schemas/lead_intake_fields.schema.json. Drift is
// caught by `npm run check:intake-contract`.
import leadIntakeOptions from '../../constants/leadIntakeOptions.json';
import { normalizeVnPhone, isValidVnPhone, formatVnPhone } from '../../utils/phone';

const CONTAINER_VARIANTS = {
    hidden: { opacity: 0, y: 20 },
    visible: {
        opacity: 1,
        y: 0,
        transition: {
            duration: 0.6,
            staggerChildren: 0.08,
            delayChildren: 0.1,
        },
    },
};

const ITEM_VARIANTS = {
    hidden: { opacity: 0, y: 10 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.4 } },
};

const FIELD_VARIANTS = {
    hidden: { opacity: 0, y: 8 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.3 } },
};

const StudentInfo = ({ setStep }) => {
    const [formData, setFormData] = useState({
        email: '',
        fullName: '',
        dob: '',
        phone: '',
        address: '',
        learningHistory: '',
        skills: [],
        goal: '',
        otherInfo: ''
    });
    const [error, setError] = useState('');
    const [fieldErrors, setFieldErrors] = useState({});
    // Fields a `?k=` staff link prefilled (non-empty) are shown read-only for review;
    // blanks stay editable so the lead can enrich them. Shape: { fieldName: true }.
    const [lockedFields, setLockedFields] = useState({});

    const emailRef = useRef(null);
    const fullNameRef = useRef(null);
    const dobRef = useRef(null);
    const phoneRef = useRef(null);
    const debounceTimerRef = useRef(null);

    const skillOptions = leadIntakeOptions.skills;
    const goalOptions = leadIntakeOptions.goal;

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    // Locked-field helpers (staff `?k=` prefills): gray styling + a "đã điền sẵn" hint.
    const isLocked = (name) => !!lockedFields[name];
    const lockCls = (name) => isLocked(name) ? ' !bg-slate-100 !text-slate-500 !border-slate-200 cursor-not-allowed' : '';
    const lockHint = (name) => isLocked(name)
        ? <span className="ml-2 text-xs font-semibold text-slate-400">🔒 đã điền sẵn</span>
        : null;

    const validateField = useCallback((name, value) => {
        if (name === 'email') {
            if (!value.trim()) {
                return 'Hãy nhập địa chỉ email';
            }
            if (!emailRegex.test(value.trim())) {
                return 'Vui lòng nhập địa chỉ email hợp lệ';
            }
        }
        if (name === 'fullName' && !value.trim()) {
            return 'Hãy nhập họ tên học viên';
        }
        if (name === 'dob') {
            if (!value.trim()) {
                return 'Hãy nhập ngày sinh';
            }
            const dobDate = new Date(value);
            const today = new Date();
            const minDate = new Date(today.getFullYear() - 100, today.getMonth(), today.getDate());
            const maxDate = new Date(today.getFullYear() - 5, today.getMonth(), today.getDate());

            if (isNaN(dobDate.getTime())) {
                return 'Ngày sinh không hợp lệ';
            }
            if (dobDate > today) {
                return 'Ngày sinh không thể trong tương lai';
            }
            if (dobDate > maxDate) {
                return 'Bạn phải ít nhất 5 tuổi';
            }
            if (dobDate < minDate) {
                return 'Ngày sinh không hợp lệ';
            }
        }
        if (name === 'phone') {
            if (!value.trim()) {
                return 'Hãy nhập số điện thoại / Zalo';
            }
            if (!isValidVnPhone(value)) {
                return 'Số điện thoại không hợp lệ (VD: 0901234567)';
            }
        }
        return '';
    }, []);

    const debouncedValidate = useCallback((name, value) => {
        if (debounceTimerRef.current) {
            clearTimeout(debounceTimerRef.current);
        }
        debounceTimerRef.current = setTimeout(() => {
            const errorMsg = validateField(name, value);
            setFieldErrors(prev => ({
                ...prev,
                [name]: errorMsg
            }));
        }, 500);
    }, [validateField]);

    useEffect(() => {
        examTrackingService.setPhase('form');
        examTrackingService.track('formView', { view: 'studentInfo' });

        // Restore prefill profile (from shortlink) if present
        try {
            const raw = window.localStorage.getItem('weaver:candidateProfile');
            if (raw) {
                const parsed = JSON.parse(raw);
                if (parsed && typeof parsed === 'object') {
                    setFormData(prev => ({
                        ...prev,
                        email: parsed.email || prev.email,
                        fullName: parsed.fullName || parsed.name || prev.fullName,
                        dob: parsed.dob || prev.dob,
                        phone: parsed.phone || prev.phone,
                        address: parsed.address || prev.address,
                        learningHistory: parsed.learningHistory || prev.learningHistory,
                        skills: Array.isArray(parsed.skills) ? parsed.skills : prev.skills,
                        goal: parsed.goal || prev.goal,
                        otherInfo: parsed.otherInfo || prev.otherInfo,
                    }));
                    // `?k=` staff link (_lockPrefilled): lock every field the staff
                    // actually filled (non-empty) so the lead reviews but can't edit it;
                    // blanks stay open for enrichment.
                    if (parsed._lockPrefilled) {
                        const locked = {};
                        ['email', 'fullName', 'dob', 'phone', 'address', 'learningHistory', 'goal', 'otherInfo'].forEach((k) => {
                            const v = k === 'fullName' ? (parsed.fullName || parsed.name) : parsed[k];
                            if (typeof v === 'string' && v.trim()) locked[k] = true;
                        });
                        if (Array.isArray(parsed.skills) && parsed.skills.length) locked.skills = true;
                        setLockedFields(locked);
                    }
                }
            }
        } catch (e) { /* ignore */ }

        return () => {
            if (debounceTimerRef.current) {
                clearTimeout(debounceTimerRef.current);
            }
        };
    }, []);

    const handleBlur = useCallback((e) => {
        const { name, value } = e.target;
        examTrackingService.track('formBlur', { field: name });
        if (['email', 'fullName', 'dob', 'phone'].includes(name)) {
            if (debounceTimerRef.current) {
                clearTimeout(debounceTimerRef.current);
            }
            const errorMsg = validateField(name, value);
            if (errorMsg) {
                examTrackingService.track('formValidationError', { field: name, errorMsg });
            }
            setFieldErrors(prev => ({
                ...prev,
                [name]: errorMsg
            }));
        }
    }, [validateField]);

    const handleChange = (e) => {
        const { name, value, type, checked } = e.target;
        if (type === 'checkbox') {
            setFormData(prev => {
                const newSkills = checked
                    ? [...prev.skills, value]
                    : prev.skills.filter(skill => skill !== value);
                examTrackingService.track('formCheckbox', { field: 'skills', value, checked });
                return { ...prev, skills: newSkills };
            });
        } else {
            // Phone is STORED digits-only; the input renders the dotted display
            // (formatVnPhone) on its value prop. Other fields store verbatim.
            const storedValue = name === 'phone' ? normalizeVnPhone(value) : value;
            setFormData(prev => ({ ...prev, [name]: storedValue }));
            examTrackingService.trackField(name, storedValue);
            if (error) setError('');
            if (['email', 'fullName', 'dob', 'phone'].includes(name)) {
                if (!value.trim()) {
                    if (debounceTimerRef.current) {
                        clearTimeout(debounceTimerRef.current);
                    }
                    const errorMsg = validateField(name, value);
                    setFieldErrors(prev => ({
                        ...prev,
                        [name]: errorMsg
                    }));
                } else {
                    debouncedValidate(name, value);
                }
            }
        }
    };

    const handleNext = () => {
        const { fullName, email, phone, dob } = formData;

        const errors = {
            email: validateField('email', email),
            fullName: validateField('fullName', fullName),
            dob: validateField('dob', dob),
            phone: validateField('phone', phone),
        };

        setFieldErrors(errors);

        const fieldsOrder = [
            { name: 'email', ref: emailRef },
            { name: 'fullName', ref: fullNameRef },
            { name: 'dob', ref: dobRef },
            { name: 'phone', ref: phoneRef },
        ];

        const hasError = fieldsOrder.some(f => errors[f.name]);
        if (hasError) {
            examTrackingService.track('formSubmitFailed', { errors: Object.keys(errors).filter(k => errors[k]) });
            for (const field of fieldsOrder) {
                if (errors[field.name]) {
                    field.ref.current?.focus();
                    field.ref.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    setError('Vui lòng điền đầy đủ các thông tin bắt buộc (*).');
                    return;
                }
            }
        }

        // Mint/reuse a stable candidate join-key so a STANDALONE (no-prefill)
        // placement submission carries `candidate._candidateId` — the key the CRM
        // intake reconcile threads the submission to its lead by. resolveCandidateId
        // REUSES any id already in localStorage so a form re-submit / revisit never
        // splits one human into two leads; we likewise preserve an existing _source
        // (e.g. a booking lead that fell through to the form) and only tag genuine
        // walk-ins as 'standalone'.
        const storedProfile = readStoredProfile();
        const profile = {
            ...formData,
            startedAt: Date.now(),
            _candidateId: resolveCandidateId(),
            _source: (storedProfile && storedProfile._source) || 'standalone',
        };

        examTrackingService.init(profile, 'placement-test');
        examTrackingService.track('formSubmit', {
            hasAddress: !!formData.address,
            hasGoal: !!formData.goal,
            skillsCount: formData.skills.length,
        });

        try {
            window.localStorage.setItem('weaver:candidateProfile', JSON.stringify(profile));
        } catch (err) {
            console.warn('Unable to persist candidate profile', err);
        }

        setError('');
        setStep(prev => prev + 1);
    };

    const handleKeyDown = (e) => {
        if (e.key === 'Enter' && e.target.type !== 'textarea') {
            e.preventDefault();
        }
    };


    return (
        <div className="relative w-full min-h-screen overflow-hidden bg-[#f8fafc] font-lexend">
            {/* Background Ambiance Orbs */}
            <div className="absolute inset-0 overflow-hidden pointer-events-none">
                <div className="absolute -top-[10%] -left-[10%] w-[40rem] h-[40rem] rounded-full bg-orange-200/50 mix-blend-multiply blur-[120px] animate-[pulse_8s_ease-in-out_infinite]" />
                <div className="absolute top-[20%] -right-[10%] w-[35rem] h-[35rem] rounded-full bg-amber-200/40 mix-blend-multiply blur-[120px] animate-[pulse_10s_ease-in-out_infinite_reverse]" />
                <div className="absolute -bottom-[10%] left-[20%] w-[40rem] h-[40rem] rounded-full bg-orange-100/60 mix-blend-multiply blur-[120px] animate-[pulse_12s_ease-in-out_infinite]" />
            </div>

            <motion.div
                className="relative z-10 w-full max-w-4xl mx-auto py-8 px-4"
                variants={CONTAINER_VARIANTS}
                initial="hidden"
                animate="visible"
            >
                {/* Header Section */}
                <motion.div
                    variants={ITEM_VARIANTS}
                    className="mb-10"
                >
                    <div className="bg-white/70 backdrop-blur-3xl rounded-[2.5rem] shadow-[0_8px_30px_rgb(251,146,60,0.06)] border border-white/80 overflow-hidden relative">
                        <div className="absolute top-0 left-0 right-0 h-2 bg-gradient-to-r from-orange-300 via-orange-500 to-amber-400" />
                        <div className="px-8 py-12 md:px-12">
                            <h1 className="font-outfit text-4xl md:text-5xl font-extrabold tracking-tight text-slate-800 mb-4">
                                Kiểm tra đầu vào
                            </h1>
                            <p className="text-slate-600 text-base md:text-lg leading-relaxed max-w-2xl">
                                Trước khi bắt đầu, điền nhanh vài thông tin để WEAVER chuẩn bị tốt hơn cho bạn nhé!
                            </p>
                        </div>
                    </div>
                </motion.div>

                {/* Prefilled-by-staff review banner (?k= short link) */}
                {Object.keys(lockedFields).length > 0 && (
                    <motion.div variants={ITEM_VARIANTS} className="mb-8 flex items-start gap-3 bg-orange-50/80 border border-orange-200 rounded-2xl px-6 py-4">
                        <span className="text-xl leading-none mt-0.5">🔒</span>
                        <p className="text-slate-700 text-sm font-medium leading-relaxed">
                            Một số thông tin đã được trung tâm điền sẵn (các ô màu xám) — bạn chỉ cần kiểm tra lại.
                            Hãy bổ sung các ô còn trống nếu muốn, rồi bắt đầu làm bài nhé!
                        </p>
                    </motion.div>
                )}

                {/* Personal Information Section */}
                <motion.div variants={ITEM_VARIANTS} className="mb-10">
                    <div className="flex items-center justify-between mb-6 px-2 gap-6">
                        <div className="flex items-center space-x-3">
                            <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-orange-400 to-amber-500 flex items-center justify-center text-white shadow-lg shadow-orange-500/30">
                                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
                                </svg>
                            </div>
                            <h2 className="font-outfit text-2xl font-bold text-slate-800">
                                Thông tin cá nhân
                            </h2>
                        </div>
                        <div className="inline-flex items-center bg-orange-50/80 px-5 py-2.5 rounded-2xl border border-orange-100/50 shadow-sm whitespace-nowrap">
                            <p className="text-orange-700 text-sm font-bold tracking-tight">
                                Các ô có dấu <span className="text-orange-500 text-lg mx-1 align-middle">✦</span> là bắt buộc
                            </p>
                        </div>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                        {/* Email */}
                        <motion.div variants={FIELD_VARIANTS} className={`bg-white/50 backdrop-blur-xl rounded-2xl shadow-sm border transition-all duration-300 hover:shadow-md hover:bg-white/80 p-6 ${fieldErrors.email ? 'border-red-400' : 'border-white/80'}`}>
                            <label className="block text-sm font-bold text-slate-700 mb-2">
                                Email <span className="text-orange-500 ml-1">✦</span>{lockHint('email')}
                            </label>
                            <input
                                ref={emailRef}
                                type="email"
                                name="email"
                                value={formData.email}
                                onChange={handleChange}
                                onBlur={handleBlur}
                                onKeyDown={handleKeyDown}
                                disabled={isLocked('email')}
                                className={`w-full px-4 py-3.5 rounded-xl border-2 transition-all outline-none font-lexend text-base bg-white/50 focus:bg-white ${fieldErrors.email ? 'border-red-400 focus:ring-4 focus:ring-red-100' : 'border-slate-200/60 focus:border-orange-500 focus:ring-4 focus:ring-orange-500/10'}${lockCls('email')}`}
                                placeholder="example@email.com"
                            />
                            {fieldErrors.email && (
                                <motion.p initial={{ opacity: 0, y: -5 }} animate={{ opacity: 1, y: 0 }} className="text-red-500 text-sm mt-2 flex items-center font-medium">
                                    <span className="mr-1.5">•</span> {fieldErrors.email}
                                </motion.p>
                            )}
                        </motion.div>

                        {/* Full Name */}
                        <motion.div variants={FIELD_VARIANTS} className={`bg-white/50 backdrop-blur-xl rounded-2xl shadow-sm border transition-all duration-300 hover:shadow-md hover:bg-white/80 p-6 ${fieldErrors.fullName ? 'border-red-400' : 'border-white/80'}`}>
                            <label className="block text-sm font-bold text-slate-700 mb-2">
                                Họ tên học viên <span className="text-orange-500 ml-1">✦</span>{lockHint('fullName')}
                            </label>
                            <input
                                ref={fullNameRef}
                                type="text"
                                name="fullName"
                                value={formData.fullName}
                                onChange={handleChange}
                                onBlur={handleBlur}
                                onKeyDown={handleKeyDown}
                                disabled={isLocked('fullName')}
                                className={`w-full px-4 py-3.5 rounded-xl border-2 transition-all outline-none font-lexend text-base bg-white/50 focus:bg-white ${fieldErrors.fullName ? 'border-red-400 focus:ring-4 focus:ring-red-100' : 'border-slate-200/60 focus:border-orange-500 focus:ring-4 focus:ring-orange-500/10'}${lockCls('fullName')}`}
                                placeholder="VD: Nguyễn Văn A"
                            />
                            {fieldErrors.fullName && (
                                <motion.p initial={{ opacity: 0, y: -5 }} animate={{ opacity: 1, y: 0 }} className="text-red-500 text-sm mt-2 flex items-center font-medium">
                                    <span className="mr-1.5">•</span> {fieldErrors.fullName}
                                </motion.p>
                            )}
                        </motion.div>

                        {/* Date of Birth */}
                        <motion.div variants={FIELD_VARIANTS} className={`bg-white/50 backdrop-blur-xl rounded-2xl shadow-sm border transition-all duration-300 hover:shadow-md hover:bg-white/80 p-6 ${fieldErrors.dob ? 'border-red-400' : 'border-white/80'}`}>
                            <label className="block text-sm font-bold text-slate-700 mb-2">
                                Ngày sinh <span className="text-orange-500 ml-1">✦</span>{lockHint('dob')}
                            </label>
                            <input
                                ref={dobRef}
                                type="date"
                                name="dob"
                                value={formData.dob}
                                onChange={handleChange}
                                onBlur={handleBlur}
                                onKeyDown={handleKeyDown}
                                disabled={isLocked('dob')}
                                className={`w-full px-4 py-3.5 rounded-xl border-2 transition-all outline-none font-lexend text-base bg-white/50 focus:bg-white ${fieldErrors.dob ? 'border-red-400 focus:ring-4 focus:ring-red-100' : 'border-slate-200/60 focus:border-orange-500 focus:ring-4 focus:ring-orange-500/10'}${lockCls('dob')}`}
                            />
                            {fieldErrors.dob && (
                                <motion.p initial={{ opacity: 0, y: -5 }} animate={{ opacity: 1, y: 0 }} className="text-red-500 text-sm mt-2 flex items-center font-medium">
                                    <span className="mr-1.5">•</span> {fieldErrors.dob}
                                </motion.p>
                            )}
                        </motion.div>

                        {/* Phone */}
                        <motion.div variants={FIELD_VARIANTS} className={`bg-white/50 backdrop-blur-xl rounded-2xl shadow-sm border transition-all duration-300 hover:shadow-md hover:bg-white/80 p-6 ${fieldErrors.phone ? 'border-red-400' : 'border-white/80'}`}>
                            <label className="block text-sm font-bold text-slate-700 mb-2">
                                Số điện thoại/ Zalo <span className="text-orange-500 ml-1">✦</span>{lockHint('phone')}
                            </label>
                            <input
                                ref={phoneRef}
                                type="tel"
                                name="phone"
                                value={formatVnPhone(formData.phone)}
                                onChange={handleChange}
                                onBlur={handleBlur}
                                onKeyDown={handleKeyDown}
                                disabled={isLocked('phone')}
                                className={`w-full px-4 py-3.5 rounded-xl border-2 transition-all outline-none font-lexend text-base bg-white/50 focus:bg-white ${fieldErrors.phone ? 'border-red-400 focus:ring-4 focus:ring-red-100' : 'border-slate-200/60 focus:border-orange-500 focus:ring-4 focus:ring-orange-500/10'}${lockCls('phone')}`}
                                placeholder="0901234567"
                            />
                            {fieldErrors.phone && (
                                <motion.p initial={{ opacity: 0, y: -5 }} animate={{ opacity: 1, y: 0 }} className="text-red-500 text-sm mt-2 flex items-center font-medium">
                                    <span className="mr-1.5">•</span> {fieldErrors.phone}
                                </motion.p>
                            )}
                        </motion.div>
                    </div>
                </motion.div>

                {/* Learning Profile Section */}
                <motion.div variants={ITEM_VARIANTS} className="mb-12">
                    <div className="flex items-center space-x-3 mb-6 px-2">
                        <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-amber-400 to-orange-500 flex items-center justify-center text-white shadow-lg shadow-amber-500/30">
                            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
                            </svg>
                        </div>
                        <h2 className="font-outfit text-2xl font-bold text-slate-800">
                            Hồ sơ học tập
                        </h2>
                    </div>
                    <div className="space-y-5">
                        {/* Address */}
                        <motion.div variants={FIELD_VARIANTS} className="bg-white/50 backdrop-blur-xl rounded-2xl shadow-sm border border-white/80 transition-all duration-300 hover:shadow-md hover:bg-white/80 p-6">
                            <label className="block text-sm font-bold text-slate-700 mb-2">
                                Địa chỉ (Quận/Thành phố){lockHint('address')}
                            </label>
                            <input
                                type="text"
                                name="address"
                                value={formData.address}
                                onChange={handleChange}
                                onKeyDown={handleKeyDown}
                                disabled={isLocked('address')}
                                className={`w-full px-4 py-3.5 rounded-xl border-2 border-slate-200/60 focus:border-orange-500 focus:ring-4 focus:ring-orange-500/10 outline-none font-lexend text-base bg-white/50 focus:bg-white transition-all${lockCls('address')}`}
                                placeholder="Nhập địa chỉ của bạn"
                            />
                        </motion.div>

                        {/* Learning History */}
                        <motion.div variants={FIELD_VARIANTS} className="bg-white/50 backdrop-blur-xl rounded-2xl shadow-sm border border-white/80 transition-all duration-300 hover:shadow-md hover:bg-white/80 p-6">
                            <label className="block text-sm font-bold text-slate-700 mb-2">
                                Bạn đã học tiếng Anh khi nào và trong bao lâu?{lockHint('learningHistory')}
                            </label>
                            <textarea
                                name="learningHistory"
                                value={formData.learningHistory}
                                onChange={handleChange}
                                disabled={isLocked('learningHistory')}
                                className={`w-full px-4 py-3.5 rounded-xl border-2 border-slate-200/60 focus:border-orange-500 focus:ring-4 focus:ring-orange-500/10 outline-none font-lexend text-base bg-white/50 focus:bg-white resize-none overflow-hidden transition-all${lockCls('learningHistory')}`}
                                placeholder="Tóm tắt ngắn gọn quá trình học của bạn"
                                rows={1}
                                onInput={(e) => {
                                    e.target.style.height = 'auto';
                                    e.target.style.height = e.target.scrollHeight + 'px';
                                }}
                            />
                        </motion.div>

                        {/* Skills */}
                        <motion.div variants={FIELD_VARIANTS} className="bg-white/50 backdrop-blur-xl rounded-2xl shadow-sm border border-white/80 transition-all duration-300 hover:shadow-md hover:bg-white/80 p-6">
                            <label className="block text-sm font-bold text-slate-700 mb-4">
                                Kỹ năng bạn quan tâm (<span className="font-normal text-slate-500">có thể chọn nhiều</span>){lockHint('skills')}
                            </label>
                            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
                                {skillOptions.map((skill) => (
                                    <label key={skill} className={`flex items-center p-3 rounded-xl border-2 border-slate-100 bg-white/40 group transition-all duration-200 has-[:checked]:border-orange-500 has-[:checked]:bg-orange-50/50 ${isLocked('skills') ? 'opacity-70 cursor-not-allowed' : 'hover:bg-white hover:border-orange-200 cursor-pointer'}`}>
                                        <div className="relative flex items-center mr-3">
                                            <input
                                                type="checkbox"
                                                name="skills"
                                                value={skill}
                                                checked={formData.skills.includes(skill)}
                                                onChange={handleChange}
                                                disabled={isLocked('skills')}
                                                className={`peer h-5 w-5 appearance-none rounded-md border-2 border-slate-300 checked:border-orange-500 checked:bg-orange-500 transition-all ${isLocked('skills') ? 'cursor-not-allowed' : 'cursor-pointer'}`}
                                            />
                                            <svg className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-3.5 h-3.5 pointer-events-none opacity-0 peer-checked:opacity-100 text-white" viewBox="0 0 14 14" fill="none">
                                                <path d="M3 8L6 11L11 3.5" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
                                            </svg>
                                        </div>
                                        <span className="text-slate-700 group-hover:text-slate-900 font-medium text-sm select-none">{skill}</span>
                                    </label>
                                ))}
                            </div>
                        </motion.div>

                        {/* Goal */}
                        <motion.div variants={FIELD_VARIANTS} className="bg-white/50 backdrop-blur-xl rounded-2xl shadow-sm border border-white/80 transition-all duration-300 hover:shadow-md hover:bg-white/80 p-6">
                            <label className="block text-sm font-bold text-slate-700 mb-2">
                                Mục tiêu khóa học{lockHint('goal')}
                            </label>
                            <div className="relative">
                                <select
                                    name="goal"
                                    value={formData.goal}
                                    onChange={handleChange}
                                    disabled={isLocked('goal')}
                                    className={`w-full px-4 py-3.5 rounded-xl border-2 border-slate-200/60 focus:border-orange-500 focus:ring-4 focus:ring-orange-500/10 outline-none bg-white/50 focus:bg-white appearance-none transition-all font-lexend text-base text-slate-700 ${isLocked('goal') ? '!bg-slate-100 !text-slate-500 cursor-not-allowed' : 'cursor-pointer'}`}
                                >
                                    <option value="" disabled className="text-slate-400">Chọn mục tiêu của bạn</option>
                                    {goalOptions.map((option) => (
                                        <option key={option} value={option} className="text-slate-800">
                                            {option}
                                        </option>
                                    ))}
                                </select>
                                <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-4 text-slate-400">
                                    <svg className="fill-current h-5 w-5" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20">
                                        <path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" />
                                    </svg>
                                </div>
                            </div>
                        </motion.div>

                        {/* Other Info */}
                        <motion.div variants={FIELD_VARIANTS} className="bg-white/50 backdrop-blur-xl rounded-2xl shadow-sm border border-white/80 transition-all duration-300 hover:shadow-md hover:bg-white/80 p-6">
                            <label className="block text-sm font-bold text-slate-700 mb-2">
                                Thông tin khác{lockHint('otherInfo')}
                            </label>
                            <input
                                type="text"
                                name="otherInfo"
                                value={formData.otherInfo}
                                onChange={handleChange}
                                onKeyDown={handleKeyDown}
                                disabled={isLocked('otherInfo')}
                                className={`w-full px-4 py-3.5 rounded-xl border-2 border-slate-200/60 focus:border-orange-500 focus:ring-4 focus:ring-orange-500/10 outline-none font-lexend text-base bg-white/50 focus:bg-white transition-all${lockCls('otherInfo')}`}
                                placeholder="Ghi chú thêm (nếu có)"
                            />
                        </motion.div>
                    </div>
                </motion.div>

                {/* Error Message */}
                {error && (
                    <motion.div
                        initial={{ opacity: 0, y: -10, scale: 0.98 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        className="bg-red-50/90 backdrop-blur-sm border border-red-200 text-red-700 p-4 rounded-xl mb-8 shadow-sm flex items-center space-x-3"
                    >
                        <svg className="w-6 h-6 text-red-500 flex-shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                        </svg>
                        <p className="font-semibold text-sm">{error}</p>
                    </motion.div>
                )}

                {/* Actions */}
                <motion.div variants={ITEM_VARIANTS} className="flex flex-col-reverse sm:flex-row gap-4 justify-between items-center py-4 px-2">
                    <motion.button
                        onClick={() => setFormData(prev => {
                            const blank = { email: '', fullName: '', dob: '', phone: '', address: '', learningHistory: '', skills: [], goal: '', otherInfo: '' };
                            // Keep staff-locked (prefilled) fields; only clear what the lead can edit.
                            Object.keys(lockedFields).forEach((k) => { if (lockedFields[k]) blank[k] = prev[k]; });
                            return blank;
                        })}
                        whileHover={{ scale: 1.02 }}
                        whileTap={{ scale: 0.98 }}
                        className="w-full sm:w-auto text-slate-500 font-semibold hover:text-slate-800 hover:bg-slate-200/50 px-8 py-3.5 rounded-xl transition-all"
                    >
                        Xóa thông tin
                    </motion.button>
                    <motion.button
                        onClick={handleNext}
                        whileHover={{ scale: 1.02, y: -2 }}
                        whileTap={{ scale: 0.98 }}
                        className="w-full sm:w-auto bg-gradient-to-r from-orange-500 to-orange-600 hover:from-orange-600 hover:to-orange-700 text-white px-10 py-4 rounded-2xl shadow-[0_12px_25px_rgb(249,115,22,0.3)] hover:shadow-[0_15px_30px_rgb(249,115,22,0.4)] transition-all font-bold tracking-wide text-lg border border-white/10"
                    >
                        Bắt đầu làm bài
                    </motion.button>
                </motion.div>

            </motion.div>
        </div>
    );
};

export default StudentInfo;
