export const getCandidateProfile = () => {
  try {
    const raw = window.localStorage.getItem("weaver:candidateProfile");
    return raw ? JSON.parse(raw) : null;
  } catch (error) {
    console.warn("Unable to read candidate profile", error);
    return null;
  }
};

// Replace undefined, NaN, or unsupported types with null recursively to satisfy Firestore constraints
export const sanitizeForFirestore = (value) => {
  if (value === undefined) return null;
  if (value === null) return null;
  if (typeof value === 'number' && Number.isNaN(value)) return null;
  if (typeof value !== 'object') return value;
  // Guard against Blob/File objects, ArrayBuffer, and other non-plain objects
  try {
    if (typeof Blob !== 'undefined' && value instanceof Blob) return null;
  } catch (e) { }
  if (Array.isArray(value)) {
    // Use Array.from to ensure sparse arrays (holes) are iterated and converted to nulls
    return Array.from(value).map((item) => sanitizeForFirestore(item));
  }
  // Only sanitize plain objects to avoid touching Firestore field values or refs
  if (value && value.constructor !== Object) {
    return value;
  }
  const newObj = {};
  for (const key in value) {
    if (Object.prototype.hasOwnProperty.call(value, key)) {
      newObj[key] = sanitizeForFirestore(value[key]);
    }
  }
  return newObj;
};
