export const DEFAULT_CHOICE_OPTIONS = [
  { label: "Option A", value: "A" },
  { label: "Option B", value: "B" },
];

export const cloneDefaultOptions = (options = DEFAULT_CHOICE_OPTIONS) =>
  options.map((option) => ({ ...option }));

export const formatAnswerList = (answers) => {
  if (!Array.isArray(answers)) return "";
  return answers.join(" | ");
};

export const parseAnswerList = (value) => {
  if (!value) return [];
  return value
    .split("|")
    .map((item) => item.trim())
    .filter(Boolean);
};
