import { countGapSlots } from "./gapFilling";
import { countGapFillTableSlots } from "./gapFillTable";

export const getQuestionSlotCount = (question = {}) => {
  const type = question?.type;

  switch (type) {
    case "gap-filling":
    case "notes-completion":
    case "short-answer":
    case "summary-completion": {
      return countGapSlots(question);
    }
    case "complete-sentences":
    case "true-false-not-given":
    case "yes-no-not-given":
    case "fill-in-the-blanks":
    case "inline-blank": {
      const subQuestionCount = Array.isArray(question.subQuestions)
        ? question.subQuestions.filter(sq => !sq.isExample).length
        : 0;
      return Math.max(subQuestionCount, 1);
    }
    case "checkbox":
    case "multiple-choice": {
      // Check subQuestions first (for passage-based multiple-choice from AI)
      const subQuestionCount = Array.isArray(question.subQuestions)
        ? question.subQuestions.length
        : 0;
      if (subQuestionCount > 0) {
        return subQuestionCount;
      }

      // Fallback to correctAnswers (for standalone multiple-choice)
      const answerCount = Array.isArray(question.correctAnswers)
        ? question.correctAnswers.length
        : 0;
      return Math.max(answerCount, 1);
    }
    case "gap-fill-table": {
      return countGapFillTableSlots(question);
    }
    case "which-true": {
      const itemCount = Array.isArray(question.whichTrueItems)
        ? question.whichTrueItems.length
        : 0;
      return Math.max(itemCount, 1);
    }
    case "matching-headings": {
      const itemCount = Array.isArray(question.matchingHeadingItems)
        ? question.matchingHeadingItems.length
        : 0;
      return Math.max(itemCount, 1);
    }
    case "correction": {
      return question.numberOfErrors || (Array.isArray(question.correctAnswers) ? question.correctAnswers.length : 1);
    }
    case "underline": {
      // SubQuestions mode: count non-example subQuestions
      if (Array.isArray(question.subQuestions) && question.subQuestions.length > 0) {
        return question.subQuestions.filter(sq => !sq.isExample).length;
      }
      // Flat mode: numberOfSelections or correctAnswers length
      return question.numberOfSelections || (Array.isArray(question.correctAnswers) ? question.correctAnswers.length : 1);
    }
    default:
      return 1;
  }
};

export const accumulateQuestionSlots = (questions = []) => {
  let total = 0;
  questions.forEach((question) => {
    total += getQuestionSlotCount(question);
  });
  return total;
};
