import React, { useMemo, useContext } from "react";
import { parseGapContent } from "../../../utils/question/gapFilling";
import RegradeContext from "../../../contexts/RegradeContext";
import AnswerKeyEditor from "../_shared/AnswerKeyEditor";
import { normalizeAnswer, matchesAnswer } from "../../../utils/normalizeAnswer";

const parseInteger = (value) => {
  const parsed = Number.parseInt(value, 10);
  return Number.isFinite(parsed) ? parsed : null;
};

const GapFillingPreview = ({
  question,
  value,
  onChange,
  disabled = false,
  reviewMode = false,
  correctAnswers = [],
  name,
  questionNumber = 1,
  sectionKey = '',
}) => {
  const startingNumber = useMemo(() => {
    const raw = String(questionNumber ?? "");
    const numericMatch = raw.match(/\d+/);
    if (!numericMatch) {
      return 1;
    }
    const parsed = Number.parseInt(numericMatch[0], 10);
    return Number.isFinite(parsed) ? parsed : 1;
  }, [questionNumber]);

  const content = question?.content || "";
  const { normalizedContent, placeholders } = useMemo(
    () => parseGapContent(content),
    [content]
  );

  const baseSubQuestions = useMemo(() => Array.isArray(question?.subQuestions)
    ? question.subQuestions
    : [], [question?.subQuestions]);
  const baseCorrectAnswers = useMemo(() => Array.isArray(question?.correctAnswers)
    ? question.correctAnswers
    : [], [question?.correctAnswers]);
  const supplementalCorrectAnswers = useMemo(() => Array.isArray(correctAnswers)
    ? correctAnswers
    : [], [correctAnswers]);

  const gapCount = useMemo(
    () =>
      Math.max(
        placeholders.length,
        baseSubQuestions.length,
        baseCorrectAnswers.length,
        supplementalCorrectAnswers.length
      ),
    [placeholders.length, baseSubQuestions.length, baseCorrectAnswers.length, supplementalCorrectAnswers.length]
  );

  const normalizedUserAnswers = useMemo(() => {
    const base = Array.isArray(value) ? [...value] : [];
    if (base.length > gapCount) {
      base.length = gapCount;
    }
    while (base.length < gapCount) {
      base.push("");
    }
    return base;
  }, [value, gapCount]);

  const previewCorrectAnswers = useMemo(() =>
    Array.from({ length: gapCount }).map((_, index) => {
      if (supplementalCorrectAnswers[index] !== undefined) {
        return supplementalCorrectAnswers[index];
      }
      if (baseCorrectAnswers[index] !== undefined) {
        return baseCorrectAnswers[index];
      }
      const subQuestion = baseSubQuestions[index];
      if (subQuestion?.correctAnswers?.length) {
        return subQuestion.correctAnswers[0];
      }
      return "";
    }),
    [supplementalCorrectAnswers, baseCorrectAnswers, baseSubQuestions, gapCount]
  );

  const gapDescriptors = useMemo(
    () =>
      Array.from({ length: gapCount }).map((_, index) => {
        const placeholder = placeholders[index];
        const subQuestion = baseSubQuestions[index];

        // displayNumber is now passed via props or calculated here.
        // For GapFilling, we typically follow startingNumber + offset, 
        // but we must account for isGrouped skipping increments.
        // However, a simpler way in Preview is just use startingNumber + index
        // BUT override with subQuestion.isGrouped logic.

        let displayNumber = startingNumber + index;
        // Adjust for grouping: find how many IS_GROUPED subquestions are before this one
        const groupedBefore = baseSubQuestions.slice(0, index).filter(sq => sq?.isGrouped).length;
        displayNumber -= groupedBefore;

        const explicitNumber = parseInteger(subQuestion?.gapIndex);
        if (Number.isFinite(explicitNumber)) {
          displayNumber = explicitNumber;
        }

        return {
          displayNumber,
          slotId: subQuestion?.id || placeholder?.token || `gap-${index}`,
          slotIndex: index,
          isGrouped: !!subQuestion?.isGrouped,
        };
      }),
    [gapCount, placeholders, baseSubQuestions, startingNumber]
  );
  const { isRegrade, setKeyEdit } = useContext(RegradeContext);

  if (!question) {
    return null;
  }

  if (gapCount === 0) {
    return (
      <div className="rounded border border-dashed border-slate-300 bg-slate-50 px-3 py-2 text-sm text-slate-500">
        Add gaps to this question to preview.
      </div>
    );
  }

  const isInteractive = typeof onChange === "function";

  const handleAnswerChange = (subQuestionIndex, answer) => {
    if (!isInteractive || disabled || (reviewMode)) return;

    const nextAnswers = normalizedUserAnswers.slice();
    nextAnswers[subQuestionIndex] = answer;
    onChange(nextAnswers);
  };

  const parseHtmlToReact = (htmlString) => {
    if (!htmlString) return null;

    const parser = new DOMParser();
    const doc = parser.parseFromString(htmlString, "text/html");
    const container = doc.body;

    let globalGapIndex = 0;

    const traverse = (node, keyPrefix) => {
      if (node.nodeType === Node.TEXT_NODE) {
        const text = node.textContent;
        const parts = text.split(/(__GAP_\d+__)/);

        if (parts.length === 1) {
          return text;
        }

        return parts.map((part, index) => {
          const gapMatch = part.match(/__GAP_(\d+)__/);
          if (gapMatch) {
            // We use the sequence order of appearance for the gap index, 
            // verifying it matches the token if possible, but consistently 
            // using the traversal counter to map to the correct gap descriptor.
            // Note: parseGapContent assigns tokens __GAP_0__, __GAP_1__ sequentially.
            // Our traversal should encounter them in the same order.

            const gapIndex = globalGapIndex++;
            const descriptor = gapDescriptors[gapIndex]; // Use the pre-calculated descriptors

            // Fallback if descriptor is missing (should not happen if counts match)
            if (!descriptor) return null;

            const answerNumber = descriptor.displayNumber;
            const answerIndex = descriptor.slotIndex;
            const userAnswer = normalizedUserAnswers[answerIndex] || "";
            const normalizedUserAnswer = normalizeAnswer(userAnswer);
            const rawCorrectAnswer = previewCorrectAnswers[answerIndex];

            // Use the shared matcher so the review-mode green/red painting
            // matches exactly what examScoring.js (and the CF grader) accept.
            // expandAcceptableAnswers handles "/" + "|" + bracket variants, so
            // keys like "(£) 115 / a/one hundred (and) fifteen" or
            // "decoration / decorations" mark "115"/"decoration" as correct.
            const hasKey = Array.isArray(rawCorrectAnswer)
              ? rawCorrectAnswer.length > 0
              : rawCorrectAnswer !== null && rawCorrectAnswer !== undefined && rawCorrectAnswer !== '';

            const isCorrect = reviewMode && hasKey
              ? matchesAnswer(userAnswer, rawCorrectAnswer)
              : false;
            const isIncorrect =
              reviewMode &&
              hasKey &&
              normalizedUserAnswer &&
              !isCorrect;

            const effectiveSubQuestion = baseSubQuestions[answerIndex];
            const options = effectiveSubQuestion?.options || question?.options;

            const isSelectBox = Array.isArray(options) && options.length > 0;

            const baseInputClass =
              "min-w-[120px] inline-block border-x-0 border-t-0 border-b border-dashed border-black bg-transparent px-1 py-0 text-sm leading-none font-medium text-blue-900 focus:outline-none focus:border-blue-500 align-baseline transition-colors translate-y-[-2px]";

            // Styles for select box
            const selectClass =
              "min-w-[50px] max-w-[80px] inline-block border border-gray-300 rounded-sm bg-white px-1 py-0 h-[24px] text-xs focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 align-middle cursor-pointer shadow-sm leading-none truncate";

            const disabledClass =
              disabled || (reviewMode) || !isInteractive
                ? "cursor-not-allowed opacity-80 bg-gray-50"
                : "";

            const reviewStateClass = reviewMode
              ? isCorrect
                ? "border-green-500 text-green-700 bg-green-50"
                : isIncorrect
                  ? "border-red-500 text-red-700 bg-red-50"
                  : "border-gray-300 text-slate-800"
              : "border-gray-300 text-slate-800";

            return (
              <span
                key={`${keyPrefix}-gap-${gapIndex}`}
                data-answer-blank
                className="inline-flex items-center gap-1 mx-1 align-baseline"
              >
                {!descriptor.isGrouped && (
                  <span className="inline-flex h-5 w-5 flex-shrink-0 items-center justify-center rounded-full border border-orange-200 bg-orange-50 text-[10px] font-bold text-orange-600 align-middle mx-1">
                    {answerNumber}
                  </span>
                )}
                {isSelectBox ? (
                  <select
                    value={userAnswer}
                    onChange={(event) =>
                      handleAnswerChange(answerIndex, event.target.value)
                    }
                    disabled={disabled || (reviewMode) || !isInteractive}
                    className={`${selectClass} ${disabledClass} ${reviewStateClass}`}
                    title="Select answer"
                  >
                    <option value="">Select...</option>
                    {options.map((opt) => {
                      const optValue = typeof opt === 'object' ? opt.value : opt;
                      const optLabel = typeof opt === 'object' ? opt.label : opt;

                      // For Matching questions (Value is A-Z, Label is long text), 
                      // show ONLY the letter to keep the box compact.
                      // The full text is visible in the option list below.
                      const isMatchingLetter = typeof optValue === 'string' && /^[A-Z]$/.test(optValue) && optLabel && optLabel !== optValue;

                      const displayLabel = isMatchingLetter
                        ? optValue
                        : (typeof opt === 'object' && opt.label ? opt.label : opt);

                      return (
                        <option key={optValue} value={optValue}>
                          {displayLabel}
                        </option>
                      );
                    })}
                  </select>
                ) : (
                  <input
                    type="text"
                    value={userAnswer}
                    onChange={(event) =>
                      handleAnswerChange(answerIndex, event.target.value)
                    }
                    disabled={disabled || (reviewMode) || !isInteractive}
                    data-testid={`gap-filling-input-${answerNumber}`}
                    data-question-slot-index={answerIndex}
                    data-question-slot-number={answerNumber}
                    className={`${baseInputClass} ${disabledClass} ${reviewStateClass}`}
                    placeholder=""
                  />
                )}
              </span>
            );
          }
          return (
            <span key={`${keyPrefix}-text-${index}`}>{part}</span>
          );
        });
      }

      if (node.nodeType === Node.ELEMENT_NODE) {
        const tagName = node.tagName.toLowerCase();
        const attributes = {};
        for (const attr of node.attributes) {
          // Convert standard HTML attributes to React
          const name = attr.name === 'class' ? 'className' : attr.name;
          // Simplified handling: mostly just passing styles and classes
          attributes[name] = attr.value;
        }
        // Handle style string to object if necessary usually react expects style object, 
        // but simple pass might warn. Ideally we parse style string. 
        // For now, let's omit style parsing or assume basic handling.
        // Actually, style attribute in React must be an object.
        if (attributes.style) {
          const styleJson = {};
          attributes.style.split(';').forEach(rule => {
            const [prop, val] = rule.split(':');
            if (prop && val) {
              const camelProp = prop.trim().replace(/-([a-z])/g, g => g[1].toUpperCase());
              styleJson[camelProp] = val.trim();
            }
          });
          attributes.style = styleJson;
        }

        const VOID_ELEMENTS = new Set([
          'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
          'link', 'meta', 'param', 'source', 'track', 'wbr'
        ]);

        if (VOID_ELEMENTS.has(tagName)) {
          return React.createElement(
            tagName,
            { key: `${keyPrefix}-el`, ...attributes }
          );
        }

        return React.createElement(
          tagName,
          { key: `${keyPrefix}-el`, ...attributes },
          Array.from(node.childNodes).map((child, i) => traverse(child, `${keyPrefix}-${i}`))
        );
      }
      return null;
    };

    return traverse(container, 'root');
  };

  const renderContentWithGaps = () => {
    if (!normalizedContent) return null;
    // Reset global index for each render
    // Since parseHtmlToReact is called inside render, it's fine.
    // However, React strict mode might invoke render twice, but that's just side-effect check.
    // The traversal relies on order which is deterministic.
    return parseHtmlToReact(normalizedContent);
  };

  return (
    <div className="space-y-4">
      <div
        className="prose max-w-none text-slate-700 rich-text-content"
        style={{ fontSize: '14px', lineHeight: '1.8' }}
      >
        {renderContentWithGaps()}
      </div>

      {isRegrade && reviewMode && (
        <AnswerKeyEditor
          correctAnswers={question.correctAnswers}
          questionType={question.type}
          onChange={(patch) => setKeyEdit(sectionKey, question.id, patch)}
        />
      )}

      {question?.options && Array.isArray(question.options) && question.options.length > 0 && (
        <div className="mt-4 p-4 bg-orange-50/30 border border-orange-100 rounded-lg">
          <h4 className="text-sm font-semibold text-slate-700 mb-3 border-b border-orange-200 pb-1">
            List of options
          </h4>
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3 text-sm">
            {question.options.map((opt, i) => {
              const val = typeof opt === 'object' ? opt.value : opt;
              const label = typeof opt === 'object' ? opt.label : opt;
              const isDiff = val !== label;
              return (
                <div key={i} className="flex flex-col sm:flex-row gap-1 sm:gap-2 items-start sm:items-center">
                  <span className="font-bold text-orange-700 bg-white border border-orange-200 px-1.5 rounded text-xs leading-5 h-5 flex items-center justify-center min-w-[1.5rem]">
                    {val}
                  </span>
                  <span className="text-slate-700 leading-snug break-words">
                    {isDiff ? label : ''}
                  </span>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
};

export default GapFillingPreview;
