/**
 * Canonical VN-mobile intake contract — SHARED across all three lead-intake forms.
 * Keep byte-identical with WeaverCRM_NEW/frontend/src/utils/format.ts and the wiki
 * schema (TheWeaverWiki/schemas/lead_intake_fields.schema.json#phoneContract). The
 * contract test (`npm run check:intake-contract`) scans for these so a drift in one
 * repo turns CI red.
 *
 * STORAGE form is digits-only ('0901234567') — never store the spaced display value.
 * The spaces are cosmetic, applied at render via formatVnPhone.
 */
export const VN_PHONE_RE = /^0[0-9]{9}$/;

/** Normalize any user input to the canonical STORED form: digits only, max 10, no
 *  separators. This is what every form sends and what the lead doc stores. */
export const normalizeVnPhone = (value) => (value || '').replace(/\D/g, '').slice(0, 10);

/** Valid iff the normalized value is a 10-digit VN mobile starting with 0. */
export const isValidVnPhone = (value) => VN_PHONE_RE.test(normalizeVnPhone(value));

/** DISPLAY ONLY: XXXX XXX XXX (space-separated). Never persist — store normalizeVnPhone(value). */
export const formatVnPhone = (value) => {
  const trimmed = normalizeVnPhone(value);
  if (trimmed.length <= 4) return trimmed;
  if (trimmed.length <= 7) return `${trimmed.slice(0, 4)} ${trimmed.slice(4)}`;
  return `${trimmed.slice(0, 4)} ${trimmed.slice(4, 7)} ${trimmed.slice(7)}`;
};
