import { createContext } from 'react';

/**
 * RegradeContext — provided by Examp/index.jsx when isRegradeMode is true.
 *
 * In review mode the teacher can see student answers highlighted correct/incorrect.
 * When isRegrade is true (mode=review URL param), the teacher is also editing the
 * exam's answer keys inline.  Student inputs remain read-only in review mode;
 * only the answer-key editor fields (rendered by AnswerKeyEditor) become editable.
 *
 * Shape:
 *   {
 *     isRegrade: boolean,         // true when in regrade mode
 *     keyEdits: object,           // { [sectionKey]: { [questionId]: patchObj } }
 *     setKeyEdit: function,       // (sectionKey, questionId, patch) => void
 *   }
 */
const RegradeContext = createContext({
  isRegrade: false,
  keyEdits: {},
  setKeyEdit: () => {},
});

export default RegradeContext;
